css:
@property --ale-course-p { syntax: '<number>'; inherits: true; initial-value: 0; }

.ale-course {
  /* re-theme with these four */
  --ale-course-paper: oklch(0.968 0.012 84);
  --ale-course-ink: oklch(0.24 0.018 60);
  --ale-course-accent: oklch(0.6 0.185 34);
  --ale-course-stage: oklch(0.993 0.005 90);
  /* derived */
  --ale-course-side: color-mix(in oklch, var(--ale-course-paper) 93%, var(--ale-course-ink));
  --ale-course-line: color-mix(in oklch, var(--ale-course-ink) 11%, transparent);
  --ale-course-line2: color-mix(in oklch, var(--ale-course-ink) 20%, transparent);
  --ale-course-mute: color-mix(in oklch, var(--ale-course-ink) 62%, var(--ale-course-paper));
  --ale-course-faint: color-mix(in oklch, var(--ale-course-ink) 36%, var(--ale-course-paper));
  --ale-course-hover: color-mix(in oklch, var(--ale-course-ink) 6%, transparent);
  --ale-course-tint: color-mix(in oklch, var(--ale-course-accent) 12%, var(--ale-course-paper));
  --ale-course-on: oklch(0.99 0.01 80);
  --ale-course-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-course-serif: ui-serif, "New York", Charter, Georgia, serif;
  --ale-course-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-course-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-course-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-course-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-course-paper); color: var(--ale-course-ink); color-scheme: light;
  accent-color: var(--ale-course-accent);
  font: 13px/1.45 var(--ale-course-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-course-accent); outline-offset: 2px; }
  & button, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h1, & h2, & h3, & h4, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; font: inherit; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg text { stroke: none; fill: currentColor; font: 700 7px var(--ale-course-sans); }
  & kbd { font: 600 10px/1 var(--ale-course-mono); padding: 3px 5px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--ale-course-line2); border-bottom-width: 2px; border-radius: 5px; background: var(--ale-course-stage); color: var(--ale-course-mute); }
}

.ale-course .ale-course-app {
  height: 100%; display: grid;
  grid-template-columns: 264px minmax(0, 1fr) 300px;
  grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "side main panel" "nav nav nav";
}

/* ── shared bits ─────────────────────────────── */
.ale-course .ale-course-ib {
  display: grid; place-items: center; width: 32px; height: 32px; border: 0; border-radius: 9px; background: none; color: var(--ale-course-mute);
  transition: background .18s, color .18s, transform .25s var(--ale-course-spring);
  &:hover:not(:disabled) { background: var(--ale-course-hover); color: var(--ale-course-ink); }
  &:active:not(:disabled) { transform: scale(.92); }
}

/* ── sidebar ─────────────────────────────── */
.ale-course .ale-course-side {
  grid-area: side; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0;
  background: var(--ale-course-side); border-right: 1px solid var(--ale-course-line);
}
.ale-course .ale-course-brand {
  display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center; padding: 18px 16px 16px 18px;
  border-bottom: 1px solid var(--ale-course-line);
}
.ale-course .ale-course-brandtx {
  min-width: 0;
  & p { font-size: 10px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-course-accent); }
  & h2 { font: 600 19px/1.15 var(--ale-course-serif); letter-spacing: -.01em; margin-top: 2px; text-wrap: balance; }
  & span { display: block; margin-top: 3px; font-size: 11.5px; color: var(--ale-course-mute); font-variant-numeric: tabular-nums; }
}
.ale-course .ale-course-closeside { display: none; align-self: start; }
.ale-course .ale-course-ring {
  position: relative; width: 48px; height: 48px; display: grid; place-items: center;
  transition: --ale-course-p .9s var(--ale-course-ease);
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); stroke-width: 4; }
  & circle:first-child { stroke: var(--ale-course-line2); }
  & circle:last-child { stroke: var(--ale-course-accent); stroke-dasharray: calc(var(--ale-course-p) * 1) 100; }
  & b { font: 700 11px/1 var(--ale-course-sans); font-variant-numeric: tabular-nums; }
}

.ale-course .ale-course-outline { overflow: auto; padding: 8px 8px 16px; overscroll-behavior: contain; scrollbar-width: thin; }
.ale-course .ale-course-mod {
  & + & { margin-top: 4px; }
}
.ale-course .ale-course-modh {
  width: 100%; display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 8px; border: 0; background: none; text-align: left;
  padding: 10px 10px 6px; border-radius: 8px;
  & span { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--ale-course-mute); }
  & small { font: 600 11px var(--ale-course-mono); color: var(--ale-course-faint); font-variant-numeric: tabular-nums; }
  & svg { width: 14px; height: 14px; color: var(--ale-course-faint); transition: transform .3s var(--ale-course-ease); }
  &[aria-expanded="false"] svg { transform: rotate(-90deg); }
  &:hover { background: var(--ale-course-hover); }
}
.ale-course .ale-course-modbody {
  display: grid; grid-template-rows: 1fr; transition: grid-template-rows .35s var(--ale-course-ease), opacity .25s;
  & > ol { overflow: hidden; min-height: 0; }
}
.ale-course .ale-course-modh[aria-expanded="false"] + .ale-course-modbody { grid-template-rows: 0fr; opacity: 0; }

.ale-course .ale-course-les {
  width: 100%; display: grid; grid-template-columns: 22px 1fr auto; gap: 10px; align-items: center; text-align: left;
  border: 0; background: none; padding: 8px 10px; border-radius: 10px; position: relative;
  transition: background .18s;
  & .ale-course-st { width: 22px; height: 22px; display: grid; place-items: center; border-radius: 50%; position: relative; }
  & .ale-course-st svg { width: 22px; height: 22px; }
  & .ale-course-lt { min-width: 0; }
  & .ale-course-lt b { display: block; font-weight: 560; font-size: 13px; line-height: 1.25; text-wrap: pretty; }
  & .ale-course-lt span { font-size: 11px; color: var(--ale-course-mute); }
  & time { font: 500 11px var(--ale-course-mono); color: var(--ale-course-faint); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--ale-course-hover); }
  &[aria-current="true"] { background: var(--ale-course-stage); box-shadow: 0 1px 0 var(--ale-course-line), 0 0 0 1px var(--ale-course-line); }
  &[aria-current="true"]::before { content: ""; position: absolute; left: -8px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--ale-course-accent); }
}
.ale-course .ale-course-st {
  & .ale-course-pr { transform: rotate(-90deg); stroke-width: 2.2; }
  & .ale-course-pr circle:first-child { stroke: var(--ale-course-line2); }
  & .ale-course-pr circle:last-child { stroke: var(--ale-course-accent); transition: stroke-dasharray .4s var(--ale-course-ease); }
  &.is-done { background: var(--ale-course-ink); color: var(--ale-course-paper); }
  &.is-done svg { width: 13px; height: 13px; stroke-width: 2.6; }
}

.ale-course .ale-course-teach {
  display: flex; align-items: center; gap: 10px; padding: 12px 18px 14px; border-top: 1px solid var(--ale-course-line);
  & p { display: grid; font-size: 12px; line-height: 1.3; }
  & p span { color: var(--ale-course-mute); font-size: 11px; }
}
.ale-course .ale-course-av {
  width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; flex: none;
  background: var(--ale-course-tint); color: var(--ale-course-accent); font: 700 11px var(--ale-course-sans); letter-spacing: .04em;
}

/* ── main ─────────────────────────────── */
.ale-course .ale-course-main { grid-area: main; display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; }
.ale-course .ale-course-top {
  display: flex; align-items: center; gap: 10px; padding: 12px 18px 12px 22px; border-bottom: 1px solid var(--ale-course-line); min-width: 0;
}
.ale-course .ale-course-openside { display: none; }
.ale-course .ale-course-crumb {
  flex: 1; min-width: 0;
  & p { font-size: 11px; color: var(--ale-course-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & h1 { font: 600 clamp(16px, 1.2cqi + 6px, 21px)/1.2 var(--ale-course-serif); letter-spacing: -.012em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ale-course .ale-course-topact { display: flex; align-items: center; gap: 4px; }
.ale-course .ale-course-done {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px 0 10px; margin: 0 4px;
  border: 1px solid var(--ale-course-line2); border-radius: 999px; background: var(--ale-course-stage); font-weight: 600; font-size: 12px;
  transition: background .2s, color .2s, border-color .2s;
  & svg { width: 15px; height: 15px; stroke-width: 2.4; stroke-dasharray: 22; opacity: .35; }
  &:hover { border-color: var(--ale-course-ink); }
  &:hover svg { opacity: .7; }
  &[aria-pressed="true"] { background: var(--ale-course-ink); color: var(--ale-course-paper); border-color: var(--ale-course-ink); }
  &[aria-pressed="true"] svg { opacity: 1; animation: ale-course-draw .5s var(--ale-course-ease) both; }
}

.ale-course .ale-course-scroll { overflow: auto; overscroll-behavior: contain; padding: 18px 22px 22px; scrollbar-width: thin; }

/* ── stage ─────────────────────────────── */
.ale-course .ale-course-stage {
  --ale-course-v: 0;
  position: relative; aspect-ratio: 16 / 9; max-height: 330px; width: 100%; margin-inline: auto;
  container-type: inline-size; overflow: hidden; border-radius: 14px;
  background:
    radial-gradient(120% 80% at 50% 0%, color-mix(in oklch, var(--ale-course-stage) 100%, white) 0%, var(--ale-course-stage) 60%),
    var(--ale-course-stage);
  box-shadow: 0 0 0 1px var(--ale-course-line), 0 18px 40px -24px color-mix(in oklch, var(--ale-course-ink) 45%, transparent);
}
.ale-course .ale-course-spec {
  position: absolute; inset: 40px 6cqi 46px; display: grid; place-items: center;
  clip-path: inset(0 0 0 0); transition: clip-path .55s var(--ale-course-ease), opacity .35s;
  @starting-style { clip-path: inset(0 0 0 100%); opacity: 0; }
}
.ale-course .ale-course-chip {
  position: absolute; left: 16px; top: 14px; display: flex; gap: 8px; align-items: baseline;
  font: 700 9.5px/1 var(--ale-course-sans); letter-spacing: .14em; text-transform: uppercase; color: var(--ale-course-mute);
  & b { color: var(--ale-course-accent); }
}
.ale-course .ale-course-read {
  position: absolute; right: 16px; top: 11px; padding: 4px 8px; border-radius: 6px;
  font: 600 11px/1.2 var(--ale-course-mono); color: var(--ale-course-accent); background: var(--ale-course-tint); font-variant-numeric: tabular-nums;
}
.ale-course .ale-course-cap {
  position: absolute; left: 50%; bottom: 12px; translate: -50% 0; max-width: 88%; width: max-content;
  padding: 6px 12px; border-radius: 8px; background: color-mix(in oklch, var(--ale-course-ink) 86%, transparent); color: var(--ale-course-on);
  font-size: clamp(10.5px, 1.9cqi, 13px); line-height: 1.35; text-align: center; text-wrap: balance;
  transition: opacity .25s, translate .3s var(--ale-course-ease);
  &:empty, &.is-off { opacity: 0; translate: -50% 6px; }
}

/* specimens */
.ale-course .ale-course-sp { font-family: var(--ale-course-serif); color: var(--ale-course-ink); }
.ale-course .ale-course-sp-anat {
  position: relative; font-size: 10.5cqi; line-height: 1; letter-spacing: -.01em; padding: 0 1.2em;
  & .ale-course-glyphs { position: relative; z-index: 1; }
  & i {
    --o: clamp(0, calc(var(--ale-course-v) - var(--n) + 1), 1);
    position: absolute; left: 1.2em; right: 0; height: 0; border-top: 1.5px solid var(--ale-course-accent);
    top: calc(var(--y) * 1em); opacity: var(--o); transform: scaleX(var(--o)); transform-origin: left;
    transition: opacity .2s, transform .2s;
  }
  & i:nth-of-type(3), & i:nth-of-type(4), & i:nth-of-type(5) { border-top-style: dashed; border-top-color: color-mix(in oklch, var(--ale-course-accent) 70%, var(--ale-course-ink)); }
  & i span {
    position: absolute; right: 0; bottom: 3px; font: 700 max(8px, 1.5cqi)/1 var(--ale-course-sans); letter-spacing: .1em; text-transform: uppercase;
    color: var(--ale-course-accent); white-space: nowrap;
  }
  & i:nth-of-type(3) { left: 0; right: 1.2em; }
  & i:nth-of-type(3) span { right: auto; left: 0; }
  & i:nth-of-type(5) span { bottom: auto; top: 4px; }
  & .ale-course-xband {
    position: absolute; left: 1.2em; right: 1.2em; top: calc(var(--ale-course-base) * 1em - var(--ale-course-xh) * 1em); height: calc(var(--ale-course-xh) * 1em);
    background: color-mix(in oklch, var(--ale-course-accent) 9%, transparent); opacity: clamp(0, calc(var(--ale-course-v) - 1), 1); transition: opacity .2s;
  }
}
.ale-course .ale-course-sp-measure {
  display: grid; justify-items: start; gap: 10px; font-size: max(5px, 1.5cqi);
  & p { inline-size: calc(var(--ale-course-v) * 1ch); line-height: 1.55; text-wrap: pretty; hyphens: auto; transition: inline-size .12s linear; }
  & .ale-course-ruler {
    position: relative; inline-size: 96ch; height: 14px; border-top: 1px solid var(--ale-course-line2);
    background: linear-gradient(to right, transparent 45ch, color-mix(in oklch, oklch(0.62 0.13 150) 22%, transparent) 45ch 75ch, transparent 75ch);
  }
  & .ale-course-ruler i {
    position: absolute; top: -5px; left: calc(var(--ale-course-v) * 1ch); width: 2px; height: 18px; translate: -1px 0; border-radius: 2px; background: var(--ale-course-accent);
    transition: left .12s linear;
  }
  /* the span keeps the paragraph's font so its ch matches; only the inner label changes face */
  & .ale-course-ruler span { position: absolute; top: 4px; translate: -50% 0; }
  & .ale-course-ruler em { font: 600 max(7px, 1.3cqi) var(--ale-course-mono); font-style: normal; color: var(--ale-course-mute); }
}
.ale-course .ale-course-sp-lead {
  font-size: max(9px, 2.75cqi); max-inline-size: 54ch;
  & p {
    line-height: var(--ale-course-v); text-wrap: pretty;
    background: repeating-linear-gradient(to bottom, transparent 0 calc(var(--ale-course-v) * 1em - 1px), color-mix(in oklch, var(--ale-course-accent) 30%, transparent) calc(var(--ale-course-v) * 1em - 1px) calc(var(--ale-course-v) * 1em));
    background-position: 0 calc(var(--ale-course-v) * -0.22em);
  }
}
.ale-course .ale-course-sp-track {
  display: grid; gap: 2.4cqi; justify-items: center; text-align: center; font-family: var(--ale-course-sans);
  & h4 { margin: 0; font-size: 5.6cqi; font-weight: 750; text-transform: uppercase; letter-spacing: calc(var(--ale-course-v) * 1em); line-height: 1; }
  & small { font-size: max(8px, 1.6cqi); font-weight: 700; text-transform: uppercase; letter-spacing: calc(var(--ale-course-v) * 1em); color: var(--ale-course-accent); }
  & p { font-family: var(--ale-course-serif); font-size: max(9px, 2.4cqi); color: var(--ale-course-mute); }
}
.ale-course .ale-course-sp-scale {
  display: grid; gap: .9cqi; justify-items: start; width: 100%;
  & div { display: grid; grid-template-columns: 9cqi 1fr; align-items: baseline; gap: 2cqi; width: 100%; }
  & code { font: 600 max(7.5px, 1.35cqi) var(--ale-course-mono); color: var(--ale-course-accent); text-align: right; font-variant-numeric: tabular-nums; }
  & span { font-size: calc(var(--px) * 0.115cqi); line-height: 1.05; letter-spacing: -.012em; white-space: nowrap; transition: font-size .12s linear; }
}
.ale-course .ale-course-sp-rhythm {
  --u: calc(var(--ale-course-v) * 0.135cqi);
  width: 72%; padding: 0 2cqi;
  background: repeating-linear-gradient(to bottom, transparent 0 calc(var(--u) - 1px), color-mix(in oklch, oklch(0.6 0.12 230) 32%, transparent) calc(var(--u) - 1px) var(--u));
  /* lines sit on the body baseline; the heading is nudged so its baseline lands on the same grid */
  background-position: 0 calc(var(--u) * (0.5 + var(--ale-course-k, 0.33) * 0.62) - var(--u));
  & h4 { margin: 0; position: relative; top: calc(var(--u) * (0.5 - var(--ale-course-k, 0.33) * 0.68)); font-size: calc(var(--u) * 1.3); line-height: calc(var(--u) * 2); font-weight: 600; }
  & p { margin: 0 0 var(--u); font-size: calc(var(--u) * 0.62); line-height: var(--u); text-wrap: pretty; }
}
.ale-course .ale-course-sp-pair {
  display: grid; gap: 2cqi; max-inline-size: 80%;
  & h4 { margin: 0; font-size: 5.4cqi; line-height: 1.05; font-weight: 650; letter-spacing: -.02em; text-wrap: balance; }
  & p { font-family: var(--ale-course-sans); font-size: max(8px, 1.9cqi); line-height: 1.5; color: var(--ale-course-mute); text-wrap: pretty; }
  &[data-face="0"] h4 { font-family: var(--ale-course-sans); }
  &[data-face="1"] h4 { font-family: var(--ale-course-serif); font-weight: 600; }
  &[data-face="2"] h4 { font-family: var(--ale-course-mono); font-weight: 600; letter-spacing: -.04em; }
  &[data-face="3"] h4 { font-family: ui-rounded, "SF Pro Rounded", var(--ale-course-sans); font-weight: 700; }
}
.ale-course .ale-course-sp-fluid {
  width: 100%; display: grid; gap: 8px; justify-items: center;
  & .ale-course-frame {
    inline-size: calc(var(--ale-course-v) / 1440 * 100%); border: 1.5px solid var(--ale-course-ink); border-radius: 8px; overflow: hidden; background: white;
    transition: inline-size .12s linear;
  }
  & .ale-course-frame::before { content: ""; display: block; height: 12px; background: radial-gradient(circle at 8px 6px, var(--ale-course-line2) 2.5px, transparent 3px), radial-gradient(circle at 17px 6px, var(--ale-course-line2) 2.5px, transparent 3px), var(--ale-course-line); border-bottom: 1px solid var(--ale-course-line2); }
  & .ale-course-fb { padding: 2cqi 2.4cqi 2.4cqi; }
  & h4 { margin: 0; font-size: calc(var(--ale-course-fs) * 88cqi / 1440); line-height: 1.05; font-weight: 650; letter-spacing: -.02em; white-space: nowrap; overflow: hidden; }
  & p { margin-top: 1cqi; font-family: var(--ale-course-sans); font-size: max(7px, 1.25cqi); color: var(--ale-course-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ale-course-fb i { display: block; height: 1cqi; margin-top: 1cqi; border-radius: 2px; background: var(--ale-course-line); }
  & .ale-course-fb i + i { width: 72%; }
  & code { font: 600 max(7.5px, 1.4cqi) var(--ale-course-mono); color: var(--ale-course-mute); }
}
.ale-course .ale-course-sp-nums {
  width: min(100%, 64cqi); font-family: var(--ale-course-sans);
  & table { width: 100%; border-collapse: collapse; font-size: max(8.5px, 2.1cqi); font-variant-numeric: proportional-nums; }
  &[data-tab="1"] table { font-variant-numeric: tabular-nums; }
  & th { text-align: left; font-size: .72em; letter-spacing: .1em; text-transform: uppercase; color: var(--ale-course-mute); font-weight: 700; padding-bottom: .5em; border-bottom: 1.5px solid var(--ale-course-ink); }
  & th:not(:first-child), & td:not(:first-child) { text-align: right; }
  & td { padding: .42em 0; border-bottom: 1px solid var(--ale-course-line); }
  & tr:last-child td { font-weight: 700; border-bottom: 0; }
}

/* end-of-lesson card */
.ale-course .ale-course-end {
  position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 10px; text-align: center; padding: 20px;
  background: color-mix(in oklch, var(--ale-course-stage) 82%, transparent); backdrop-filter: blur(6px);
  transition: opacity .35s, scale .5s var(--ale-course-spring);
  @starting-style { opacity: 0; scale: .97; }
  & p { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-course-accent); }
  & h3 { font: 600 clamp(17px, 3.2cqi, 24px)/1.15 var(--ale-course-serif); text-wrap: balance; max-width: 26ch; }
  & div { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; margin-top: 4px; }
  & button { height: 34px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--ale-course-line2); background: var(--ale-course-stage); font-weight: 600; }
  & button.is-pri { background: var(--ale-course-ink); color: var(--ale-course-paper); border-color: var(--ale-course-ink); }
  & button:hover { filter: brightness(1.08); }
}

/* ── transport ─────────────────────────────── */
.ale-course .ale-course-bar { margin-top: 12px; display: grid; gap: 6px; }
.ale-course .ale-course-scrub {
  position: relative; height: 26px; cursor: pointer; touch-action: none; border-radius: 6px;
  --ale-course-t: 0; --ale-course-w: 0;
  & .ale-course-track { position: absolute; left: 0; right: 0; top: 10px; height: 6px; }
  & .ale-course-segs { position: absolute; inset: 0; }
  & .ale-course-segs i { position: absolute; top: 0; bottom: 0; border-radius: 3px; background: var(--ale-course-line2); }
  & .ale-course-watch, & .ale-course-fill {
    position: absolute; inset: 0; border-radius: 3px; transform-origin: left; pointer-events: none;
    -webkit-mask: var(--ale-course-segmask); mask: var(--ale-course-segmask);
  }
  & .ale-course-watch { background: color-mix(in oklch, var(--ale-course-ink) 22%, transparent); transform: scaleX(var(--ale-course-w)); }
  & .ale-course-fill { background: var(--ale-course-accent); transform: scaleX(var(--ale-course-t)); }
  & .ale-course-thumb {
    position: absolute; top: 6px; left: calc(var(--ale-course-t) * 100%); width: 14px; height: 14px; translate: -7px 0; border-radius: 50%;
    background: var(--ale-course-stage); box-shadow: 0 0 0 2.5px var(--ale-course-accent), 0 2px 6px -1px color-mix(in oklch, var(--ale-course-ink) 40%, transparent);
    pointer-events: none; transition: scale .2s var(--ale-course-spring);
  }
  &:hover .ale-course-thumb, &.is-drag .ale-course-thumb { scale: 1.25; }
  & .ale-course-tip {
    position: absolute; bottom: calc(100% + 4px); left: var(--ale-course-hx, 0); translate: -50% 4px; padding: 5px 8px; border-radius: 7px; white-space: nowrap; pointer-events: none;
    background: var(--ale-course-ink); color: var(--ale-course-on); font-size: 11px; opacity: 0; transition: opacity .15s, translate .2s var(--ale-course-ease);
    & b { font: 600 11px var(--ale-course-mono); color: color-mix(in oklch, var(--ale-course-accent) 55%, white); margin-right: 6px; font-variant-numeric: tabular-nums; }
  }
  &:hover .ale-course-tip, &.is-drag .ale-course-tip { opacity: 1; translate: -50% 0; }
}
.ale-course .ale-course-pins { position: absolute; inset: 0; pointer-events: none; }
.ale-course .ale-course-pin {
  position: absolute; top: -3px; left: calc(var(--x) * 100%); translate: -50% 0; width: 14px; height: 13px; border: 0; padding: 0; background: none; pointer-events: auto;
  &::before { content: ""; position: absolute; left: 3px; top: 0; width: 8px; height: 8px; border-radius: 50% 50% 50% 0; rotate: -45deg; background: var(--ale-course-ink); transition: scale .25s var(--ale-course-spring), background .15s; }
  &:hover::before { scale: 1.35; background: var(--ale-course-accent); }
}
.ale-course .ale-course-ctrls { display: flex; align-items: center; gap: 4px; }
.ale-course .ale-course-play {
  width: 38px; height: 38px; border-radius: 50%; border: 0; display: grid; place-items: center; margin-right: 2px;
  background: var(--ale-course-ink); color: var(--ale-course-paper); transition: transform .3s var(--ale-course-spring), background .2s;
  & svg { width: 18px; height: 18px; fill: currentColor; stroke-width: 1.2; }
  &:hover { background: color-mix(in oklch, var(--ale-course-ink) 85%, var(--ale-course-accent)); }
  &:active { transform: scale(.9); }
}
.ale-course .ale-course-time { font: 600 12px var(--ale-course-mono); font-variant-numeric: tabular-nums; color: var(--ale-course-mute); margin-left: 6px; white-space: nowrap; & b { color: var(--ale-course-ink); } }
.ale-course .ale-course-flex { flex: 1; }
.ale-course .ale-course-pill {
  height: 28px; min-width: 40px; padding: 0 9px; border-radius: 7px; border: 1px solid var(--ale-course-line2); background: none;
  font: 700 11px var(--ale-course-mono); font-variant-numeric: tabular-nums; color: var(--ale-course-mute); transition: background .15s, color .15s, border-color .15s;
  &:hover { color: var(--ale-course-ink); border-color: var(--ale-course-ink); }
  &[aria-pressed="true"] { background: var(--ale-course-ink); border-color: var(--ale-course-ink); color: var(--ale-course-paper); }
}

/* chapters */
.ale-course .ale-course-chaps { margin-top: 18px; }
.ale-course .ale-course-h3 {
  display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 6px;
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-course-mute); }
  & span { font-size: 11px; color: var(--ale-course-faint); }
}
.ale-course .ale-course-chap {
  width: 100%; display: grid; grid-template-columns: 52px 1fr auto; align-items: center; gap: 10px; text-align: left;
  border: 0; background: none; padding: 9px 10px; border-radius: 9px; position: relative; overflow: hidden;
  & time { font: 600 11.5px var(--ale-course-mono); color: var(--ale-course-mute); font-variant-numeric: tabular-nums; }
  & b { font-weight: 550; }
  & small { font-size: 11px; color: var(--ale-course-faint); font-variant-numeric: tabular-nums; }
  &::after { content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: 100%; background: var(--ale-course-accent); transform: scaleX(var(--f, 0)); transform-origin: left; }
  &:hover { background: var(--ale-course-hover); }
  &[aria-current="true"] { background: var(--ale-course-tint); & time { color: var(--ale-course-accent); } }
}

/* ── side panel ─────────────────────────────── */
.ale-course .ale-course-panel { grid-area: panel; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; border-left: 1px solid var(--ale-course-line); background: var(--ale-course-side); }
.ale-course .ale-course-tabs {
  display: flex; gap: 2px; padding: 10px 12px 0; border-bottom: 1px solid var(--ale-course-line);
  & button { position: relative; border: 0; background: none; padding: 10px 10px 12px; font-weight: 600; color: var(--ale-course-mute); display: inline-flex; gap: 6px; align-items: center; }
  & button b { font: 700 10px/1 var(--ale-course-mono); padding: 3px 5px; border-radius: 5px; background: var(--ale-course-line); color: var(--ale-course-mute); font-variant-numeric: tabular-nums; }
  & button::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--ale-course-ink); transform: scaleX(0); transition: transform .3s var(--ale-course-ease); }
  & button[aria-selected="true"] { color: var(--ale-course-ink); }
  & button[aria-selected="true"]::after { transform: scaleX(1); }
  & button:hover { color: var(--ale-course-ink); }
}
.ale-course .ale-course-pane { min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.ale-course .ale-course-follow {
  position: sticky; top: 0; z-index: 1; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 14px;
  background: color-mix(in oklch, var(--ale-course-side) 92%, transparent); backdrop-filter: blur(6px); font-size: 11px; color: var(--ale-course-mute);
}
.ale-course .ale-course-sw {
  display: inline-flex; align-items: center; gap: 7px; border: 0; background: none; padding: 2px; font-size: 11.5px; font-weight: 600; color: var(--ale-course-ink);
  & i { width: 26px; height: 15px; border-radius: 999px; background: var(--ale-course-line2); position: relative; transition: background .2s; }
  & i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 11px; height: 11px; border-radius: 50%; background: white; box-shadow: 0 1px 2px color-mix(in oklch, var(--ale-course-ink) 30%, transparent); transition: translate .3s var(--ale-course-spring); }
  &[aria-checked="true"] i { background: var(--ale-course-accent); }
  &[aria-checked="true"] i::after { translate: 11px 0; }
}
.ale-course .ale-course-lines { padding: 2px 8px 18px; }
.ale-course .ale-course-line {
  width: 100%; display: grid; grid-template-columns: 38px 1fr; gap: 8px; text-align: left; border: 0; background: none; padding: 7px 8px; border-radius: 8px;
  color: var(--ale-course-mute); transition: color .25s, background .25s;
  & time { font: 600 10.5px/1.75 var(--ale-course-mono); color: var(--ale-course-faint); font-variant-numeric: tabular-nums; }
  & span { font-size: 12.5px; line-height: 1.5; text-wrap: pretty; }
  &:hover { background: var(--ale-course-hover); color: var(--ale-course-ink); }
  &.is-past { color: color-mix(in oklch, var(--ale-course-ink) 78%, var(--ale-course-paper)); }
  &[aria-current="true"] { color: var(--ale-course-ink); background: var(--ale-course-stage); box-shadow: 0 0 0 1px var(--ale-course-line); }
  &[aria-current="true"] time { color: var(--ale-course-accent); }
}

/* notes */
.ale-course .ale-course-compose {
  margin: 12px; padding: 10px; border-radius: 12px; background: var(--ale-course-stage); box-shadow: 0 0 0 1px var(--ale-course-line);
  transition: box-shadow .2s;
  &:focus-within { box-shadow: 0 0 0 1.5px var(--ale-course-accent); }
  & label { display: block; font-size: 11px; font-weight: 700; color: var(--ale-course-mute); margin-bottom: 4px; }
  & label span { font: 600 11px var(--ale-course-mono); color: var(--ale-course-accent); font-variant-numeric: tabular-nums; }
  & textarea { width: 100%; resize: none; border: 0; outline: 0; background: none; font-size: 13px; line-height: 1.45; padding: 2px 0; }
  & textarea::placeholder { color: var(--ale-course-faint); }
}
.ale-course .ale-course-cfoot { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 11px; color: var(--ale-course-faint); }
.ale-course .ale-course-save {
  height: 28px; padding: 0 12px; border: 0; border-radius: 999px; background: var(--ale-course-accent); color: white; font-weight: 650; font-size: 12px;
  transition: transform .25s var(--ale-course-spring), opacity .2s;
  &:active:not(:disabled) { transform: scale(.94); }
}
.ale-course .ale-course-scope {
  display: flex; gap: 2px; margin: 0 12px 6px; padding: 2px; border-radius: 9px; background: var(--ale-course-line);
  & button { flex: 1; border: 0; background: none; height: 26px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--ale-course-mute); }
  & button[aria-checked="true"] { background: var(--ale-course-stage); color: var(--ale-course-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--ale-course-ink) 14%, transparent); }
}
.ale-course .ale-course-nlist { padding: 4px 12px 18px; display: grid; gap: 8px; }
.ale-course .ale-course-ngroup { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--ale-course-faint); padding: 8px 2px 0; }
.ale-course .ale-course-note {
  --i: 0;
  display: grid; grid-template-columns: auto 1fr auto; gap: 4px 8px; align-items: start; padding: 10px; border-radius: 10px;
  background: var(--ale-course-stage); box-shadow: 0 0 0 1px var(--ale-course-line);
  animation: ale-course-in .45s var(--ale-course-ease) both; animation-delay: calc(var(--i) * 40ms);
  & p { grid-column: 1 / -1; font-size: 12.5px; line-height: 1.45; text-wrap: pretty; }
  & .ale-course-ts { border: 0; background: var(--ale-course-tint); color: var(--ale-course-accent); font: 700 11px var(--ale-course-mono); padding: 3px 7px; border-radius: 6px; font-variant-numeric: tabular-nums; }
  & .ale-course-ts:hover { background: var(--ale-course-accent); color: white; }
  & .ale-course-nl { font-size: 11px; color: var(--ale-course-faint); align-self: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ale-course-del { width: 26px; height: 26px; margin: -4px -4px 0 0; }
  & .ale-course-del svg { width: 15px; height: 15px; }
  &.is-new { animation: ale-course-pop .6s var(--ale-course-spring) both; }
}
.ale-course .ale-course-empty { padding: 26px 14px; text-align: center; color: var(--ale-course-faint); font-size: 12px; text-wrap: balance; }
@keyframes ale-course-draw { from { stroke-dashoffset: 22; } to { stroke-dashoffset: 0; } }
@keyframes ale-course-in { from { opacity: 0; transform: translateY(6px); } }
@keyframes ale-course-pop { from { opacity: 0; transform: scale(.94); filter: blur(3px); } }

/* ── nav (narrow only) ─────────────────────────────── */
.ale-course .ale-course-nav {
  grid-area: nav; display: none; border-top: 1px solid var(--ale-course-line); background: var(--ale-course-side); padding: 4px 6px 6px;
  & button { flex: 1; border: 0; background: none; display: grid; justify-items: center; gap: 2px; padding: 6px 4px; border-radius: 10px; font-size: 11px; font-weight: 600; color: var(--ale-course-mute); }
  & button svg { width: 20px; height: 20px; }
  & button[aria-selected="true"] { color: var(--ale-course-accent); background: var(--ale-course-tint); }
}

/* ── overlays ─────────────────────────────── */
.ale-course .ale-course-scrim {
  position: absolute; inset: 0; z-index: 20; background: color-mix(in oklch, var(--ale-course-ink) 28%, transparent);
  opacity: 0; visibility: hidden; transition: opacity .3s, visibility 0s .3s; cursor: pointer;
}
.ale-course .ale-course-keys {
  position: absolute; z-index: 30; right: 16px; top: 58px; width: min(330px, calc(100% - 32px)); padding: 14px 16px 16px; border-radius: 14px;
  background: var(--ale-course-stage); box-shadow: 0 0 0 1px var(--ale-course-line), 0 24px 50px -18px color-mix(in oklch, var(--ale-course-ink) 45%, transparent);
  transition: opacity .25s, transform .35s var(--ale-course-spring); transform-origin: top right;
  @starting-style { opacity: 0; transform: scale(.94) translateY(-6px); }
  & header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
  & h3 { font: 600 16px var(--ale-course-serif); }
  & dl { display: grid; grid-template-columns: auto 1fr; gap: 8px 14px; align-items: center; font-size: 12.5px; }
  & dt { white-space: nowrap; }
  & dd { color: var(--ale-course-mute); }
}
.ale-course .ale-course-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; translate: -50% 16px; display: flex; align-items: center; gap: 12px;
  padding: 8px 8px 8px 14px; border-radius: 12px; background: var(--ale-course-ink); color: var(--ale-course-on); font-size: 12.5px;
  box-shadow: 0 16px 34px -14px color-mix(in oklch, var(--ale-course-ink) 70%, transparent);
  opacity: 0; visibility: hidden; transition: opacity .25s, translate .4s var(--ale-course-spring), visibility 0s .4s;
  & button { border: 0; border-radius: 8px; padding: 5px 10px; background: color-mix(in oklch, var(--ale-course-on) 14%, transparent); color: var(--ale-course-on); font-weight: 650; font-size: 12px; }
  & button:hover { background: color-mix(in oklch, var(--ale-course-on) 24%, transparent); }
  &.is-on { opacity: 1; visibility: visible; translate: -50% 0; transition: opacity .25s, translate .4s var(--ale-course-spring), visibility 0s; }
  &:not(.has-undo) button { display: none; }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 1080px) {
  .ale-course .ale-course-app { grid-template-columns: 236px minmax(0, 1fr) 272px; }
}
@container (max-width: 959px) {
  .ale-course .ale-course-app { grid-template-columns: minmax(0, 1fr) 280px; grid-template-areas: "main panel" "nav nav"; }
  .ale-course .ale-course-side {
    position: absolute; z-index: 25; left: 0; top: 0; bottom: 0; width: min(300px, 86%);
    box-shadow: 24px 0 50px -30px color-mix(in oklch, var(--ale-course-ink) 60%, transparent);
    transform: translateX(-102%); visibility: hidden; transition: transform .45s var(--ale-course-ease), visibility 0s .45s;
  }
  .ale-course[data-drawer="open"] .ale-course-side { transform: none; visibility: visible; transition: transform .45s var(--ale-course-ease), visibility 0s; }
  .ale-course[data-drawer="open"] .ale-course-scrim { opacity: 1; visibility: visible; transition: opacity .3s, visibility 0s; }
  .ale-course .ale-course-openside, .ale-course .ale-course-closeside { display: grid; }
}
@container (max-width: 759px) {
  .ale-course .ale-course-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; grid-template-areas: "view" "nav"; }
  .ale-course .ale-course-nav { display: flex; }
  .ale-course .ale-course-main, .ale-course .ale-course-panel, .ale-course .ale-course-side { grid-area: view; }
  .ale-course .ale-course-side {
    position: static; width: auto; transform: none; visibility: visible; box-shadow: none; border-right: 0; transition: none;
  }
  .ale-course .ale-course-openside, .ale-course .ale-course-closeside { display: none; }
  .ale-course .ale-course-scrim { display: none; }
  .ale-course .ale-course-panel { border-left: 0; }
  .ale-course:not([data-view="lesson"]) .ale-course-main,
  .ale-course:not([data-view="outline"]) .ale-course-side,
  .ale-course:not([data-view="panel"]) .ale-course-panel { display: none; }
  .ale-course .ale-course-top { padding: 10px 12px 10px 16px; }
  .ale-course .ale-course-scroll { padding: 12px 14px 18px; }
  .ale-course .ale-course-keys { top: 52px; }
}
@container (max-width: 520px) {
  .ale-course .ale-course-done span { display: none; }
  .ale-course .ale-course-done { padding: 0 9px; }
  .ale-course .ale-course-topact [data-act="keys"] { display: none; }
  .ale-course .ale-course-spec { inset: 30px 5cqi 38px; }
  .ale-course .ale-course-chip { left: 10px; top: 10px; }
  .ale-course .ale-course-read { right: 10px; top: 7px; font-size: 10px; }
  .ale-course .ale-course-cap { bottom: 8px; padding: 4px 9px; }
  .ale-course .ale-course-chap { grid-template-columns: 44px 1fr; & small { display: none; } }
}

@media (prefers-reduced-motion: reduce) {
  .ale-course *, .ale-course *::before, .ale-course *::after { animation-duration: 1ms !important; animation-delay: 0s !important; transition-duration: 1ms !important; }
  .ale-course .ale-course-spec { clip-path: none; }
}

