/* Northlight Academy · Type on Screen — course player.
   The lesson "video" is live CSS. Each lesson carries keyframe tracks; the playhead (S.t)
   interpolates them into custom properties on the stage, so scrubbing re-sets the very
   measure, leading or tracking the lesson is about. Transcript, chapters, captions and
   note pins all read the same clock. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmt = s => { s = Math.max(0, Math.floor(s)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
const ICO = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  chev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>',
  trash: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h14M10 7V4.5h4V7M7 7l1 12.5h8L17 7"/></svg>',
  play: '<path d="M8 5.5v13l10.5-6.5z"/>',
  pause: '<path d="M7 5.5h3.4v13H7zM13.6 5.5H17v13h-3.4z"/>',
};

/* ── course data ───────────────────────────────────────── */
const P_MEASURE = 'Measure is felt before it is noticed. When a line runs too long, the eye loses its place on the way back and rereads a line it has already read; when it runs too short, the reader is pulled back to the left edge so often that sentences break into fragments. Somewhere between forty-five and seventy-five characters, reading settles into a rhythm and the page disappears behind the words it carries.';
const P_LEAD = 'Leading is the quiet space between lines. Too little and ascenders crowd the descenders above them; too much and each line drifts away from its neighbours until the paragraph no longer reads as one block. The right amount depends on the measure, the face and the size, which is why it is written as a ratio rather than a distance.';
const MODS = [
  { name: 'Foundations', lessons: [
    { title: 'Anatomy of a letterform', kind: 'anat', dur: 252,
      chapters: [[0, 'Why anatomy matters'], [70, 'Baseline and x-height'], [150, 'Ascenders, descenders, caps'], [215, 'Recap']],
      lines: [[0, 'Before we touch a single setting, we need names for the parts we’ll be adjusting.'], [34, 'Every letter sits on the baseline — the invisible rule your eye tracks along a line.'], [70, 'The x-height is the height of a lowercase x. It decides how big a face feels at a given size.'], [112, 'Two faces at 16 pixels can look a full size apart because their x-heights differ.'], [150, 'Cap height is usually a little shorter than the ascenders of b, d and h.'], [184, 'Descenders drop below the baseline; give them room or lines start to collide.'], [215, 'Baseline, x-height, cap height, ascender, descender — five lines, and the rest of the course hangs on them.']],
      track: [[0, 0], [30, 0], [42, 1], [70, 1], [82, 2], [150, 2], [158, 3], [166, 3], [174, 4], [184, 4], [192, 5], [252, 5]] },
    { title: 'Measure', kind: 'measure', dur: 330,
      chapters: [[0, 'What measure means'], [95, 'Too narrow, too wide'], [200, 'The 45–75 range'], [280, 'Setting it in CSS']],
      lines: [[0, 'Measure is the length of a line of text, counted in characters rather than pixels.'], [48, 'Your eye has to find the start of the next line every time it reaches the end of this one.'], [95, 'Squeeze it under forty characters and the eye jumps back so often that reading turns choppy.'], [150, 'Stretch it past ninety and the return sweep gets lost — you reread the same line twice.'], [200, 'Most body text is comfortable between forty-five and seventy-five characters.'], [245, 'Sixty-six is the number typographers keep coming back to for a single column.'], [280, 'In CSS, set max-inline-size in ch units on the text block, not on the page.'], [310, 'The container can be any width; the paragraph keeps its measure.']],
      track: [[0, 66], [95, 66], [120, 30], [150, 30], [175, 96], [200, 96], [240, 66], [330, 66]] },
