  tick(true);
}
function finish() {
  S.playing = false; S.t = L().dur; S.watched[S.cur] = L().dur;
  setPlaying(false);
  if (!S.done[S.cur]) { S.done[S.cur] = true; renderOutline(); renderDone(); toast('Lesson ' + L().n + ' complete — ' + S.done.filter(Boolean).length + ' of ' + LES.length + ' done'); }
