css:
.ale-cards {
  /* re-theme with these four */
  --ale-cards-bg: oklch(0.205 0.012 55);
  --ale-cards-ink: oklch(0.94 0.012 80);
  --ale-cards-accent: oklch(0.8 0.14 78);
  --ale-cards-paper: oklch(0.955 0.02 88);
  /* derived */
  --ale-cards-panel: color-mix(in oklch, var(--ale-cards-bg) 88%, var(--ale-cards-ink) 4%);
  --ale-cards-raise: color-mix(in oklch, var(--ale-cards-bg) 90%, var(--ale-cards-ink));
  --ale-cards-line: color-mix(in oklch, var(--ale-cards-ink) 10%, transparent);
  --ale-cards-line2: color-mix(in oklch, var(--ale-cards-ink) 18%, transparent);
  --ale-cards-mute: color-mix(in oklch, var(--ale-cards-ink) 60%, var(--ale-cards-bg));
  --ale-cards-faint: color-mix(in oklch, var(--ale-cards-ink) 36%, var(--ale-cards-bg));
  --ale-cards-hover: color-mix(in oklch, var(--ale-cards-ink) 7%, transparent);
  --ale-cards-pink: oklch(0.62 0.16 22);
  --ale-cards-rule: oklch(0.72 0.07 235);
  --ale-cards-cardink: oklch(0.27 0.02 60);
  --ale-cards-again: oklch(0.7 0.17 28);
  --ale-cards-hard: oklch(0.8 0.12 85);
  --ale-cards-good: oklch(0.76 0.14 150);
  --ale-cards-easy: oklch(0.74 0.11 230);
  --ale-cards-new: oklch(0.74 0.11 230);
  --ale-cards-learn: oklch(0.7 0.17 28);
  --ale-cards-rev: oklch(0.76 0.14 150);
  --ale-cards-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-cards-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-cards-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-cards-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-cards-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-cards-bg); color: var(--ale-cards-ink); color-scheme: dark; accent-color: var(--ale-cards-accent);
  font: 13px/1.45 var(--ale-cards-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-cards-accent); outline-offset: 2px; }
  & button, & input, & textarea, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .38; }
  & h1, & h2, & h3, & p, & ul, & ol, & dl, & dd { margin: 0; padding: 0; font: inherit; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--ale-cards-mono); padding: 3px 5px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--ale-cards-line2); border-bottom-width: 2px; border-radius: 5px; color: var(--ale-cards-mute); }
}
.ale-cards .ale-cards-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.ale-cards .ale-cards-app {
  height: 100%; display: grid; grid-template-columns: 236px minmax(0, 1fr) 292px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "decks main stats" "nav nav nav";
}
.ale-cards .ale-cards-ib {
  display: grid; place-items: center; width: 34px; height: 34px; border: 0; border-radius: 10px; background: none; color: var(--ale-cards-mute);
  transition: background .18s, color .18s, transform .25s var(--ale-cards-spring);
  &:hover:not(:disabled) { background: var(--ale-cards-hover); color: var(--ale-cards-ink); }
  &:active:not(:disabled) { transform: scale(.9); }
}

/* ── decks ─────────────────────────────── */
.ale-cards .ale-cards-decks { grid-area: decks; display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto auto; min-height: 0; background: var(--ale-cards-panel); border-right: 1px solid var(--ale-cards-line); }
.ale-cards .ale-cards-brand {
  display: flex; align-items: center; gap: 10px; padding: 18px 16px 14px;
  & p { font-size: 16px; font-weight: 750; letter-spacing: -.01em; }
  & span { display: block; font-size: 11px; color: var(--ale-cards-mute); }
}
.ale-cards .ale-cards-logo { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; background: var(--ale-cards-accent); color: var(--ale-cards-bg); & svg { width: 20px; height: 20px; stroke-width: 2; } }
.ale-cards .ale-cards-dh {
  display: flex; justify-content: space-between; align-items: baseline; padding: 8px 18px 6px;
  & h2 { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-cards-mute); }
  & span { font-size: 10.5px; color: var(--ale-cards-faint); }
}
.ale-cards .ale-cards-dlist { overflow: auto; padding: 0 8px 8px; scrollbar-width: thin; }
.ale-cards .ale-cards-deck {
  display: grid; grid-template-columns: 1fr auto auto; gap: 4px 8px; align-items: center; padding: 10px 10px 10px 12px; border-radius: 11px; cursor: pointer;
  transition: background .18s; position: relative;
  & b { font-weight: 600; font-size: 13px; }
  & small { grid-column: 1 / -1; font-size: 11px; color: var(--ale-cards-faint); }
  & .ale-cards-n { font: 700 12px var(--ale-cards-mono); font-variant-numeric: tabular-nums; min-width: 22px; text-align: right; }
  & .ale-cards-n.is-due { color: var(--ale-cards-rev); }
  & .ale-cards-n.is-new { color: var(--ale-cards-new); }
  & .ale-cards-n.is-zero { color: var(--ale-cards-faint); }
  & .ale-cards-mini { grid-column: 1 / -1; height: 3px; border-radius: 2px; background: var(--ale-cards-line); overflow: hidden; }
  & .ale-cards-mini i { display: block; height: 100%; width: calc(var(--m) * 100%); background: var(--ale-cards-accent); border-radius: inherit; transition: width .6s var(--ale-cards-ease); }
  &:hover { background: var(--ale-cards-hover); }
  &[aria-selected="true"] { background: var(--ale-cards-raise); box-shadow: inset 0 0 0 1px var(--ale-cards-line2); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: -8px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--ale-cards-accent); }
}
.ale-cards .ale-cards-add {
  margin: 4px 12px 10px; height: 36px; display: flex; align-items: center; justify-content: center; gap: 8px; border-radius: 10px;
  border: 1px dashed var(--ale-cards-line2); background: none; color: var(--ale-cards-mute); font-weight: 600;
  & svg { width: 16px; height: 16px; }
  &:hover { border-style: solid; color: var(--ale-cards-ink); background: var(--ale-cards-hover); }
}
.ale-cards .ale-cards-streak {
  display: flex; align-items: center; gap: 10px; padding: 12px 16px 14px; border-top: 1px solid var(--ale-cards-line); font-size: 11.5px; color: var(--ale-cards-mute);
  & svg { width: 22px; height: 22px; color: var(--ale-cards-accent); }
  & b { color: var(--ale-cards-ink); font-variant-numeric: tabular-nums; }
}

/* ── main ─────────────────────────────── */
.ale-cards .ale-cards-main { grid-area: main; display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; }
.ale-cards .ale-cards-top { display: flex; align-items: center; gap: 12px; padding: 14px 16px 12px 22px; border-bottom: 1px solid var(--ale-cards-line); min-width: 0; }
.ale-cards .ale-cards-title {
  flex: 1; min-width: 0;
  & p { font-size: 11px; color: var(--ale-cards-mute); }
  & h1 { font-size: clamp(16px, 1.1cqi + 6px, 20px); font-weight: 700; letter-spacing: -.015em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ale-cards .ale-cards-counts {
  display: flex; gap: 10px; font: 700 13px var(--ale-cards-mono); font-variant-numeric: tabular-nums;
  & span { display: inline-flex; align-items: baseline; gap: 4px; }
  & small { font: 600 10px var(--ale-cards-sans); color: var(--ale-cards-faint); text-transform: uppercase; letter-spacing: .08em; }
  & .is-new { color: var(--ale-cards-new); } & .is-learn { color: var(--ale-cards-learn); } & .is-rev { color: var(--ale-cards-rev); }
  & .is-cur { text-decoration: underline 2px; text-underline-offset: 4px; }
}
.ale-cards .ale-cards-mode {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--ale-cards-line);
  & button { border: 0; background: none; height: 28px; padding: 0 12px; border-radius: 8px; font-weight: 600; font-size: 12px; color: var(--ale-cards-mute); display: inline-flex; align-items: center; gap: 6px; }
  & button kbd { padding: 2px 4px; min-width: 0; font-size: 9px; }
  & button[aria-selected="true"] { background: var(--ale-cards-raise); color: var(--ale-cards-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .3); }
}

/* study */
.ale-cards .ale-cards-study { display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; min-height: 0; }
.ale-cards .ale-cards-prog { height: 3px; background: var(--ale-cards-line); & i { display: block; height: 100%; width: calc(var(--p, 0) * 100%); background: var(--ale-cards-accent); transition: width .6s var(--ale-cards-ease); } }
.ale-cards .ale-cards-desk {
  position: relative; display: grid; place-items: center; padding: 22px 24px 10px; min-height: 0; overflow: hidden;
  background: radial-gradient(70% 70% at 50% 45%, color-mix(in oklch, var(--ale-cards-accent) 7%, transparent), transparent 70%);
}
.ale-cards .ale-cards-stack {
  position: relative; width: min(460px, 100%); aspect-ratio: 5 / 3; max-height: 100%; perspective: 1400px;
  &::before, &::after {
    content: ""; position: absolute; inset: 0; border-radius: 6px; background: color-mix(in oklch, var(--ale-cards-paper) 82%, var(--ale-cards-bg));
    box-shadow: 0 10px 24px -14px oklch(0 0 0 / .7); transition: opacity .4s, transform .5s var(--ale-cards-ease);
  }
  &::before { transform: rotate(-3.2deg) translate(-6px, 8px); }
  &::after { transform: rotate(2.4deg) translate(8px, 4px); background: color-mix(in oklch, var(--ale-cards-paper) 90%, var(--ale-cards-bg)); }
  &[data-depth="1"]::before { opacity: 0; }
  &[data-depth="0"]::before, &[data-depth="0"]::after { opacity: 0; transform: none; }
}
.ale-cards .ale-cards-card {
  position: absolute; inset: 0; z-index: 1; transform-style: preserve-3d; cursor: pointer;
  transition: transform .7s var(--ale-cards-spring);
  &.is-flipped { transform: rotateY(180deg); }
  &.is-in { animation: ale-cards-deal .55s var(--ale-cards-ease) both; }
}
@keyframes ale-cards-deal { from { transform: translateY(14px) scale(.965) rotate(-1.5deg); opacity: .4; } }
.ale-cards .ale-cards-face {
  position: absolute; inset: 0; backface-visibility: hidden; -webkit-backface-visibility: hidden; border-radius: 6px; overflow: hidden;
  color: var(--ale-cards-cardink); padding: clamp(14px, 3.4cqi, 26px) clamp(16px, 3.6cqi, 30px) 18px;
  background:
    linear-gradient(to bottom, transparent 0 22%, var(--ale-cards-pink) 22% calc(22% + 1.5px), transparent calc(22% + 1.5px)),
    repeating-linear-gradient(to bottom, transparent 0 25px, color-mix(in oklch, var(--ale-cards-rule) 55%, transparent) 25px 26px) 0 calc(22% + 1px) / 100% 100% no-repeat,
    var(--ale-cards-paper);
  box-shadow: 0 1px 0 oklch(1 0 0 / .6) inset, 0 22px 40px -20px oklch(0 0 0 / .85), 0 2px 6px oklch(0 0 0 / .25);
  display: grid; grid-template-rows: auto 1fr auto;
}
.ale-cards .ale-cards-back { transform: rotateY(180deg); }
.ale-cards .ale-cards-tag {
  display: flex; justify-content: space-between; gap: 8px; font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: color-mix(in oklch, var(--ale-cards-cardink) 55%, var(--ale-cards-paper));
  & .ale-cards-flag { color: var(--ale-cards-pink); display: inline-flex; gap: 4px; align-items: center; }
  & .ale-cards-flag svg { width: 12px; height: 12px; fill: currentColor; }
}
.ale-cards .ale-cards-q {
  align-self: center; text-align: center; font-size: clamp(16px, 2.2cqi + 4px, 25px); font-weight: 600; line-height: 1.25; letter-spacing: -.012em; text-wrap: balance;
}
.ale-cards .ale-cards-hint { text-align: center; font-size: 11px; color: color-mix(in oklch, var(--ale-cards-cardink) 45%, var(--ale-cards-paper)); }
.ale-cards .ale-cards-back {
  & .ale-cards-qs { font-size: 12px; line-height: 1.35; color: color-mix(in oklch, var(--ale-cards-cardink) 55%, var(--ale-cards-paper)); text-align: center; text-wrap: balance; margin-top: 6px; }
  & .ale-cards-a { align-self: center; text-align: center; font-size: clamp(18px, 2.4cqi + 5px, 28px); font-weight: 750; line-height: 1.2; letter-spacing: -.015em; text-wrap: balance; }
  & .ale-cards-x { text-align: center; font-size: 12.5px; line-height: 1.4; font-style: italic; color: color-mix(in oklch, var(--ale-cards-cardink) 70%, var(--ale-cards-paper)); text-wrap: pretty; }
}
.ale-cards .ale-cards-ghost { position: absolute; pointer-events: none; z-index: 2; }

.ale-cards .ale-cards-done {
  position: relative; z-index: 1; text-align: center; display: grid; gap: 10px; justify-items: center; max-width: 380px;
  animation: ale-cards-deal .55s var(--ale-cards-ease) both;
  & svg { width: 46px; height: 46px; color: var(--ale-cards-accent); stroke-width: 1.5; }
  & h2 { font-size: 20px; font-weight: 750; letter-spacing: -.015em; text-wrap: balance; }
  & p { color: var(--ale-cards-mute); text-wrap: pretty; }
  & div { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; margin-top: 6px; }
}

/* answer bar */
.ale-cards .ale-cards-actions { padding: 10px 24px 6px; display: grid; justify-items: center; }
.ale-cards .ale-cards-show {
  width: min(460px, 100%); height: 46px; border: 0; border-radius: 12px; background: var(--ale-cards-ink); color: var(--ale-cards-bg); font-weight: 700; font-size: 14px;
  display: flex; align-items: center; justify-content: center; gap: 10px; transition: transform .3s var(--ale-cards-spring), filter .2s;
  & kbd { border-color: color-mix(in oklch, var(--ale-cards-bg) 30%, transparent); color: color-mix(in oklch, var(--ale-cards-bg) 70%, var(--ale-cards-ink)); }
  &:hover { filter: brightness(1.05); }
  &:active { transform: scale(.97); }
}
.ale-cards .ale-cards-grades { width: min(460px, 100%); display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.ale-cards .ale-cards-g {
  --c: var(--ale-cards-good); --i: 0;
  position: relative; height: 54px; border: 1px solid var(--ale-cards-line2); border-radius: 12px; background: var(--ale-cards-raise);
  display: grid; place-content: center; gap: 1px; text-align: center; overflow: hidden;
  animation: ale-cards-rise .45s var(--ale-cards-spring) both; animation-delay: calc(var(--i) * 45ms);
  transition: border-color .2s, background .2s, transform .25s var(--ale-cards-spring);
  & b { font: 700 13px var(--ale-cards-mono); color: var(--c); font-variant-numeric: tabular-nums; }
  & span { font-size: 12px; font-weight: 600; }
  & kbd { position: absolute; right: 6px; top: 6px; padding: 1px 4px; min-width: 0; font-size: 9px; border-width: 1px; }
  &::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 3px; background: var(--c); }
  &:hover { border-color: var(--c); background: color-mix(in oklch, var(--c) 12%, var(--ale-cards-raise)); }
  &:active { transform: scale(.95); }
  &[data-g="1"] { --c: var(--ale-cards-again); } &[data-g="2"] { --c: var(--ale-cards-hard); } &[data-g="4"] { --c: var(--ale-cards-easy); }
}
@keyframes ale-cards-rise { from { opacity: 0; transform: translateY(8px); } }
.ale-cards .ale-cards-tools {
  display: flex; justify-content: center; gap: 4px; padding: 4px 16px 14px;
  & button { display: inline-flex; align-items: center; gap: 6px; border: 0; background: none; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 12px; color: var(--ale-cards-mute); }
  & button svg { width: 15px; height: 15px; }
  & button kbd { padding: 2px 4px; min-width: 0; font-size: 9px; }
  & button:hover:not(:disabled) { background: var(--ale-cards-hover); color: var(--ale-cards-ink); }
  & button[aria-pressed="true"] { color: var(--ale-cards-pink); }
  & button[aria-pressed="true"] svg { fill: currentColor; }
}
.ale-cards .ale-cards-btn {
  height: 34px; padding: 0 14px; border-radius: 10px; border: 1px solid var(--ale-cards-line2); background: var(--ale-cards-raise); font-weight: 650;
  &:hover:not(:disabled) { border-color: var(--ale-cards-mute); }
  &.is-pri { background: var(--ale-cards-accent); border-color: var(--ale-cards-accent); color: var(--ale-cards-bg); }
  &.is-pri:hover:not(:disabled) { filter: brightness(1.06); }
}

/* browse */
.ale-cards .ale-cards-browse { display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; }
.ale-cards .ale-cards-search {
  display: flex; align-items: center; gap: 8px; margin: 14px 18px 8px; padding: 0 12px; height: 38px; border-radius: 10px; background: var(--ale-cards-raise); border: 1px solid var(--ale-cards-line);
  & svg { color: var(--ale-cards-faint); width: 16px; height: 16px; }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; }
  & input::placeholder { color: var(--ale-cards-faint); }
  & span { font-size: 11px; color: var(--ale-cards-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
  &:focus-within { border-color: var(--ale-cards-accent); }
}
.ale-cards .ale-cards-tablewrap { overflow: auto; padding: 0 10px 14px; scrollbar-width: thin; }
.ale-cards .ale-cards-tbl {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--ale-cards-bg); text-align: left; padding: 0; border-bottom: 1px solid var(--ale-cards-line2); }
  & th button { border: 0; background: none; padding: 8px 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--ale-cards-mute); display: inline-flex; gap: 4px; align-items: center; }
  & th button:hover, & th button[aria-sort] { color: var(--ale-cards-ink); }
  & th button[aria-sort]::after { content: "\2193"; color: var(--ale-cards-accent); }
  & th button[aria-sort="descending"]::after { content: "\2191"; }
  & td { padding: 0 8px; height: 44px; border-bottom: 1px solid var(--ale-cards-line); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & td:first-child { white-space: normal; width: 60%; padding: 0; }
  & tr { transition: background .15s; }
  & tbody tr:hover { background: var(--ale-cards-hover); }
  & tr.is-sel { background: color-mix(in oklch, var(--ale-cards-accent) 10%, transparent); }
  & tr.is-susp td { color: var(--ale-cards-faint); }
  & tr.is-susp .ale-cards-pick b { text-decoration: line-through; }
}
.ale-cards .ale-cards-pick {
  width: 100%; border: 0; background: none; text-align: left; padding: 7px 8px; display: grid; gap: 1px;
  & b { font-weight: 600; line-height: 1.3; }
  & span { font-size: 11.5px; color: var(--ale-cards-mute); }
}
.ale-cards .ale-cards-due { font-family: var(--ale-cards-mono); font-size: 12px; &.is-now { color: var(--ale-cards-rev); } &.is-new { color: var(--ale-cards-new); } }
.ale-cards .ale-cards-sus {
  border: 1px solid var(--ale-cards-line2); background: none; border-radius: 7px; height: 26px; padding: 0 8px; font-size: 11px; color: var(--ale-cards-mute);
  &:hover { color: var(--ale-cards-ink); border-color: var(--ale-cards-mute); }
  &[aria-pressed="true"] { color: var(--ale-cards-pink); border-color: color-mix(in oklch, var(--ale-cards-pink) 50%, transparent); }
}

/* ── stats ─────────────────────────────── */
.ale-cards .ale-cards-stats { grid-area: stats; overflow: auto; min-height: 0; padding: 16px 16px 20px; border-left: 1px solid var(--ale-cards-line); background: var(--ale-cards-panel); display: flex; flex-direction: column; gap: 18px; scrollbar-width: thin; & > * { flex: none; } }
.ale-cards .ale-cards-stats header {
  display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 10px;
  & h2 { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-cards-mute); }
  & span { font-size: 11px; color: var(--ale-cards-faint); font-variant-numeric: tabular-nums; }
}
.ale-cards .ale-cards-bars { display: grid; grid-template-columns: repeat(14, 1fr); gap: 3px; height: 126px; align-items: end; }
.ale-cards .ale-cards-bar {
  --h: 0;
  height: 100%; border: 0; background: none; padding: 0; display: grid; grid-template-rows: 1fr auto; gap: 4px; border-radius: 5px;
  & .ale-cards-col { position: relative; display: flex; align-items: flex-end; justify-content: center; }
  & .ale-cards-col i {
    width: 100%; height: calc(var(--h) * 100%); min-height: 2px; border-radius: 4px 4px 2px 2px;
    background: color-mix(in oklch, var(--ale-cards-ink) 32%, var(--ale-cards-bg)); transition: height .5s var(--ale-cards-spring), background .2s;
  }
  & .ale-cards-col b {
    position: absolute; bottom: calc(var(--h) * 100% + 3px); font: 700 9.5px var(--ale-cards-mono); color: var(--ale-cards-mute); font-variant-numeric: tabular-nums;
    transition: bottom .5s var(--ale-cards-spring);
  }
  & > span { font: 600 9.5px var(--ale-cards-mono); color: var(--ale-cards-faint); text-align: center; }
  &.is-today .ale-cards-col i { background: var(--ale-cards-accent); }
  /* a bar taller than the scale is cut with a break mark instead of flattening every other day */
  &.is-clip .ale-cards-col i { -webkit-mask: linear-gradient(to bottom, #000 0 10px, transparent 10px 14px, #000 14px); mask: linear-gradient(to bottom, #000 0 10px, transparent 10px 14px, #000 14px); }
  &.is-today > span { color: var(--ale-cards-accent); }
  &.is-wk > span { color: var(--ale-cards-mute); }
  &:hover .ale-cards-col i { background: color-mix(in oklch, var(--ale-cards-ink) 55%, var(--ale-cards-bg)); }
  &.is-today:hover .ale-cards-col i { background: color-mix(in oklch, var(--ale-cards-accent) 85%, white); }
  &[aria-pressed="true"] { background: var(--ale-cards-hover); }
  &[aria-pressed="true"] .ale-cards-col b { color: var(--ale-cards-ink); }
  &.is-bump .ale-cards-col i { animation: ale-cards-bump .5s var(--ale-cards-spring); }
}
@keyframes ale-cards-bump { 40% { filter: brightness(1.6); } }
.ale-cards .ale-cards-fcnote { margin-top: 10px; font-size: 12px; color: var(--ale-cards-mute); text-wrap: pretty; min-height: 2.9em; & b { color: var(--ale-cards-ink); font-variant-numeric: tabular-nums; } }
.ale-cards .ale-cards-today {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--ale-cards-line);
  & div { background: var(--ale-cards-raise); padding: 10px 10px 9px; display: grid; gap: 1px; }
  & b { font-size: 20px; font-weight: 750; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & span { font-size: 10.5px; color: var(--ale-cards-mute); line-height: 1.25; }
}
.ale-cards .ale-cards-grid {
  display: grid; grid-template-rows: repeat(7, 1fr); grid-auto-flow: column; grid-auto-columns: 1fr; gap: 3px; aspect-ratio: 12 / 7;
  & i { border-radius: 3px; background: color-mix(in oklch, var(--ale-cards-accent) calc(var(--l) * 100%), var(--ale-cards-line)); }
  & i.is-today { box-shadow: 0 0 0 1.5px var(--ale-cards-ink); }
  & i.is-future { background: none; box-shadow: inset 0 0 0 1px var(--ale-cards-line); }
}
.ale-cards .ale-cards-info {
  border-top: 1px solid var(--ale-cards-line); padding-top: 14px;
  & dl { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 12px; }
  & dt { font-size: 10.5px; color: var(--ale-cards-faint); text-transform: uppercase; letter-spacing: .08em; font-weight: 600; }
  & dd { font: 600 13px var(--ale-cards-mono); font-variant-numeric: tabular-nums; }
  & p { font-size: 12px; color: var(--ale-cards-mute); margin-bottom: 10px; text-wrap: pretty; }
}

/* ── nav (narrow) ─────────────────────────────── */
.ale-cards .ale-cards-nav {
  grid-area: nav; display: none; padding: 4px 6px 6px; border-top: 1px solid var(--ale-cards-line); background: var(--ale-cards-panel);
  & button { flex: 1; border: 0; background: none; display: grid; justify-items: center; gap: 2px; padding: 6px 4px; border-radius: 10px; font-size: 11px; font-weight: 600; color: var(--ale-cards-mute); }
  & button svg { width: 20px; height: 20px; }
  & button[aria-selected="true"] { color: var(--ale-cards-accent); background: var(--ale-cards-hover); }
}

/* ── modal, fly layer, toast ─────────────────────────────── */
.ale-cards .ale-cards-modal {
  position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 16px; background: oklch(0.1 0.01 55 / .6); backdrop-filter: blur(3px); margin: 0;
  transition: opacity .25s; @starting-style { opacity: 0; }
}
.ale-cards .ale-cards-sheet {
  width: min(440px, 100%); max-height: 100%; overflow: auto; padding: 16px 18px 16px; border-radius: 16px; background: var(--ale-cards-raise);
  box-shadow: 0 0 0 1px var(--ale-cards-line2), 0 30px 60px -20px oklch(0 0 0 / .8); display: grid; gap: 12px;
  transition: transform .45s var(--ale-cards-spring); @starting-style { transform: translateY(14px) scale(.97); }
  & header { display: flex; justify-content: space-between; align-items: center; }
  & h2 { font-size: 16px; font-weight: 700; }
  & label { display: grid; gap: 5px; font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--ale-cards-mute); }
  & label small { font-weight: 500; text-transform: none; letter-spacing: 0; color: var(--ale-cards-faint); }
  & textarea, & input, & select { width: 100%; border-radius: 10px; border: 1px solid var(--ale-cards-line2); background: var(--ale-cards-bg); padding: 8px 10px; font-size: 13.5px; text-transform: none; letter-spacing: 0; font-weight: 450; color: var(--ale-cards-ink); resize: vertical; outline: 0; }
  & textarea:focus, & input:focus, & select:focus { border-color: var(--ale-cards-accent); }
  & [aria-invalid="true"] { border-color: var(--ale-cards-again); }
  & footer { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }
  & footer span { margin-right: auto; font-size: 11px; color: var(--ale-cards-faint); }
}
.ale-cards .ale-cards-err { color: var(--ale-cards-again); font-size: 12px; min-height: 0; &:empty { display: none; } }
.ale-cards .ale-cards-flylayer { position: absolute; inset: 0; z-index: 25; pointer-events: none; overflow: hidden; }
.ale-cards .ale-cards-chip {
  position: absolute; left: 0; top: 0; padding: 4px 9px; border-radius: 999px; font: 700 11px var(--ale-cards-mono); white-space: nowrap;
  background: var(--c); color: var(--ale-cards-bg); box-shadow: 0 8px 18px -6px oklch(0 0 0 / .6); will-change: transform;
}
.ale-cards .ale-cards-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; translate: -50% 16px; display: flex; align-items: center; gap: 12px;
  padding: 8px 8px 8px 14px; border-radius: 12px; background: var(--ale-cards-ink); color: var(--ale-cards-bg); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 34px -14px oklch(0 0 0 / .8); opacity: 0; visibility: hidden; transition: opacity .25s, translate .4s var(--ale-cards-spring), visibility 0s .4s;
  & button { border: 0; border-radius: 8px; padding: 5px 10px; background: color-mix(in oklch, var(--ale-cards-bg) 12%, transparent); font-weight: 700; font-size: 12px; color: var(--ale-cards-bg); }
  &.is-on { opacity: 1; visibility: visible; translate: -50% 0; transition: opacity .25s, translate .4s var(--ale-cards-spring), visibility 0s; }
  &:not(.has-undo) button { display: none; }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 1080px) {
  .ale-cards .ale-cards-app { grid-template-columns: 212px minmax(0, 1fr) 260px; }
  .ale-cards .ale-cards-counts small { display: none; }
}
@container (max-width: 959px) {
