js:
/* Loci — spaced-repetition flashcards.
   An SM-2 style scheduler: every grade button previews the interval it would set, and a
   graded card sends a chip flying into the forecast bar for the day it will come back,
   so the review load you are building is visible as you build it. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const DAY0 = Date.UTC(2026, 9, 2);           /* today: Friday 2 October 2026 */
const WDS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dt = d => new Date(DAY0 + d * 864e5);
const dayName = d => d === 0 ? 'Today' : d === 1 ? 'Tomorrow' : WDS[dt(d).getUTCDay()] + ' ' + dt(d).getUTCDate() + ' ' + MON[dt(d).getUTCMonth()];
const ivlLabel = r => r.mins ? (r.mins < 2 ? '<1m' : r.mins + 'm') : r.days < 30 ? r.days + 'd' : (r.days / 30).toFixed(1) + 'mo';
const NEW_PER_DAY = 5;

const DECKS = [
  { id: 'cn', name: 'Cranial nerves', sub: 'Neuroanatomy' },
  { id: 'ab', name: 'Antibiotics', sub: 'Pharmacology' },
  { id: 'aa', name: 'Amino acids', sub: 'Biochemistry' },
];
const DK = Object.fromEntries(DECKS.map(d => [d.id, d]));
/* [deck, front, back, extra, [interval, due, ease, reps, lapses] | null for new] */
const RAW = [
  ['cn', 'Which cranial nerve abducts the eye?', 'VI · Abducens', 'Lateral rectus. Remember LR6 SO4.', [3, 0, 2.5, 4, 0]],
  ['cn', 'Which nerve passes through the cribriform plate?', 'I · Olfactory', 'The only sensory pathway without a thalamic relay.', [8, -1, 2.6, 6, 0]],
  ['cn', 'The muscles of mastication are supplied by…', 'V3 · Mandibular division', 'Leaves the skull through the foramen ovale.', [1, 0, 2.3, 3, 1]],
  ['cn', 'Taste from the anterior two-thirds of the tongue', 'VII · Facial, via chorda tympani', 'General sensation from the same area is V3.', [5, 0, 2.5, 5, 0]],
  ['cn', 'Which nerve supplies the superior oblique?', 'IV · Trochlear', 'The only nerve to leave the dorsal brainstem.', [12, 2, 2.7, 7, 0]],
  ['cn', 'Gag reflex: afferent and efferent limbs', 'IX in, X out', 'Glossopharyngeal senses, vagus contracts.', [2, 0, 2.2, 3, 2]],
  ['cn', 'Weak shoulder shrug points to a lesion of…', 'XI · Accessory', 'Trapezius and sternocleidomastoid.', [21, 9, 2.8, 8, 0]],
  ['cn', 'Lower motor neuron lesion of XII: which way does the tongue point?', 'Toward the weak side', 'The healthy genioglossus pushes it across.', [4, 1, 2.5, 4, 0]],
  ['cn', 'Pupil constriction is carried by…', 'III · Oculomotor (parasympathetic)', 'Edinger–Westphal nucleus to the ciliary ganglion.', [6, 0, 2.5, 5, 1]],
  ['cn', 'Hearing and balance', 'VIII · Vestibulocochlear', 'Runs with VII through the internal acoustic meatus.', null],
  ['cn', 'Corneal reflex: afferent limb', 'V1 · Ophthalmic division', 'The efferent limb is VII, closing the eye.', null],
  ['cn', 'Through which foramen does the vagus leave the skull?', 'Jugular foramen', 'Shared with IX and XI.', null],
  ['ab', 'How do β-lactams kill bacteria?', 'Block transpeptidases (PBPs)', 'No cross-linking, so the cell wall fails.', [2, 0, 2.5, 2, 0]],
  ['ab', 'Vancomycin binds…', 'D-Ala-D-Ala on wall precursors', 'Resistance swaps the end for D-Ala-D-Lac.', [5, 3, 2.5, 4, 0]],
  ['ab', 'Aminoglycosides act on…', '30S subunit · mRNA misreading', 'Need oxygen to enter, so useless against anaerobes.', [1, 0, 2.36, 2, 1]],
  ['ab', 'Macrolides act on…', '50S subunit · block translocation', 'Watch for QT prolongation.', [9, 4, 2.6, 5, 0]],
  ['ab', 'Fluoroquinolones inhibit…', 'DNA gyrase and topoisomerase IV', 'Avoid with antacids: cations chelate them.', [3, 0, 2.5, 3, 0]],
  ['ab', 'Tetracyclines are avoided in…', 'Children under 8 and pregnancy', 'They bind calcium in teeth and growing bone.', [14, 6, 2.7, 6, 0]],
  ['ab', 'Red man syndrome follows a fast infusion of…', 'Vancomycin', 'Histamine release. Slow the infusion down.', [4, -2, 2.5, 3, 0]],
  ['ab', 'Disulfiram-like reaction with alcohol', 'Metronidazole', 'Also cefotetan and cefoperazone.', [7, 5, 2.5, 4, 0]],
  ['ab', 'Trimethoprim inhibits…', 'Bacterial dihydrofolate reductase', 'Paired with sulfamethoxazole for a sequential block.', null],
  ['ab', 'Tendon rupture is a warning for…', 'Fluoroquinolones', 'Risk rises with age and steroids.', null],
  ['aa', 'The only achiral amino acid', 'Glycine', 'Its side chain is a single hydrogen.', [30, 12, 2.9, 9, 0]],
  ['aa', 'Amino acid with an imidazole side chain', 'Histidine', 'pKa near 6, so it buffers at body pH.', [11, 0, 2.6, 6, 0]],
  ['aa', 'Precursor of serotonin', 'Tryptophan', 'Also of niacin and melatonin.', [6, 2, 2.5, 5, 0]],
  ['aa', 'Precursor of the catecholamines', 'Tyrosine', 'Made from phenylalanine.', [18, 7, 2.7, 7, 0]],
  ['aa', 'Forms disulfide bonds', 'Cysteine', 'Two cysteines make cystine.', [3, 0, 2.4, 4, 1]],
  ['aa', 'Secondary amine that breaks α-helices', 'Proline', 'Its ring locks the backbone angle.', [25, 16, 2.8, 8, 0]],
  ['aa', 'Precursor of nitric oxide', 'Arginine', 'NO synthase releases citrulline.', [9, 1, 2.6, 5, 0]],
  ['aa', 'The three branched-chain amino acids', 'Leucine, isoleucine, valine', 'Their breakdown fails in maple syrup urine disease.', [2, 0, 2.2, 3, 2]],
  ['aa', 'Precursor of histamine', 'Histidine', 'Decarboxylated by histidine decarboxylase.', [15, 10, 2.7, 6, 0]],
  ['aa', 'The purely ketogenic amino acids', 'Leucine and lysine', 'Everything else can feed glucose.', [40, 22, 3.0, 10, 0]],
];
let cards = RAW.map((r, i) => ({ id: i + 1, deck: r[0], front: r[1], back: r[2], extra: r[3], s: r[4] && { ivl: r[4][0], due: r[4][1], ease: r[4][2], reps: r[4][3], lapses: r[4][4] }, learn: false, seen: false, susp: false, flag: false }));
let nid = cards.length;

/* 12 weeks of history ending on Saturday 3 Oct; a 23-day streak runs up to yesterday */
const HEAT = (() => {
  let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const start = -(dt(0).getUTCDay()) - 77;        /* the Sunday 11 weeks before this week */
  return Array.from({ length: 84 }, (_, k) => {
    const d = start + k;
    if (d >= 0) return { d, n: 0 };
    if (d === -24 || d === -31 || d === -45 || d === -46 || d === -60) return { d, n: 0 };
    return { d, n: d >= -23 ? 14 + Math.floor(rnd() * 26) : Math.floor(rnd() * 34) };
  });
})();

const S = { deck: 'all', mode: 'study', view: 'study', flipped: false, queue: [], done: 0, right: 0, sel: null, sort: ['due', 1], q: '', fc: null, newSeen: { cn: 0, ab: 0, aa: 0 } };
const undo = [];
const pending = new Array(14).fill(0);
const card = id => cards.find(c => c.id === id);
const cur = () => card(S.queue[0]);
const inScope = c => S.deck === 'all' || c.deck === S.deck;

/* ── scheduler ───────────────────────────────────────── */
function next(c, g) {
  if (!c.s || c.learn) {
    if (g === 1) return { mins: 1 };
    if (g === 2) return { mins: 6 };
    if (g === 3) return { days: 1 };
    return { days: 4, ease: 2.65 };
  }
  const { ivl, ease } = c.s, late = Math.max(0, -c.s.due);
  if (g === 1) return { mins: 10, ease: Math.max(1.3, +(ease - 0.2).toFixed(2)), lapse: true };
  if (g === 2) return { days: Math.max(ivl + 1, Math.round(ivl * 1.2)), ease: Math.max(1.3, +(ease - 0.15).toFixed(2)) };
  if (g === 3) return { days: Math.max(ivl + 1, Math.round((ivl + late / 2) * ease)), ease };
  return { days: Math.max(ivl + 2, Math.round((ivl + late) * ease * 1.3)), ease: +(ease + 0.15).toFixed(2) };
}
function newLeft(deck) { return NEW_PER_DAY - S.newSeen[deck]; }
function build() {
  const pool = cards.filter(c => inScope(c) && !c.susp);
  const due = pool.filter(c => c.s && c.s.due <= 0).sort((a, b) => a.s.due - b.s.due || a.id - b.id);
  const fresh = [], used = {};
  pool.filter(c => !c.s).forEach(c => { used[c.deck] = used[c.deck] || 0; if (used[c.deck] < newLeft(c.deck)) { fresh.push(c); used[c.deck]++; } });
  const q = [];
  while (due.length || fresh.length) { for (let k = 0; k < 3 && due.length; k++) q.push(due.shift()); if (fresh.length) q.push(fresh.shift()); }
  S.queue = q.map(c => c.id);
  S.flipped = false;
}
function counts(list = S.queue.map(card)) {
  const r = { nw: 0, lr: 0, rv: 0 };
  list.forEach(c => { if (c.learn) r.lr++; else if (!c.s) r.nw++; else r.rv++; });
  return r;
}
function deckCounts(id) {
  const pool = cards.filter(c => (id === 'all' || c.deck === id) && !c.susp);
  const due = pool.filter(c => c.s && c.s.due <= 0 && !c.learn).length + pool.filter(c => c.learn).length;
  const ids = id === 'all' ? DECKS.map(d => d.id) : [id];
  const nw = ids.reduce((a, d) => a + Math.min(newLeft(d), pool.filter(c => !c.s && c.deck === d).length), 0);
  const total = pool.length, known = pool.filter(c => c.s && c.s.ivl >= 21).length;
  return { due, nw, total, mature: total ? known / total : 0 };
}

/* ── rendering ───────────────────────────────────────── */
const stack = $('[data-stack]'), actions = $('[data-actions]'), barsEl = $('[data-bars]');
function renderDecks() {
  const rows = [{ id: 'all', name: 'All decks', sub: cards.filter(c => !c.susp).length + ' cards' }].concat(DECKS.map(d => ({ ...d, sub: d.sub })));
  $('[data-decks]').innerHTML = rows.map(d => {
    const k = deckCounts(d.id), on = S.deck === d.id;
    return '<li role="option" class="ale-cards-deck" data-deck="' + d.id + '" aria-selected="' + on + '" tabindex="' + (on ? 0 : -1) + '"><b>' + esc(d.name) + '</b>' +
      '<span class="ale-cards-n ' + (k.due ? 'is-due' : 'is-zero') + '" title="Due">' + k.due + '</span><span class="ale-cards-n ' + (k.nw ? 'is-new' : 'is-zero') + '" title="New">' + k.nw + '</span>' +
      '<small>' + esc(d.id === 'all' ? d.sub : d.sub + ' · ' + k.total + ' cards · ' + Math.round(k.mature * 100) + '% mature') + '</small>' +
      '<span class="ale-cards-mini"><i style="--m:' + k.mature.toFixed(3) + '"></i></span></li>';
  }).join('');
}
function renderTop() {
  const d = S.deck === 'all' ? null : DK[S.deck];
  $('[data-deckname]').textContent = d ? d.name : 'All decks';
  $('[data-deckcrumb]').textContent = (d ? d.sub : 'Today') + ' · Friday 2 October';
  const k = counts(), c = cur(), which = c ? (c.learn ? 'lr' : !c.s ? 'nw' : 'rv') : '';
  $('[data-counts]').innerHTML = '<span class="is-new' + (which === 'nw' ? ' is-cur' : '') + '">' + k.nw + '<small>new</small></span><span class="is-learn' + (which === 'lr' ? ' is-cur' : '') + '">' + k.lr + '<small>learning</small></span><span class="is-rev' + (which === 'rv' ? ' is-cur' : '') + '">' + k.rv + '<small>review</small></span>';
  const u = $('[data-act="undo"]');
  u.disabled = !undo.length;
  u.title = undo.length ? 'Undo: ' + undo[undo.length - 1].label + ' (U)' : 'Nothing to undo yet';
  const total = S.done + S.queue.length;
  $('[data-progbar]').parentElement.style.setProperty('--p', total ? (S.done / total).toFixed(3) : 0);
}
const ICON_FLAG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 20.5V4.5M6 5h11l-2.5 4L17 13H6"/></svg>';
function cardHTML(c, flipped, enter) {
  const st = c.learn ? 'Learning' : !c.s ? 'New' : 'Review';
  const tag = '<p class="ale-cards-tag"><span>' + esc(DK[c.deck].name) + ' · ' + st + '</span>' + (c.flag ? '<span class="ale-cards-flag">' + ICON_FLAG + 'Flagged</span>' : '<span></span>') + '</p>';
  return '<div class="ale-cards-card' + (flipped ? ' is-flipped' : '') + (enter ? ' is-in' : '') + '" data-card="' + c.id + '" aria-live="polite">' +
    '<div class="ale-cards-face ale-cards-front"' + (flipped ? ' aria-hidden="true"' : '') + '>' + tag + '<p class="ale-cards-q">' + esc(c.front) + '</p><p class="ale-cards-hint">Tap the card or press Space to turn it over</p></div>' +
    '<div class="ale-cards-face ale-cards-back"' + (flipped ? '' : ' aria-hidden="true"') + '>' + tag + '<div style="display:grid;align-content:center;gap:10px"><p class="ale-cards-qs">' + esc(c.front) + '</p><p class="ale-cards-a">' + esc(c.back) + '</p></div><p class="ale-cards-x">' + esc(c.extra || '') + '</p></div></div>';
}
function clearDesk() { $$('.ale-cards-card:not(.ale-cards-ghost), .ale-cards-done', stack).forEach(n => n.remove()); }
function renderStudy(enter) {
  const c = cur();
  stack.dataset.depth = Math.min(2, Math.max(0, S.queue.length - 1));
  $('[data-tools]').hidden = !c;
  clearDesk();
  if (!c) {
    const ahead = cards.filter(x => inScope(x) && !x.susp && x.s && x.s.due === 1).length;
    stack.dataset.depth = 0;
    stack.insertAdjacentHTML('afterbegin', '<div class="ale-cards-done"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="20"/><path d="m15 24.5 6 6 12-13"/></svg><h2>' + (S.done ? 'Done for today' : 'Nothing due here') + '</h2><p>' +
      (S.done ? 'You reviewed ' + S.done + ' card' + (S.done === 1 ? '' : 's') + ' and got ' + S.right + ' right. ' : '') + (ahead ? ahead + ' card' + (ahead === 1 ? ' is' : 's are') + ' due tomorrow.' : 'Nothing is due tomorrow either.') + '</p></div>');
    actions.innerHTML = '<div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center"><button type="button" class="ale-cards-btn is-pri" data-act="ahead"' + (ahead ? '' : ' disabled title="No cards are due tomorrow"') + '>Study tomorrow’s ' + (ahead || '') + ' now</button><button type="button" class="ale-cards-btn" data-act="tobrowse">Browse this deck</button></div>';
    return;
  }
  stack.insertAdjacentHTML('afterbegin', cardHTML(c, S.flipped, enter));
  $('[data-act="flag"]').setAttribute('aria-pressed', c.flag);
  $('[data-flaglbl]').textContent = c.flag ? 'Flagged' : 'Flag';
  renderActions(c);
}
function renderActions(c) {
  if (!S.flipped) {
    actions.innerHTML = '<button type="button" class="ale-cards-show" data-act="flip">Show answer <kbd>Space</kbd></button>';
  } else {
    actions.innerHTML = '<div class="ale-cards-grades" role="group" aria-label="How well did you know it?">' + ['Again', 'Hard', 'Good', 'Easy'].map((w, k) =>
      '<button type="button" class="ale-cards-g" data-g="' + (k + 1) + '" style="--i:' + k + '" aria-label="' + w + ', next review in ' + ivlLabel(next(c, k + 1)) + '"><b>' + ivlLabel(next(c, k + 1)) + '</b><span>' + w + '</span><kbd>' + (k + 1) + '</kbd></button>').join('') + '</div>';
  }
}
function forecast() {
  const f = new Array(14).fill(0); let later = 0;
  cards.forEach(c => { if (!inScope(c) || c.susp || !c.s || c.learn) return; if (c.s.due >= 1 && c.s.due < 14) f[c.s.due]++; else if (c.s.due >= 14) later++; });
  f[0] = S.queue.length;
  return { f, later };
}
function renderBars(bump) {
  const { f, later } = forecast();
  const shown = f.map((n, d) => Math.max(0, n - pending[d]));
  const max = Math.max(8, ...shown.slice(1));
  barsEl.innerHTML = shown.map((n, d) => {
    const day = dt(d), wd = day.getUTCDay();
    return '<button type="button" class="ale-cards-bar' + (d === 0 ? ' is-today' : '') + (n > max ? ' is-clip' : '') + (wd === 1 ? ' is-wk' : '') + (bump === d ? ' is-bump' : '') + '" data-day="' + d + '" aria-pressed="' + (S.fc === d) + '" style="--h:' + Math.min(1, n / max).toFixed(3) + '" aria-label="' + dayName(d) + ': ' + n + (d === 0 ? ' left' : ' due') + '" title="' + dayName(d) + ': ' + n + (d === 0 ? ' left today' : ' due') + '">' +
      '<span class="ale-cards-col"><i></i><b>' + (n || '') + '</b></span><span>' + (d === 0 ? 'T' : WDS[wd][0]) + '</span></button>';
  }).join('');
  const note = $('[data-fcnote]');
  if (S.fc != null) {
    const d = S.fc, list = d === 0 ? S.queue.map(card) : cards.filter(c => inScope(c) && !c.susp && c.s && !c.learn && c.s.due === d);
    const by = DECKS.map(k => [k.name, list.filter(c => c.deck === k.id).length]).filter(x => x[1]);
    note.innerHTML = '<b>' + dayName(d) + '</b>: ' + list.length + (d === 0 ? ' left in this session' : ' card' + (list.length === 1 ? '' : 's') + ' due') + (by.length ? ' — ' + by.map(x => x[1] + ' ' + esc(x[0].toLowerCase())).join(', ') : '') + '.';
  } else {
    const week = f.slice(1, 8).reduce((a, b) => a + b, 0);
    note.innerHTML = 'Tomorrow <b>' + f[1] + '</b> · next 7 days <b>' + week + '</b> · later <b>' + later + '</b>. Select a day for its breakdown.';
  }
}
function renderHeat() {
  const today = HEAT.find(h => h.d === 0); today.n = S.done;
  const max = 40;
  $('[data-heat]').innerHTML = HEAT.map(h => '<i class="' + (h.d === 0 ? 'is-today' : h.d > 0 ? 'is-future' : '') + '" style="--l:' + (h.d > 0 || !h.n ? 0 : Math.min(4, Math.ceil(h.n / 10)) / 4) + '"' + (h.d > 0 ? '' : ' title="' + (h.d === 0 ? 'Today' : WDS[dt(h.d).getUTCDay()] + ' ' + dt(h.d).getUTCDate() + ' ' + MON[dt(h.d).getUTCMonth()]) + ': ' + h.n + ' reviews"') + '></i>').join('');
  const sum = HEAT.reduce((a, h) => a + h.n, 0);
  $('[data-heatsum]').textContent = sum.toLocaleString('en-GB') + ' reviews';
  $('[data-heat]').setAttribute('aria-label', 'Reviews per day for the last 12 weeks, ' + sum + ' in total');
  const streak = 23 + (S.done ? 1 : 0);
  $('[data-st="streak"]').textContent = streak;
  $('[data-st="done"]').textContent = S.done;
  $('[data-st="acc"]').textContent = S.done ? Math.round(100 * S.right / S.done) + '%' : '—';
  $('[data-streak]').innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21c-3.9 0-6.5-2.6-6.5-6.2 0-3.3 2.4-5.4 3.9-7.6.4 1.6 1.2 2.7 2.4 3.3.2-2.9 1.5-5.6 3.7-7.5.2 2.8 1.4 4.4 2.5 6 .8 1.2 1.5 2.6 1.5 4.3 0 4.4-3 7.7-7.5 7.7Z"/><path d="M12 21c-1.6 0-2.7-1.1-2.7-2.6 0-1.7 1.4-2.6 2.2-3.9.9 1.2 3.2 2.2 3.2 4 0 1.5-1.2 2.5-2.7 2.5Z"/></svg><span><b>' + streak + '-day streak.</b> ' + (S.done ? 'Today counts.' : 'Review one card to make it ' + (streak + 1) + '.') + '</span>';
}
function renderInfo() {
  const c = card(S.sel) || cur();
  const el = $('[data-info]');
  if (!c) { el.innerHTML = '<header><h2>This card</h2></header><p>No card on the desk. Pick one in Browse to see its schedule.</p>'; return; }
