@property --ale-quiz-n { syntax: '<integer>'; inherits: false; initial-value: 0; }
@property --ale-quiz-fill { syntax: '<percentage>'; inherits: false; initial-value: 0%; }

.ale-quiz {
  /* re-theme with these four */
  --ale-quiz-bg: oklch(0.982 0.004 250);
  --ale-quiz-ink: oklch(0.23 0.03 262);
  --ale-quiz-accent: oklch(0.5 0.17 262);
  --ale-quiz-hi: oklch(0.87 0.14 92);
  /* derived */
  --ale-quiz-card: oklch(1 0 none);
  --ale-quiz-side: color-mix(in oklch, var(--ale-quiz-bg) 94%, var(--ale-quiz-ink));
  --ale-quiz-line: color-mix(in oklch, var(--ale-quiz-ink) 11%, transparent);
  --ale-quiz-line2: color-mix(in oklch, var(--ale-quiz-ink) 20%, transparent);
  --ale-quiz-mute: color-mix(in oklch, var(--ale-quiz-ink) 60%, var(--ale-quiz-bg));
  --ale-quiz-faint: color-mix(in oklch, var(--ale-quiz-ink) 36%, var(--ale-quiz-bg));
  --ale-quiz-hover: color-mix(in oklch, var(--ale-quiz-ink) 5%, transparent);
  --ale-quiz-tint: color-mix(in oklch, var(--ale-quiz-accent) 10%, var(--ale-quiz-card));
  --ale-quiz-ok: oklch(0.58 0.13 155);
  --ale-quiz-bad: oklch(0.57 0.19 27);
  --ale-quiz-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-quiz-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-quiz-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-quiz-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-quiz-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-quiz-bg); color: var(--ale-quiz-ink); color-scheme: light; accent-color: var(--ale-quiz-accent);
  font: 13px/1.45 var(--ale-quiz-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-quiz-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & h1, & h2, & h3, & p, & ol, & ul, & dl, & dd, & fieldset, & legend { margin: 0; padding: 0; font: inherit; border: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--ale-quiz-mono); padding: 3px 5px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--ale-quiz-line2); border-bottom-width: 2px; border-radius: 5px; background: var(--ale-quiz-card); color: var(--ale-quiz-mute); }
}
.ale-quiz .ale-quiz-app {
  height: 100%; display: grid; grid-template-columns: 228px minmax(0, 1fr) 286px; grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "side main score" "tabs tabs tabs";
}

/* ── header ─────────────────────────────── */
.ale-quiz .ale-quiz-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 14px 18px; border-bottom: 1px solid var(--ale-quiz-line); position: relative; }
.ale-quiz .ale-quiz-mark { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; background: var(--ale-quiz-ink); color: var(--ale-quiz-hi); & svg { width: 22px; height: 22px; } }
