  & p { font-size: 11px; color: var(--ale-quiz-mute); }
  & h1 { font-size: clamp(15px, 1.1cqi + 6px, 19px); font-weight: 720; letter-spacing: -.018em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ale-quiz .ale-quiz-meter { position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; & i { display: block; height: 100%; width: var(--ale-quiz-fill); background: var(--ale-quiz-accent); transition: --ale-quiz-fill .7s var(--ale-quiz-ease); } }
.ale-quiz .ale-quiz-btn {
