  &.is-pri kbd { background: none; color: color-mix(in oklch, var(--ale-quiz-card) 70%, var(--ale-quiz-ink)); border-color: color-mix(in oklch, var(--ale-quiz-card) 30%, transparent); }
  &.is-pri:hover:not(:disabled):not([aria-disabled="true"]) { background: color-mix(in oklch, var(--ale-quiz-ink) 85%, var(--ale-quiz-accent)); }
