/* ── navigator ─────────────────────────────── */
.ale-quiz .ale-quiz-side { grid-area: side; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; border-right: 1px solid var(--ale-quiz-line); background: var(--ale-quiz-side); }
.ale-quiz .ale-quiz-filter {
