  & button[aria-checked="true"] { background: var(--ale-quiz-card); color: var(--ale-quiz-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--ale-quiz-ink) 14%, transparent); }
}
.ale-quiz .ale-quiz-nav { overflow: auto; padding: 2px 8px 10px; scrollbar-width: thin; }
.ale-quiz .ale-quiz-qi {
  --c: var(--ale-quiz-line2);
