  & .ale-quiz-dot svg { width: 14px; height: 14px; stroke-width: 2.6; }
  & b { display: block; font-weight: 560; font-size: 12.5px; line-height: 1.25; text-wrap: pretty; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  & small { font-size: 10.5px; color: var(--ale-quiz-faint); }
