  &:hover { background: var(--ale-quiz-hover); }
  &[aria-current="true"] { background: var(--ale-quiz-card); box-shadow: 0 0 0 1px var(--ale-quiz-line), 0 2px 8px -4px color-mix(in oklch, var(--ale-quiz-ink) 25%, transparent); }
  &[aria-current="true"] .ale-quiz-dot { box-shadow: inset 0 0 0 2px var(--ale-quiz-accent); color: var(--ale-quiz-accent); }
  &.is-ok .ale-quiz-dot { background: var(--ale-quiz-ok); color: white; box-shadow: none; }
  &.is-bad .ale-quiz-dot { background: var(--ale-quiz-bad); color: white; box-shadow: none; }
}
.ale-quiz .ale-quiz-legend {
  display: flex; gap: 12px; padding: 10px 16px 14px; border-top: 1px solid var(--ale-quiz-line); font-size: 11px; color: var(--ale-quiz-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ale-quiz-line2); }
  & i.is-ok { background: var(--ale-quiz-ok); box-shadow: none; } & i.is-bad { background: var(--ale-quiz-bad); box-shadow: none; }
}

/* ── question ─────────────────────────────── */
.ale-quiz .ale-quiz-main { grid-area: main; overflow: auto; min-height: 0; padding: 22px clamp(16px, 3cqi, 34px) 26px; scrollbar-width: thin; overscroll-behavior: contain; }
.ale-quiz .ale-quiz-card {
  --dir: 1;
  max-width: 640px; margin: 0 auto; display: grid; gap: 16px;
  animation: ale-quiz-enter .45s var(--ale-quiz-ease) both;
}
@keyframes ale-quiz-enter { from { opacity: 0; transform: translateX(calc(var(--dir) * 26px)); filter: blur(2px); } }
.ale-quiz .ale-quiz-qh {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  & .ale-quiz-num { font: 700 11px var(--ale-quiz-mono); color: var(--ale-quiz-accent); letter-spacing: .02em; font-variant-numeric: tabular-nums; }
  & .ale-quiz-chip { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ale-quiz-mute); padding: 3px 8px; border-radius: 999px; background: var(--ale-quiz-line); }
  & .ale-quiz-flag { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--ale-quiz-line2); background: none; font-size: 12px; font-weight: 600; color: var(--ale-quiz-mute); }
  & .ale-quiz-flag svg { width: 14px; height: 14px; }
  & .ale-quiz-flag:hover { color: var(--ale-quiz-ink); border-color: var(--ale-quiz-ink); }
  & .ale-quiz-flag[aria-pressed="true"] { background: var(--ale-quiz-hi); border-color: color-mix(in oklch, var(--ale-quiz-hi) 60%, var(--ale-quiz-ink)); color: var(--ale-quiz-ink); }
  & .ale-quiz-flag[aria-pressed="true"] svg { fill: currentColor; }
}
.ale-quiz .ale-quiz-prompt { font-size: clamp(17px, 1.3cqi + 8px, 22px); font-weight: 680; line-height: 1.3; letter-spacing: -.016em; text-wrap: balance; }
.ale-quiz .ale-quiz-sub { margin-top: -8px; font-size: 12.5px; color: var(--ale-quiz-mute); }

.ale-quiz .ale-quiz-opts { display: grid; gap: 8px; }
.ale-quiz .ale-quiz-opt {
  --i: 0;
  position: relative; width: 100%; display: grid; grid-template-columns: 28px 1fr auto; gap: 12px; align-items: center; text-align: left;
  padding: 11px 14px 11px 12px; border-radius: 12px; border: 1.5px solid var(--ale-quiz-line); background: var(--ale-quiz-card);
  animation: ale-quiz-rise .4s var(--ale-quiz-ease) both; animation-delay: calc(var(--i) * 40ms + 80ms);
