  & .ale-quiz-txt { line-height: 1.4; font-size: 13.5px; text-wrap: pretty; }
  & .ale-quiz-mk { width: 20px; height: 20px; opacity: 0; transform: scale(.6); transition: opacity .2s, transform .35s var(--ale-quiz-spring); }
  &[role="checkbox"] .ale-quiz-key { border-radius: 6px; }
  &:hover:not([aria-disabled="true"]) { border-color: var(--ale-quiz-line2); background: color-mix(in oklch, var(--ale-quiz-card) 92%, var(--ale-quiz-accent)); }
  &:active:not([aria-disabled="true"]) { transform: scale(.99); }
  &[aria-checked="true"] { border-color: var(--ale-quiz-accent); background: var(--ale-quiz-tint); }
  &[aria-checked="true"] .ale-quiz-key { background: var(--ale-quiz-accent); color: white; }
  &.is-right { border-color: var(--ale-quiz-ok); background: color-mix(in oklch, var(--ale-quiz-ok) 9%, var(--ale-quiz-card)); }
  &.is-right .ale-quiz-key { background: var(--ale-quiz-ok); color: white; }
  &.is-right .ale-quiz-mk { opacity: 1; transform: none; color: var(--ale-quiz-ok); }
  &.is-wrong { border-color: var(--ale-quiz-bad); background: color-mix(in oklch, var(--ale-quiz-bad) 8%, var(--ale-quiz-card)); }
  &.is-wrong .ale-quiz-key { background: var(--ale-quiz-bad); color: white; }
  &.is-wrong .ale-quiz-mk { opacity: 1; transform: none; color: var(--ale-quiz-bad); }
  &.is-missed { border-style: dashed; border-color: var(--ale-quiz-ok); }
  &.is-missed .ale-quiz-mk { opacity: 1; transform: none; color: var(--ale-quiz-ok); }
  &[aria-disabled="true"] { cursor: default; }
  &[aria-disabled="true"]:not(.is-right):not(.is-wrong):not(.is-missed) { opacity: .55; }
}
@keyframes ale-quiz-rise { from { opacity: 0; transform: translateY(8px); } }

/* ordering */
.ale-quiz .ale-quiz-order { display: grid; gap: 8px; position: relative; }
.ale-quiz .ale-quiz-ord {
  --i: 0;
  display: grid; grid-template-columns: 22px 26px 1fr auto; gap: 10px; align-items: center; padding: 9px 8px 9px 10px; border-radius: 12px;
  border: 1.5px solid var(--ale-quiz-line); background: var(--ale-quiz-card); touch-action: none; user-select: none;
  animation: ale-quiz-rise .4s var(--ale-quiz-ease) both; animation-delay: calc(var(--i) * 40ms + 80ms);
  transition: border-color .18s, box-shadow .2s, background .18s;
  & .ale-quiz-grip { color: var(--ale-quiz-faint); cursor: grab; display: grid; place-items: center; height: 100%; }
  & .ale-quiz-grip svg { width: 16px; height: 16px; }
  & .ale-quiz-pos { width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; font: 700 12px var(--ale-quiz-mono); background: var(--ale-quiz-line); color: var(--ale-quiz-mute); }
  & .ale-quiz-txt { font-size: 13.5px; line-height: 1.35; text-wrap: pretty; }
  & .ale-quiz-mv { display: flex; gap: 2px; }
  & .ale-quiz-mv button { width: 28px; height: 28px; border: 0; border-radius: 7px; background: none; color: var(--ale-quiz-mute); display: grid; place-items: center; }
  & .ale-quiz-mv button:hover:not(:disabled) { background: var(--ale-quiz-hover); color: var(--ale-quiz-ink); }
  & .ale-quiz-mv button:disabled { opacity: .25; }
  & .ale-quiz-mv svg { width: 15px; height: 15px; }
  &.is-drag { box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--ale-quiz-ink) 45%, transparent); border-color: var(--ale-quiz-accent); z-index: 2; position: relative; background: var(--ale-quiz-card); }
  &.is-right { border-color: var(--ale-quiz-ok); & .ale-quiz-pos { background: var(--ale-quiz-ok); color: white; } }
  &.is-wrong { border-color: var(--ale-quiz-bad); & .ale-quiz-pos { background: var(--ale-quiz-bad); color: white; } }
  & .ale-quiz-should { font: 600 11px var(--ale-quiz-mono); color: var(--ale-quiz-ok); white-space: nowrap; }
}

/* numeric */
.ale-quiz .ale-quiz-numrow {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  & label { display: flex; align-items: center; height: 52px; border-radius: 12px; border: 1.5px solid var(--ale-quiz-line2); background: var(--ale-quiz-card); padding: 0 14px 0 16px; gap: 8px; transition: border-color .15s, box-shadow .15s; }
  & label:focus-within { border-color: var(--ale-quiz-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--ale-quiz-accent) 15%, transparent); }
  & input { width: 7.5ch; border: 0; outline: 0; background: none; font: 650 22px var(--ale-quiz-mono); font-variant-numeric: tabular-nums; }
  & label span { font: 600 14px var(--ale-quiz-mono); color: var(--ale-quiz-mute); }
  & label.is-right { border-color: var(--ale-quiz-ok); background: color-mix(in oklch, var(--ale-quiz-ok) 9%, var(--ale-quiz-card)); }
  & label.is-wrong { border-color: var(--ale-quiz-bad); background: color-mix(in oklch, var(--ale-quiz-bad) 8%, var(--ale-quiz-card)); }
  & p { font-size: 12px; color: var(--ale-quiz-mute); }
  & p.is-err { color: var(--ale-quiz-bad); font-weight: 600; }
}

/* confidence */
.ale-quiz .ale-quiz-conf {
  display: grid; gap: 8px; padding: 12px; border-radius: 14px; background: var(--ale-quiz-side); border: 1px solid var(--ale-quiz-line);
  & legend { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--ale-quiz-mute); float: left; width: 100%; }
