}
.ale-quiz .ale-quiz-confs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; clear: both; }
.ale-quiz .ale-quiz-cf {
  border: 1.5px solid var(--ale-quiz-line); background: var(--ale-quiz-card); border-radius: 10px; padding: 8px 10px; text-align: left; display: grid; gap: 1px;
  transition: border-color .15s, background .15s, transform .25s var(--ale-quiz-spring);
