  &:hover:not([aria-disabled="true"]) { border-color: var(--ale-quiz-line2); }
  &[aria-checked="true"] { border-color: var(--ale-quiz-ink); background: var(--ale-quiz-hi); }
  &[aria-checked="true"] span { color: var(--ale-quiz-ink); }
  &[aria-disabled="true"] { cursor: default; }
  &[aria-disabled="true"]:not([aria-checked="true"]) { opacity: .5; }
}

/* explanation */
.ale-quiz .ale-quiz-why {
  display: grid; grid-template-rows: 1fr; transition: grid-template-rows .5s var(--ale-quiz-ease), opacity .4s;
  @starting-style { grid-template-rows: 0fr; opacity: 0; }
  & > div { overflow: hidden; min-height: 0; }
  & .ale-quiz-wbox { border-radius: 14px; padding: 14px 16px; border-left: 4px solid var(--c); background: color-mix(in oklch, var(--c) 8%, var(--ale-quiz-card)); display: grid; gap: 6px; }
  & h3 { display: flex; align-items: center; gap: 10px; font-weight: 720; font-size: 14px; }
  & .ale-quiz-pts { font: 750 12px var(--ale-quiz-mono); padding: 3px 8px; border-radius: 999px; background: var(--c); color: white; animation: ale-quiz-pop .6s var(--ale-quiz-spring) .15s both; font-variant-numeric: tabular-nums; }
  & p { line-height: 1.55; text-wrap: pretty; }
  & small { color: var(--ale-quiz-mute); font-size: 11.5px; }
}
@keyframes ale-quiz-pop { from { transform: scale(.4); opacity: 0; } }
.ale-quiz .ale-quiz-foot {
  display: flex; align-items: center; gap: 8px; padding-top: 4px;
  & .ale-quiz-hint { margin-right: auto; font-size: 11.5px; color: var(--ale-quiz-faint); }
}

/* results */
.ale-quiz .ale-quiz-res {
  max-width: 640px; margin: 0 auto; display: grid; gap: 18px; animation: ale-quiz-enter .5s var(--ale-quiz-ease) both;
  & > p:first-child { font: 700 11px var(--ale-quiz-mono); color: var(--ale-quiz-accent); }
  & h2 { font-size: clamp(22px, 2cqi + 10px, 32px); font-weight: 760; letter-spacing: -.025em; line-height: 1.12; text-wrap: balance; }
  & .ale-quiz-lede { color: var(--ale-quiz-mute); font-size: 14px; line-height: 1.55; text-wrap: pretty; max-width: 56ch; }
}
.ale-quiz .ale-quiz-rgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.ale-quiz .ale-quiz-rcard {
  --i: 0;
  padding: 14px; border-radius: 14px; background: var(--ale-quiz-card); border: 1px solid var(--ale-quiz-line); display: grid; gap: 2px;
  animation: ale-quiz-rise .5s var(--ale-quiz-ease) both; animation-delay: calc(var(--i) * 70ms + 150ms);
  & b { font-size: 26px; font-weight: 760; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & span { font-size: 12px; color: var(--ale-quiz-mute); }
}
.ale-quiz .ale-quiz-rbig { padding: 16px; border-radius: 16px; background: var(--ale-quiz-card); border: 1px solid var(--ale-quiz-line); & svg { width: 100%; height: auto; display: block; } }
.ale-quiz .ale-quiz-ract { display: flex; gap: 8px; flex-wrap: wrap; }

/* ── score panel ─────────────────────────────── */
.ale-quiz .ale-quiz-score { grid-area: score; overflow: auto; min-height: 0; padding: 18px 16px 20px; border-left: 1px solid var(--ale-quiz-line); background: var(--ale-quiz-side); display: flex; flex-direction: column; gap: 18px; scrollbar-width: thin; & > * { flex: none; } }
.ale-quiz .ale-quiz-total {
  & > p { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-quiz-mute); }
  & > span { font-size: 12px; color: var(--ale-quiz-mute); font-variant-numeric: tabular-nums; }
}
.ale-quiz .ale-quiz-big {
  display: flex; align-items: baseline; gap: 10px; margin: 2px 0;
  & b { font-size: 48px; line-height: 1; font-weight: 780; letter-spacing: -.04em; font-variant-numeric: tabular-nums; counter-reset: ale-quiz-s var(--ale-quiz-n); transition: --ale-quiz-n .8s var(--ale-quiz-ease); }
  & b::after { content: counter(ale-quiz-s); }
  & span { font: 750 14px var(--ale-quiz-mono); padding: 3px 8px; border-radius: 999px; opacity: 0; font-variant-numeric: tabular-nums; }
  & span.is-up { background: color-mix(in oklch, var(--ale-quiz-ok) 16%, transparent); color: var(--ale-quiz-ok); animation: ale-quiz-flash 2.2s var(--ale-quiz-ease) both; }
  & span.is-down { background: color-mix(in oklch, var(--ale-quiz-bad) 14%, transparent); color: var(--ale-quiz-bad); animation: ale-quiz-flash 2.2s var(--ale-quiz-ease) both; }
}
@keyframes ale-quiz-flash { 0% { opacity: 0; transform: translateY(6px); } 12%, 70% { opacity: 1; transform: none; } 100% { opacity: 0; } }
.ale-quiz .ale-quiz-kpis {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--ale-quiz-line);
  & div { background: var(--ale-quiz-card); padding: 10px; display: grid; gap: 1px; }
  & dt { font-size: 10.5px; color: var(--ale-quiz-mute); order: 2; }
  & dd { font-size: 17px; font-weight: 740; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
}
.ale-quiz .ale-quiz-cal, .ale-quiz .ale-quiz-topics {
  & header { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px; }
  & h2 { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-quiz-mute); }
  & header span { font-size: 11px; font-weight: 600; }
}
.ale-quiz .ale-quiz-cal {
  & svg { width: 100%; height: auto; display: block; overflow: visible; }
  & .ale-quiz-calhelp { margin-top: 6px; font-size: 11px; color: var(--ale-quiz-faint); line-height: 1.4; text-wrap: pretty; }
}
.ale-quiz .ale-quiz-calsvg {
  & .ale-quiz-band { fill: color-mix(in oklch, var(--ale-quiz-accent) 10%, transparent); stroke: color-mix(in oklch, var(--ale-quiz-accent) 22%, transparent); stroke-width: 1; stroke-dasharray: 3 3; }
  & .ale-quiz-gl { stroke: var(--ale-quiz-line); stroke-width: 1; }
  & .ale-quiz-ax { fill: var(--ale-quiz-mute); font: 600 9.5px var(--ale-quiz-sans); stroke: none; }
  & .ale-quiz-ax.is-n { font: 600 9px var(--ale-quiz-mono); fill: var(--ale-quiz-faint); }
  & .ale-quiz-dt { stroke: var(--ale-quiz-card); stroke-width: 2; transition: cy .6s var(--ale-quiz-spring), r .4s var(--ale-quiz-spring); }
  & .ale-quiz-dt.is-ok { fill: var(--ale-quiz-ok); } & .ale-quiz-dt.is-bad { fill: var(--ale-quiz-bad); } & .ale-quiz-dt.is-none { fill: none; stroke: var(--ale-quiz-line2); stroke-dasharray: 2 2; }
  & .ale-quiz-lbl { font: 700 9.5px var(--ale-quiz-mono); fill: var(--ale-quiz-ink); stroke: none; }
}
.ale-quiz .ale-quiz-topics ul { display: grid; gap: 10px; }
.ale-quiz .ale-quiz-topic {
  display: grid; gap: 4px;
  & div { display: flex; justify-content: space-between; font-size: 12px; }
  & div span { font: 600 11.5px var(--ale-quiz-mono); color: var(--ale-quiz-mute); font-variant-numeric: tabular-nums; }
  & .ale-quiz-tbar { height: 6px; border-radius: 3px; background: var(--ale-quiz-line); display: flex; overflow: hidden; }
  & .ale-quiz-tbar i { height: 100%; transition: flex-grow .6s var(--ale-quiz-ease); }
  & .ale-quiz-tbar i.is-ok { background: var(--ale-quiz-ok); } & .ale-quiz-tbar i.is-bad { background: var(--ale-quiz-bad); }
}

/* tabs (narrow) */
.ale-quiz .ale-quiz-tabs {
  grid-area: tabs; display: none; padding: 4px 6px 6px; border-top: 1px solid var(--ale-quiz-line); background: var(--ale-quiz-side);
  & button { flex: 1; border: 0; background: none; display: grid; justify-items: center; gap: 2px; padding: 6px 4px; border-radius: 10px; font-size: 11px; font-weight: 600; color: var(--ale-quiz-mute); }
  & button svg { width: 20px; height: 20px; }
  & button[aria-selected="true"] { color: var(--ale-quiz-accent); background: var(--ale-quiz-tint); }
}

/* dialog */
.ale-quiz .ale-quiz-dialog { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 16px; background: color-mix(in oklch, var(--ale-quiz-ink) 30%, transparent); transition: opacity .25s; @starting-style { opacity: 0; } }
.ale-quiz .ale-quiz-dsheet {
  width: min(400px, 100%); padding: 20px; border-radius: 16px; background: var(--ale-quiz-card); display: grid; gap: 10px;
  box-shadow: 0 30px 60px -20px color-mix(in oklch, var(--ale-quiz-ink) 50%, transparent);
  transition: transform .45s var(--ale-quiz-spring); @starting-style { transform: translateY(12px) scale(.97); }
  & h2 { font-size: 17px; font-weight: 720; }
  & p { color: var(--ale-quiz-mute); line-height: 1.5; text-wrap: pretty; }
  & div { display: flex; justify-content: flex-end; gap: 8px; margin-top: 6px; }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 1080px) {
  .ale-quiz .ale-quiz-app { grid-template-columns: 208px minmax(0, 1fr) 260px; }
}
@container (max-width: 959px) {
  .ale-quiz .ale-quiz-app { grid-template-columns: 200px minmax(0, 1fr); grid-template-areas: "top top" "side main" "tabs tabs"; }
  .ale-quiz .ale-quiz-tabs { display: flex; }
  .ale-quiz .ale-quiz-tabs [data-view="list"] { display: none; }
  .ale-quiz .ale-quiz-score { grid-area: main; border-left: 0; }
  .ale-quiz[data-view="score"] .ale-quiz-main, .ale-quiz:not([data-view="score"]) .ale-quiz-score { display: none; }
}
@container (max-width: 759px) {
  .ale-quiz .ale-quiz-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "tabs"; }
  .ale-quiz .ale-quiz-tabs [data-view="list"] { display: grid; }
  .ale-quiz .ale-quiz-side { grid-area: main; border-right: 0; }
  .ale-quiz:not([data-view="list"]) .ale-quiz-side, .ale-quiz[data-view="list"] .ale-quiz-main { display: none; }
  .ale-quiz .ale-quiz-top { padding: 12px 14px; gap: 10px; }
  .ale-quiz .ale-quiz-mark { display: none; }
}
@container (max-width: 480px) {
  .ale-quiz .ale-quiz-confs { grid-template-columns: 1fr; }
  .ale-quiz .ale-quiz-cf { grid-template-columns: 1fr auto; align-items: center; }
  .ale-quiz .ale-quiz-rgrid { grid-template-columns: 1fr 1fr; }
  .ale-quiz .ale-quiz-foot .ale-quiz-hint { display: none; }
  .ale-quiz .ale-quiz-btn kbd, .ale-quiz .ale-quiz-cf b kbd { display: none; }
  .ale-quiz .ale-quiz-ttl p { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .ale-quiz *, .ale-quiz *::before, .ale-quiz *::after { animation-duration: 1ms !important; animation-delay: 0s !important; transition-duration: 1ms !important; }
}

