/* Fernhill College — a calibrated quiz.
   Every answer carries a stated confidence that sets its stake (+1/0, +2/−1, +3/−4).
   Those stakes make each choice the best bet in one band of real probability
   (under 50%, 50–75%, over 75%), and the calibration chart plots how often you were
   right in each band — from the same answer log that produces the score. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const KEYS = 'ABCDE';
const I = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  flag: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 20.5V4.5M6 5h11l-2.5 4L17 13H6"/></svg>',
  grip: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6h.01M15 6h.01M9 12h.01M15 12h.01M9 18h.01M15 18h.01" stroke-width="3"/></svg>',
  up: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 14 6-6 6 6"/></svg>',
  down: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 10 6 6 6-6"/></svg>',
  left: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5m6-6-6 6 6 6"/></svg>',
  right: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>',
};
const TOPICS = ['Circulation', 'Carbon & chemistry', 'Heat & structure'];
const CONF = [
  { name: 'Guessing', win: 1, lose: 0, lo: 0, hi: 50 },
  { name: 'Fairly sure', win: 2, lose: -1, lo: 50, hi: 75 },
  { name: 'Certain', win: 3, lose: -4, lo: 75, hi: 100 },
];
const Q = [
  { t: 0, type: 'single', short: 'What drives the deep circulation', prompt: 'What mainly drives the thermohaline circulation?',
    opts: ['Wind stress on the sea surface', 'Differences in water density from temperature and salinity', 'The pull of the Moon on the open ocean', 'Heat escaping from mid-ocean ridges'], ans: 1,
    why: 'Cold, salty water is dense. It sinks in the North Atlantic and around Antarctica, and that sinking pulls the deep “conveyor”. Wind drives the surface gyres, not the deep flow.', ref: 'Unit 4 reading, p. 108' },
  { t: 1, type: 'multi', short: 'What happens as the ocean takes up CO₂', prompt: 'Which of these happen as the ocean absorbs more CO₂?',
    opts: ['Surface pH falls', 'Carbonate ion concentration falls', 'Seawater becomes more alkaline', 'Shell-building gets harder for some plankton', 'Dissolved oxygen rises'], ans: [0, 1, 3],
    why: 'CO₂ forms carbonic acid, which releases hydrogen ions (lower pH) and uses up carbonate ions. With less carbonate, calcium-carbonate shells cost more to build. The ocean is still alkaline at a pH near 8.05 — just less so.', ref: 'Unit 4 reading, p. 121' },
  { t: 0, type: 'order', short: 'The path of a Gulf Stream parcel', prompt: 'Put the journey of a Gulf Stream water parcel in order, starting in the tropics.',
    opts: ['Warmed at the surface in the Caribbean', 'Carried north-east along the North American coast', 'Gives up heat to the air near Iceland', 'Sinks as North Atlantic Deep Water'],
    why: 'Warm surface water travels north-east, releases its heat to the atmosphere at high latitude, becomes cold and dense, and sinks — the start of the deep return flow.', ref: 'Lecture 9 slides, 14–18' },
  { t: 2, type: 'num', short: 'Thermal expansion of a water column', prompt: 'A 1,000 m column of seawater warms by 1 °C. With an expansion coefficient of 2 × 10⁻⁴ per °C, how many centimetres does its surface rise?',
    unit: 'cm', ans: 20, tol: 1, why: 'Δh = h × α × ΔT = 1,000 m × 0.0002 × 1 = 0.2 m, which is 20 cm. Small per degree, large over a whole ocean.', ref: 'Problem set 4, question 2' },
  { t: 2, type: 'single', short: 'What does not raise sea level', prompt: 'Which of these does not raise global mean sea level?',
    opts: ['Melting of the Greenland ice sheet', 'Warming of the upper ocean', 'Melting of Arctic sea ice', 'Retreat of mountain glaciers'], ans: 2,
    why: 'Sea ice already floats and displaces its own weight of water, so melting it barely changes sea level. Ice on land and warming water both add volume.', ref: 'Unit 4 reading, p. 131' },
  { t: 1, type: 'single', short: 'The ocean’s share of our CO₂', prompt: 'Roughly what share of the CO₂ people have emitted since 1850 has the ocean taken up?',
    opts: ['About 5%', 'About 25%', 'About 60%', 'About 90%'], ans: 1,
    why: 'The ocean has absorbed roughly a quarter of cumulative emissions. Land plants and soils took up a similar share; the rest stayed in the air.', ref: 'Lecture 10 slides, 6' },
  { t: 0, type: 'multi', short: 'True statements about upwelling', prompt: 'Which statements about coastal upwelling are true?',
    opts: ['It brings cold, nutrient-rich water to the surface', 'It is driven by winds blowing along the shore', 'It warms the sea surface near the coast', 'Some of the richest fisheries sit over upwelling zones'], ans: [0, 1, 3],
    why: 'Along-shore winds and the Coriolis effect push surface water offshore (Ekman transport) and deep water rises to replace it. It cools the coast and feeds plankton — and the fish that eat them.', ref: 'Unit 4 reading, p. 114' },
  { t: 1, type: 'num', short: 'pH and hydrogen ions', prompt: 'Surface pH has fallen from about 8.2 to 8.1. By what factor has the hydrogen ion concentration grown? Give one decimal place.',
    unit: '×', ans: 1.3, tol: 0.05, why: 'pH is a base-10 logarithm, so a 0.1 drop multiplies [H⁺] by 10^0.1 ≈ 1.26 — roughly 26% more hydrogen ions.', ref: 'Problem set 4, question 5' },
  { t: 2, type: 'order', short: 'Layers of the ocean, top down', prompt: 'Order these layers of the open ocean from the surface down.',
    opts: ['Mixed layer, stirred by wind and waves', 'Thermocline, where temperature drops fast', 'Deep water, cold and slow', 'Bottom water, the densest of all'],
    why: 'Wind mixes the top tens of metres; below it the thermocline separates warm surface water from the cold deep ocean, and the densest water hugs the sea floor.', ref: 'Lecture 8 slides, 3' },
  { t: 2, type: 'single', short: 'Where the extra heat went', prompt: 'Over the last 50 years, where has most of the extra heat trapped by greenhouse gases gone?',
    opts: ['Into the atmosphere', 'Into melting ice', 'Into the ocean', 'Into the land surface'], ans: 2,
    why: 'About 90% of the excess energy has been stored in the ocean. The atmosphere holds only a percent or two — which is why ocean heat content is the steadiest signal of warming.', ref: 'Unit 4 reading, p. 103' },
];
const SCRAMBLE = [[2, 0, 3, 1], [1, 3, 0, 2]];
const fresh = () => Q.map((q, i) => ({ pick: q.type === 'multi' ? [] : null, conf: null, checked: false, ok: null, pts: 0, flag: false, val: '', order: q.type === 'order' ? (i === 2 ? SCRAMBLE[0] : SCRAMBLE[1]).slice() : null }));
const S = { cur: 3, filter: 'all', view: 'q', results: false, dir: 1, a: fresh(), msg: '' };
/* three answered already, one flagged */
Object.assign(S.a[0], { pick: 1, conf: 2, checked: true, ok: true, pts: 3 });
Object.assign(S.a[1], { pick: [0, 1], conf: 1, checked: true, ok: false, pts: -1 });
Object.assign(S.a[2], { order: [0, 1, 2, 3], conf: 1, checked: true, ok: true, pts: 2 });
S.a[5].flag = true;

const main = $('[data-main]');
const score = () => S.a.reduce((n, a) => n + a.pts, 0);
const answered = () => S.a.filter(a => a.checked).length;

/* ── checking ───────────────────────────────────────── */
function ready(i) {
  const q = Q[i], a = S.a[i];
  if (a.conf == null) return false;
  if (q.type === 'single') return a.pick != null;
  if (q.type === 'multi') return a.pick.length > 0;
  if (q.type === 'num') return a.val.trim() !== '';
  return true;
}
function correct(i) {
  const q = Q[i], a = S.a[i];
  if (q.type === 'single') return a.pick === q.ans;
  if (q.type === 'multi') return a.pick.length === q.ans.length && q.ans.every(k => a.pick.includes(k));
  if (q.type === 'order') return a.order.every((k, j) => k === j);
  return Math.abs(parseFloat(a.val.replace(',', '.')) - q.ans) <= q.tol + 1e-9;
}
let lastDelta = 0;
function check() {
  const i = S.cur, q = Q[i], a = S.a[i];
  if (a.checked) return;
  if (!ready(i)) {
    S.msg = a.conf == null && (q.type === 'order' || hasAnswer(i)) ? 'Choose how sure you are — it sets the stake.' : q.type === 'num' ? 'Type a number first.' : q.type === 'multi' ? 'Select at least one option.' : 'Pick an answer first.';
    return renderQuestion(false);
  }
  if (q.type === 'num' && !isFinite(parseFloat(a.val.replace(',', '.')))) { S.msg = 'That isn’t a number — try something like 12.5'; return renderQuestion(false); }
  a.checked = true; a.ok = correct(i);
  const c = CONF[a.conf]; a.pts = a.ok ? c.win : c.lose;
  lastDelta = a.pts; S.msg = '';
  renderAll(false);
  const nx = $('[data-act="next"]', main); if (nx) nx.focus({ preventScroll: true });
}
const hasAnswer = i => { const q = Q[i], a = S.a[i]; return q.type === 'single' ? a.pick != null : q.type === 'multi' ? a.pick.length > 0 : q.type === 'num' ? a.val.trim() !== '' : true; };

/* ── rendering ───────────────────────────────────────── */
function renderNav() {
  const list = Q.map((q, i) => i).filter(i => S.filter === 'all' || (S.filter === 'flag' ? S.a[i].flag : S.a[i].checked && !S.a[i].ok));
  $('[data-nav]').innerHTML = list.length ? list.map(i => {
    const a = S.a[i], st = a.checked ? (a.ok ? ' is-ok' : ' is-bad') : '';
    return '<li><button type="button" class="ale-quiz-qi' + st + '" data-go="' + i + '" aria-current="' + (i === S.cur && !S.results) + '"><span class="ale-quiz-dot">' + (a.checked ? (a.ok ? I.check : I.x) : i + 1) + '</span><span><b>' + esc(Q[i].short) + '</b><small>' + TOPICS[Q[i].t] + (a.checked ? ' · ' + (a.pts > 0 ? '+' : a.pts < 0 ? '−' : '') + Math.abs(a.pts) + ' pts' : '') + '</small></span>' + (a.flag ? '<svg class="ale-quiz-fl" viewBox="0 0 24 24" aria-label="Flagged"><path d="M6 20.5V4.5M6 5h11l-2.5 4L17 13H6"/></svg>' : '<span></span>') + '</button></li>';
  }).join('') : '<li style="padding:20px 12px;color:var(--ale-quiz-faint);font-size:12px;text-align:center">' + (S.filter === 'flag' ? 'Nothing flagged. Press F on a question to mark it for later.' : 'No missed questions yet.') + '</li>';
}
function stakeHTML(c) { return '<span><em>+' + c.win + '</em> / ' + (c.lose < 0 ? '<i>−' + Math.abs(c.lose) + '</i>' : '0') + '</span>'; }
function optionsHTML(i) {
  const q = Q[i], a = S.a[i], locked = a.checked;
  if (q.type === 'single' || q.type === 'multi') {
    const multi = q.type === 'multi';
    return '<div class="ale-quiz-opts" role="' + (multi ? 'group' : 'radiogroup') + '" aria-label="Answers">' + q.opts.map((o, k) => {
      const on = multi ? a.pick.includes(k) : a.pick === k, good = multi ? q.ans.includes(k) : q.ans === k;
      let cls = '';
      if (locked) cls = good && on ? ' is-right' : on ? ' is-wrong' : good ? (multi ? ' is-missed' : ' is-right') : '';
      return '<button type="button" class="ale-quiz-opt' + cls + '" role="' + (multi ? 'checkbox' : 'radio') + '" aria-checked="' + on + '" data-opt="' + k + '" style="--i:' + k + '"' + (locked ? ' aria-disabled="true"' : '') + (!multi ? ' tabindex="' + ((a.pick == null ? k === 0 : on) ? 0 : -1) + '"' : '') + '>' +
        '<span class="ale-quiz-key">' + KEYS[k] + '</span><span class="ale-quiz-txt">' + esc(o) + '</span><span class="ale-quiz-mk">' + (locked && (good || on) ? (good ? I.check : I.x) : '') + '</span></button>';
    }).join('') + '</div>';
  }
  if (q.type === 'order') {
    return '<ol class="ale-quiz-order" data-order aria-label="Drag, or use the arrows, to reorder">' + a.order.map((k, pos) => {
      const st = locked ? (k === pos ? ' is-right' : ' is-wrong') : '';
      return '<li class="ale-quiz-ord' + st + '" data-item="' + k + '" style="--i:' + pos + '" tabindex="' + (locked ? -1 : 0) + '" aria-label="' + esc(q.opts[k]) + ', position ' + (pos + 1) + ' of ' + a.order.length + '">' +
        '<span class="ale-quiz-grip"' + (locked ? ' style="cursor:default;opacity:.3"' : '') + ' aria-hidden="true">' + I.grip + '</span><span class="ale-quiz-pos">' + (pos + 1) + '</span><span class="ale-quiz-txt">' + esc(q.opts[k]) + '</span>' +
        (locked ? (k === pos ? '<span class="ale-quiz-mk" style="color:var(--ale-quiz-ok)">' + I.check + '</span>' : '<span class="ale-quiz-should">goes ' + (k + 1) + '</span>') :
          '<span class="ale-quiz-mv"><button type="button" data-mv="-1" aria-label="Move up"' + (pos === 0 ? ' disabled title="Already first"' : '') + '>' + I.up + '</button><button type="button" data-mv="1" aria-label="Move down"' + (pos === a.order.length - 1 ? ' disabled title="Already last"' : '') + '>' + I.down + '</button></span>') + '</li>';
    }).join('') + '</ol>';
  }
  const st = locked ? (a.ok ? ' is-right' : ' is-wrong') : '';
  return '<div class="ale-quiz-numrow"><label class="' + st.trim() + '"><input type="text" inputmode="decimal" autocomplete="off" aria-label="Your answer in ' + q.unit + '" data-num value="' + esc(a.val) + '"' + (locked ? ' readonly' : '') + ' placeholder="0"><span>' + q.unit + '</span></label>' +
    (locked ? '<p>' + (a.ok ? 'Within the tolerance of ±' + q.tol + ' ' + q.unit : 'Expected ' + q.ans + ' ' + q.unit + ' (±' + q.tol + ')') + '</p>' : '<p>Answers within ±' + q.tol + ' ' + q.unit + ' count.</p>') + '</div>';
}
function renderQuestion(enter) {
  if (S.results) return renderResults();
  const i = S.cur, q = Q[i], a = S.a[i], locked = a.checked, c = a.conf != null ? CONF[a.conf] : null;
  const all = answered() === Q.length;
  const sub = q.type === 'multi' ? 'Select all that apply.' : q.type === 'order' ? 'Drag the handles, or use the arrows. Alt + ↑/↓ moves the focused row.' : q.type === 'num' ? '' : '';
  main.innerHTML = '<article class="ale-quiz-card" style="--dir:' + (enter ? S.dir : 0) + (enter ? '' : ';animation:none') + '">' +
    '<header class="ale-quiz-qh"><span class="ale-quiz-num">Question ' + (i + 1) + ' of ' + Q.length + '</span><span class="ale-quiz-chip">' + TOPICS[q.t] + '</span><span class="ale-quiz-chip">' + { single: 'One answer', multi: 'Several answers', order: 'Put in order', num: 'Number' }[q.type] + '</span>' +
    '<button type="button" class="ale-quiz-flag" data-act="flag" aria-pressed="' + a.flag + '">' + I.flag + (a.flag ? 'Flagged' : 'Flag') + ' <kbd>F</kbd></button></header>' +
    '<h2 class="ale-quiz-prompt" id="ale-quiz-prompt">' + esc(q.prompt) + '</h2>' + (sub ? '<p class="ale-quiz-sub">' + sub + '</p>' : '') +
    optionsHTML(i) +
    '<fieldset class="ale-quiz-conf"><legend>How sure are you?<span>Only say Certain if you’d be right at least 3 times in 4.</span></legend><div class="ale-quiz-confs" role="radiogroup" aria-label="Confidence">' +
    CONF.map((cf, k) => '<button type="button" role="radio" class="ale-quiz-cf" data-conf="' + k + '" aria-checked="' + (a.conf === k) + '" tabindex="' + ((a.conf == null ? k === 0 : a.conf === k) ? 0 : -1) + '"' + (locked ? ' aria-disabled="true"' : '') + '><b>' + cf.name + ' <kbd>' + (k + 1) + '</kbd></b>' + stakeHTML(cf) + '</button>').join('') + '</div></fieldset>' +
    (locked ? '<div class="ale-quiz-why" style="--c:' + (a.ok ? 'var(--ale-quiz-ok)' : 'var(--ale-quiz-bad)') + '"><div><div class="ale-quiz-wbox"><h3>' + (a.ok ? 'Right' : 'Not quite') + '<span class="ale-quiz-pts">' + (a.pts > 0 ? '+' : a.pts < 0 ? '−' : '±') + Math.abs(a.pts) + ' at “' + c.name + '”</span></h3><p>' + esc(q.why) + '</p><small>' + esc(q.ref) + '</small></div></div></div>' : '') +
    '<footer class="ale-quiz-foot"><span class="ale-quiz-hint"' + (S.msg ? ' style="color:var(--ale-quiz-bad);font-weight:600" role="alert"' : '') + '>' + (S.msg || (locked ? 'Enter for the next question' : q.type === 'order' ? 'Press 1–3 for confidence, Enter to check' : 'Press ' + (q.type === 'num' ? '' : 'A–' + KEYS[q.opts.length - 1] + ' to answer, ') + '1–3 for confidence, Enter to check')) + '</span>' +
    '<button type="button" class="ale-quiz-btn" data-act="prev"' + (i === 0 ? ' disabled title="This is the first question"' : '') + '>' + I.left + 'Back</button>' +
    (locked ? (all ? '<button type="button" class="ale-quiz-btn is-pri" data-act="results">See results <kbd>↵</kbd></button>' : '<button type="button" class="ale-quiz-btn is-pri" data-act="next">Next ' + I.right + '</button>')
      : '<button type="button" class="ale-quiz-btn is-pri" data-act="check"' + (ready(i) ? '' : ' aria-disabled="true" title="Pick an answer and how sure you are"') + '>Check answer <kbd>↵</kbd></button>') +
    '</footer></article>';
  if (enter) main.scrollTop = 0;
}
function calSVG(w, h, big) {
  const L = 34, R = w - 10, T = 10, B = h - 30, cw = (R - L) / 3;
  const y = p => B - (B - T) * p / 100;
  let s = '<g class="ale-quiz-calsvg">';
  [0, 50, 75, 100].forEach(p => { s += '<line class="ale-quiz-gl" x1="' + L + '" x2="' + R + '" y1="' + y(p) + '" y2="' + y(p) + '"/><text class="ale-quiz-ax is-n" x="' + (L - 6) + '" y="' + (y(p) + 3) + '" text-anchor="end">' + p + '%</text>'; });
  CONF.forEach((c, k) => {
    const x = L + cw * k + 6, cx = L + cw * (k + 0.5);
    s += '<rect class="ale-quiz-band" x="' + x + '" width="' + (cw - 12) + '" y="' + y(c.hi) + '" height="' + (y(c.lo) - y(c.hi)) + '" rx="4"/>';
    s += '<text class="ale-quiz-ax" x="' + cx + '" y="' + (B + 16) + '" text-anchor="middle">' + c.name + '</text>';
    const xs = S.a.filter(a => a.checked && a.conf === k), n = xs.length, r = xs.filter(a => a.ok).length;
    if (!n) { s += '<circle class="ale-quiz-dt is-none" cx="' + cx + '" cy="' + y((c.lo + c.hi) / 2) + '" r="5"/>'; return; }
    const acc = 100 * r / n, inside = acc >= c.lo - 1e-9 && acc <= c.hi + 1e-9;
    s += '<circle class="ale-quiz-dt ' + (inside ? 'is-ok' : 'is-bad') + '" cx="' + cx + '" cy="' + y(acc) + '" r="' + ((big ? 6 : 4.5) + Math.min(5, n) * (big ? 1.4 : 1)) + '"/>';
    s += '<text class="ale-quiz-lbl" x="' + (cx + 12 + Math.min(5, n)) + '" y="' + (y(acc) + 3.5) + '">' + r + '/' + n + '</text>';
  });
  return s + '</g>';
}
function calVerdict() {
  let over = 0, under = 0, n = 0;
  CONF.forEach((c, k) => { const xs = S.a.filter(a => a.checked && a.conf === k); if (!xs.length) return; n += xs.length; const acc = 100 * xs.filter(a => a.ok).length / xs.length; if (acc < c.lo) over++; else if (acc > c.hi) under++; });
  if (n < 3) return ['Answer a few more', 'var(--ale-quiz-faint)'];
  if (over && !under) return ['Overconfident', 'var(--ale-quiz-bad)'];
  if (under && !over) return ['Underconfident', 'oklch(0.62 0.14 70)'];
  if (over && under) return ['Mixed', 'oklch(0.62 0.14 70)'];
  return ['Well calibrated', 'var(--ale-quiz-ok)'];
}
function renderScore() {
  const sc = score(), n = answered(), right = S.a.filter(a => a.checked && a.ok).length;
  const b = $('[data-score]'); b.style.setProperty('--ale-quiz-n', sc);
  b.setAttribute('aria-label', sc + ' points');
  $('[data-scoresub]').textContent = 'of a possible ' + Q.length * 3 + ' · best still reachable ' + (sc + (Q.length - n) * 3);
  const d = $('[data-delta]');
