@property --ale-lingo-g { syntax: '<number>'; inherits: true; initial-value: 0; }

.ale-lingo {
  /* re-theme with these four */
  --ale-lingo-bg: oklch(0.2 0.018 125);
  --ale-lingo-ink: oklch(0.95 0.015 100);
  --ale-lingo-accent: oklch(0.68 0.19 32);
  --ale-lingo-ok: oklch(0.78 0.16 140);
  /* derived */
  --ale-lingo-panel: color-mix(in oklch, var(--ale-lingo-bg) 92%, var(--ale-lingo-ink));
  --ale-lingo-tile: color-mix(in oklch, var(--ale-lingo-bg) 86%, var(--ale-lingo-ink));
  --ale-lingo-line: color-mix(in oklch, var(--ale-lingo-ink) 11%, transparent);
  --ale-lingo-line2: color-mix(in oklch, var(--ale-lingo-ink) 20%, transparent);
  --ale-lingo-mute: color-mix(in oklch, var(--ale-lingo-ink) 62%, var(--ale-lingo-bg));
  --ale-lingo-faint: color-mix(in oklch, var(--ale-lingo-ink) 36%, var(--ale-lingo-bg));
  --ale-lingo-hover: color-mix(in oklch, var(--ale-lingo-ink) 7%, transparent);
  --ale-lingo-sel: oklch(0.78 0.11 230);
  --ale-lingo-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-lingo-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-lingo-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-lingo-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-lingo-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-lingo-bg); color: var(--ale-lingo-ink); color-scheme: dark; accent-color: var(--ale-lingo-accent);
  font: 14px/1.45 var(--ale-lingo-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-lingo-sel); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h1, & h2, & h3, & p, & ul, & ol { margin: 0; padding: 0; font: inherit; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--ale-lingo-mono); padding: 3px 5px; display: inline-block; border: 1px solid currentColor; border-radius: 5px; opacity: .6; }
}
.ale-lingo .ale-lingo-app { height: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "top top" "main side"; }

/* ── top bar ─────────────────────────────── */
.ale-lingo .ale-lingo-top { grid-area: top; display: flex; align-items: center; gap: 16px; padding: 14px 20px; border-bottom: 1px solid var(--ale-lingo-line); }
.ale-lingo .ale-lingo-ib {
