  & i::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--ale-lingo-ok); transform: scaleX(0); transform-origin: left; transition: transform .6s var(--ale-lingo-spring); box-shadow: inset 0 3px 0 oklch(1 0 none / .28); }
