  &:hover:not(:disabled) { background: color-mix(in oklch, var(--ale-lingo-tile) 90%, var(--ale-lingo-ink)); }
  &:active:not(:disabled) { transform: translateY(2px); border-bottom-width: 2px; margin-top: 2px; height: 43px; }
  &.is-slot { visibility: visible; color: transparent; background: var(--ale-lingo-line); border-color: transparent; border-bottom-width: 2px; margin-top: 2px; height: 43px; pointer-events: none; }
  &.is-slot sup { display: none; }
}
.ale-lingo .ale-lingo-match { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 14px; }
.ale-lingo .ale-lingo-mb {
  height: 52px; border-radius: 12px; border: 2px solid var(--ale-lingo-line2); border-bottom-width: 4px; background: var(--ale-lingo-tile); font-size: 15px; font-weight: 550;
  display: flex; align-items: center; gap: 10px; padding: 0 14px;
  transition: border-color .15s, background .15s, opacity .35s, transform .3s var(--ale-lingo-spring);
  & kbd { margin-left: auto; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--ale-lingo-tile) 90%, var(--ale-lingo-ink)); }
  &[aria-pressed="true"] { border-color: var(--ale-lingo-sel); background: color-mix(in oklch, var(--ale-lingo-sel) 16%, var(--ale-lingo-tile)); color: var(--ale-lingo-sel); }
  &.is-done { opacity: .35; border-color: var(--ale-lingo-ok); color: var(--ale-lingo-ok); }
  &.is-miss { animation: ale-lingo-shake .45s var(--ale-lingo-ease); border-color: var(--ale-lingo-accent); color: var(--ale-lingo-accent); }
  &.is-hit { animation: ale-lingo-hit .5s var(--ale-lingo-spring); }
}
@keyframes ale-lingo-shake { 20% { transform: translateX(-6px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(2px); } }
@keyframes ale-lingo-hit { 40% { transform: scale(1.05); } }
.ale-lingo .ale-lingo-choices { display: grid; gap: 10px; }
.ale-lingo .ale-lingo-choices.is-row { grid-template-columns: repeat(4, 1fr); }
.ale-lingo .ale-lingo-ch {
  --i: 0;
  min-height: 52px; border-radius: 14px; border: 2px solid var(--ale-lingo-line2); border-bottom-width: 4px; background: var(--ale-lingo-tile); text-align: left; padding: 10px 14px;
  display: flex; align-items: center; gap: 12px; font-size: 15px; text-wrap: pretty;
  animation: ale-lingo-rise .4s var(--ale-lingo-ease) both; animation-delay: calc(var(--i) * 50ms + 120ms);
  transition: border-color .15s, background .15s, color .15s;
  & kbd { flex: none; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--ale-lingo-tile) 90%, var(--ale-lingo-ink)); }
  &[aria-checked="true"] { border-color: var(--ale-lingo-sel); background: color-mix(in oklch, var(--ale-lingo-sel) 16%, var(--ale-lingo-tile)); color: var(--ale-lingo-sel); }
  &.is-big { justify-content: center; font-size: 22px; font-weight: 700; min-height: 76px; }
  &.is-good { border-color: var(--ale-lingo-ok); color: var(--ale-lingo-ok); }
  &.is-bad { border-color: var(--ale-lingo-accent); color: var(--ale-lingo-accent); }
}
@keyframes ale-lingo-rise { from { opacity: 0; transform: translateY(10px); } }
.ale-lingo .ale-lingo-type {
  display: grid; gap: 8px;
  & textarea { width: 100%; min-height: 110px; resize: none; border-radius: 14px; border: 2px solid var(--ale-lingo-line2); background: color-mix(in oklch, var(--ale-lingo-bg) 70%, black); padding: 12px 14px; font-size: 17px; line-height: 1.45; outline: 0; color: var(--ale-lingo-ink); transition: border-color .15s; }
  & textarea:focus { border-color: var(--ale-lingo-sel); }
  & textarea:read-only { opacity: .7; }
  & .ale-lingo-accents { display: flex; gap: 6px; flex-wrap: wrap; }
  & .ale-lingo-accents button { width: 36px; height: 34px; border-radius: 9px; border: 2px solid var(--ale-lingo-line2); border-bottom-width: 3px; background: var(--ale-lingo-tile); font-size: 15px; font-weight: 600; }
  & .ale-lingo-accents button:hover:not(:disabled) { border-color: var(--ale-lingo-mute); }
}
.ale-lingo .ale-lingo-cloze {
  font-size: 19px; line-height: 2.1; text-wrap: pretty;
  & input { width: 9ch; font: 650 19px var(--ale-lingo-sans); text-align: center; background: none; border: 0; border-bottom: 2px solid var(--ale-lingo-sel); color: var(--ale-lingo-ink); outline: 0; padding: 0 4px; }
  & small { display: block; font-size: 12.5px; line-height: 1.4; color: var(--ale-lingo-mute); }
}

/* ── footer & feedback sheet ─────────────────────────────── */
.ale-lingo .ale-lingo-foot { display: flex; align-items: center; gap: 12px; padding: 16px clamp(16px, 4cqi, 48px); border-top: 2px solid var(--ale-lingo-line); }
.ale-lingo .ale-lingo-keys { flex: 1; text-align: center; font-size: 11.5px; color: var(--ale-lingo-faint); }
.ale-lingo .ale-lingo-skip {
  height: 46px; padding: 0 20px; border-radius: 13px; border: 2px solid var(--ale-lingo-line2); border-bottom-width: 4px; background: none; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; font-size: 13px; color: var(--ale-lingo-mute);
  &:hover { color: var(--ale-lingo-ink); background: var(--ale-lingo-hover); }
}
.ale-lingo .ale-lingo-go {
  height: 46px; padding: 0 26px; min-width: 150px; border-radius: 13px; border: 0; box-shadow: inset 0 -4px 0 color-mix(in oklch, var(--ale-lingo-ok) 60%, black);
  background: var(--ale-lingo-ok); color: oklch(0.2 0.04 140); font-weight: 800; letter-spacing: .06em; text-transform: uppercase; font-size: 13px;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  transition: transform .2s var(--ale-lingo-spring), filter .15s, background .2s;
  &:hover:not(:disabled) { filter: brightness(1.06); }
  &:active:not(:disabled) { transform: translateY(2px); box-shadow: inset 0 -2px 0 color-mix(in oklch, var(--ale-lingo-ok) 60%, black); }
  &:disabled { background: var(--ale-lingo-line); color: var(--ale-lingo-faint); box-shadow: none; }
  & kbd { border-color: currentColor; }
}
.ale-lingo .ale-lingo-sheet {
  --c: var(--ale-lingo-ok);
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; padding: 18px clamp(16px, 4cqi, 48px) 16px;
  background: color-mix(in oklch, var(--c) 16%, var(--ale-lingo-bg)); border-top: 2px solid color-mix(in oklch, var(--c) 40%, transparent);
  transition: transform .55s var(--ale-lingo-spring); @starting-style { transform: translateY(100%); }
  &.is-bad { --c: var(--ale-lingo-accent); }
  & .ale-lingo-go { background: var(--c); box-shadow: inset 0 -4px 0 color-mix(in oklch, var(--c) 60%, black); color: color-mix(in oklch, var(--c) 25%, black); }
}
.ale-lingo .ale-lingo-sheetin { max-width: 600px; margin: 0 auto; display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.ale-lingo .ale-lingo-badge { width: 52px; height: 52px; border-radius: 50%; display: grid; place-items: center; background: var(--c); color: var(--ale-lingo-bg); flex: none; & svg { width: 28px; height: 28px; stroke-width: 3; } }
.ale-lingo .ale-lingo-fb {
  flex: 1; min-width: 200px; color: var(--c);
  & h3 { font-size: 19px; font-weight: 800; letter-spacing: -.01em; }
  & p { font-size: 14.5px; line-height: 1.45; color: color-mix(in oklch, var(--c) 70%, var(--ale-lingo-ink)); text-wrap: pretty; }
  & .ale-lingo-diff { font-weight: 650; letter-spacing: .01em; }
  & .ale-lingo-diff ins { text-decoration: none; background: color-mix(in oklch, var(--c) 35%, transparent); color: var(--ale-lingo-ink); border-radius: 3px; padding: 0 1px; }
}

/* ── side ─────────────────────────────── */
.ale-lingo .ale-lingo-side { grid-area: side; overflow: auto; padding: 20px 18px; border-left: 1px solid var(--ale-lingo-line); background: var(--ale-lingo-panel); display: flex; flex-direction: column; gap: 22px; scrollbar-width: thin; & > * { flex: none; } }
.ale-lingo .ale-lingo-goal {
  display: flex; align-items: center; gap: 14px;
  & p { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-lingo-mute); }
  & h2 { font-size: 17px; font-weight: 780; font-variant-numeric: tabular-nums; }
  & span { font-size: 12px; color: var(--ale-lingo-mute); }
}
.ale-lingo .ale-lingo-ring {
  position: relative; width: 64px; height: 64px; display: grid; place-items: center; flex: none; transition: --ale-lingo-g 1s var(--ale-lingo-ease);
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); stroke-width: 7; }
  & circle:first-child { stroke: var(--ale-lingo-line); }
  & circle:last-child { stroke: oklch(0.82 0.15 70); stroke-dasharray: var(--ale-lingo-g) 100; }
  & b { font: 800 14px var(--ale-lingo-sans); font-variant-numeric: tabular-nums; }
}
.ale-lingo .ale-lingo-tip {
  padding: 14px 16px; border-radius: 14px; border: 2px solid var(--ale-lingo-line); display: grid; gap: 6px;
  animation: ale-lingo-rise .5s var(--ale-lingo-ease) both;
  & p:first-child { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-lingo-ok); }
  & h3 { font-size: 15px; font-weight: 720; text-wrap: balance; }
  & p { font-size: 13px; color: var(--ale-lingo-mute); line-height: 1.5; text-wrap: pretty; }
  & b { color: var(--ale-lingo-ink); }
}
.ale-lingo .ale-lingo-words {
  & header { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px; }
  & h2 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-lingo-mute); }
  & header span { font-size: 11.5px; color: var(--ale-lingo-faint); font-variant-numeric: tabular-nums; }
  & ul { display: grid; gap: 2px; }
}
.ale-lingo .ale-lingo-w {
  display: grid; grid-template-columns: 1fr auto; gap: 0 10px; align-items: center; padding: 7px 8px; border-radius: 9px;
  & b { font-weight: 650; font-size: 13.5px; }
  & span { grid-column: 1; font-size: 12px; color: var(--ale-lingo-mute); }
  & i { grid-row: 1 / 3; grid-column: 2; display: flex; gap: 2px; align-items: flex-end; height: 16px; }
  & i u { width: 4px; border-radius: 2px; background: var(--ale-lingo-line2); text-decoration: none; transition: background .4s; }
  & i u:nth-child(1) { height: 6px; } & i u:nth-child(2) { height: 9px; } & i u:nth-child(3) { height: 12px; } & i u:nth-child(4) { height: 16px; }
  & i u.is-on { background: oklch(0.82 0.15 70); }
  &.is-fresh { background: color-mix(in oklch, var(--ale-lingo-ok) 12%, transparent); animation: ale-lingo-hit .6s var(--ale-lingo-spring); }
}

/* ── modal & end screen ─────────────────────────────── */
.ale-lingo .ale-lingo-modal { position: absolute; inset: 0; z-index: 20; display: grid; place-items: center; padding: 16px; background: oklch(0.1 0.01 125 / .65); backdrop-filter: blur(3px); transition: opacity .25s; @starting-style { opacity: 0; } }
.ale-lingo .ale-lingo-msheet {
  width: min(400px, 100%); padding: 22px; border-radius: 18px; background: var(--ale-lingo-panel); border: 2px solid var(--ale-lingo-line2); display: grid; gap: 12px; text-align: center; justify-items: center;
  transition: transform .5s var(--ale-lingo-spring); @starting-style { transform: translateY(16px) scale(.96); }
  & h2 { font-size: 20px; font-weight: 800; text-wrap: balance; }
  & p { color: var(--ale-lingo-mute); text-wrap: pretty; }
  & .ale-lingo-mrow { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; }
  & .ale-lingo-big { font-size: 46px; line-height: 1; }
}
.ale-lingo .ale-lingo-ghost-btn { height: 46px; padding: 0 20px; border-radius: 13px; border: 2px solid var(--ale-lingo-line2); border-bottom-width: 4px; background: none; font-weight: 750; text-transform: uppercase; letter-spacing: .06em; font-size: 13px; &:hover { background: var(--ale-lingo-hover); } }
.ale-lingo .ale-lingo-end {
  max-width: 520px; margin: 0 auto; display: grid; gap: 18px; justify-items: center; text-align: center; padding-top: 10px;
  animation: ale-lingo-in .5s var(--ale-lingo-ease) both;
  & > svg { width: 96px; height: 96px; stroke: none; animation: ale-lingo-hit .8s var(--ale-lingo-spring) .1s both; }
  & h2 { font-size: clamp(22px, 2cqi + 12px, 30px); font-weight: 820; letter-spacing: -.02em; color: oklch(0.82 0.15 70); }
  & p { color: var(--ale-lingo-mute); max-width: 42ch; text-wrap: pretty; }
}
.ale-lingo .ale-lingo-stats { display: grid; grid-template-columns: repeat(3, minmax(0, 120px)); gap: 10px; }
.ale-lingo .ale-lingo-stat {
  --i: 0; --c: oklch(0.82 0.15 70);
  border-radius: 14px; border: 2px solid var(--c); overflow: hidden; animation: ale-lingo-rise .5s var(--ale-lingo-ease) both; animation-delay: calc(var(--i) * 90ms + 250ms);
  & p { background: var(--c); color: var(--ale-lingo-bg); font-size: 10.5px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; padding: 4px; }
  & b { display: block; padding: 10px 4px; font-size: 20px; font-weight: 800; color: var(--c); font-variant-numeric: tabular-nums; }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 959px) {
  .ale-lingo .ale-lingo-app { grid-template-columns: minmax(0, 1fr) 248px; }
  .ale-lingo .ale-lingo-say svg.ale-lingo-av { width: 60px; height: 70px; }
}
@container (max-width: 759px) {
  .ale-lingo .ale-lingo-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main"; }
  .ale-lingo .ale-lingo-side { grid-area: main; border-left: 0; }
  .ale-lingo .ale-lingo-wordsbtn { display: inline-flex; }
  .ale-lingo[data-view="lesson"] .ale-lingo-side, .ale-lingo[data-view="words"] .ale-lingo-main { display: none; }
  .ale-lingo .ale-lingo-top { gap: 10px; padding: 12px 14px; }
  .ale-lingo .ale-lingo-keys { display: none; }
  .ale-lingo .ale-lingo-foot { justify-content: space-between; }
}
@container (max-width: 480px) {
  .ale-lingo .ale-lingo-streak, .ale-lingo .ale-lingo-wordsbtn span { display: none; }
  .ale-lingo .ale-lingo-wordsbtn { padding: 0 9px; }
  .ale-lingo .ale-lingo-hearts svg { width: 18px; height: 18px; }
  .ale-lingo .ale-lingo-say svg.ale-lingo-av { display: none; }
  .ale-lingo .ale-lingo-say p::before { display: none; }
  .ale-lingo .ale-lingo-say p { margin-bottom: 0; }
  .ale-lingo .ale-lingo-choices.is-row { grid-template-columns: 1fr 1fr; }
  .ale-lingo .ale-lingo-go { min-width: 0; flex: 1; }
  .ale-lingo .ale-lingo-tile { height: 42px; padding: 0 11px; font-size: 15px; }
  .ale-lingo .ale-lingo-line { background: repeating-linear-gradient(to bottom, transparent 0 48px, var(--ale-lingo-line2) 48px 50px); }
  .ale-lingo .ale-lingo-mb kbd, .ale-lingo .ale-lingo-ch kbd, .ale-lingo .ale-lingo-tile sup { display: none; }
  .ale-lingo .ale-lingo-stats { grid-template-columns: repeat(3, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .ale-lingo *, .ale-lingo *::before, .ale-lingo *::after { animation-duration: 1ms !important; animation-delay: 0s !important; transition-duration: 1ms !important; }
}

