/* Parola — Italian, unit 3 "Al mercato".
   Word tiles FLIP between the bank and the answer line while the bank keeps their empty
   slots, typed answers are compared accent- and punctuation-insensitively with an
   edit-distance diff, and a missed exercise goes back to the end of the queue. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const I = {
  ok: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  no: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  heart: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s-7.5-4.6-9-9.6C1.9 7.2 4.3 4 7.6 4c2 0 3.4 1.1 4.4 2.6C13 5.1 14.4 4 16.4 4c3.3 0 5.7 3.2 4.6 6.9-1.5 5-9 9.6-9 9.6Z"/></svg>',
};
const AV = '<svg class="ale-lingo-av" viewBox="0 0 74 86" aria-hidden="true"><path d="M8 86c0-17 12-27 29-27s29 10 29 27z" fill="oklch(0.62 0.15 32)"/><path d="M24 62h26l-3 24H27z" fill="oklch(0.93 0.02 95)"/><path d="M30 66h14" stroke="oklch(0.62 0.15 32)" stroke-width="2"/><circle cx="37" cy="36" r="17" fill="oklch(0.8 0.07 60)"/><path d="M19 36c0-12 8-19 18-19s18 7 18 19c-3-6-8-9-14-9-5 0-12 2-15 9" fill="oklch(0.32 0.04 50)"/><circle cx="50" cy="16" r="7" fill="oklch(0.32 0.04 50)"/><circle cx="31" cy="38" r="1.8" fill="oklch(0.25 0.03 50)"/><circle cx="43" cy="38" r="1.8" fill="oklch(0.25 0.03 50)"/><path d="M32 45c3 2.4 7 2.4 10 0" stroke="oklch(0.35 0.08 30)" stroke-width="2" fill="none" stroke-linecap="round"/><circle cx="27" cy="43" r="2.6" fill="oklch(0.72 0.12 25 / .5)"/><circle cx="47" cy="43" r="2.6" fill="oklch(0.72 0.12 25 / .5)"/></svg>';
const WORDS = [
  ['vorrei', 'I would like', 2], ['chilo', 'kilo', 3], ['pomodoro', 'tomato', 1], ['pane', 'bread', 4], ['mela', 'apple', 3], ['formaggio', 'cheese', 2], ['uova', 'eggs', 1], ['latte', 'milk', 4],
  ['quanto', 'how much', 2], ['costare', 'to cost', 1], ['arancia', 'orange', 0], ['comprare', 'to buy', 2], ['fresco', 'fresh', 1], ['etto', '100 grams', 0], ['pesce', 'fish', 3],
].map(([it, en, s]) => ({ it, en, s }));
const W = Object.fromEntries(WORDS.map(w => [w.it, w]));
const TIPS = [
  ['Vorrei, not voglio', 'In a shop, ask with <b>vorrei</b> (I would like). <b>Voglio</b> (I want) is grammatical but sounds blunt.'],
  ['Il, la, le', 'Articles follow gender and number: <b>il</b> pane, <b>la</b> mela, <b>le</b> uova.'],
  ['Costa or costano?', 'Use <b>costa</b> for one thing and <b>costano</b> for several: quanto costano le mele?'],
  ['L’ before a vowel', '<b>La</b> and <b>lo</b> drop their vowel before another vowel: l’arancia, l’uovo.'],
  ['-are verbs with noi', 'Drop <b>-are</b> and add <b>-iamo</b>: comprare → compriamo, mangiare → mangiamo.'],
  ['Adjectives agree', '<b>fresco</b> (m), <b>fresca</b> (f), <b>freschi</b> (m pl), <b>fresche</b> (f pl). Il formaggio is masculine.'],
  ['Shopping by the etto', 'Delis weigh in <b>etti</b>: un etto is 100 g, due etti di prosciutto is 200 g.'],
  ['C’è or ci sono?', '<b>C’è</b> for one thing, <b>ci sono</b> for several: c’è del pesce, ci sono delle mele.'],
];
const EX = [
  { k: 'tiles', title: 'Translate this sentence', say: 'I would like two kilos of tomatoes.', ans: ['Vorrei', 'due', 'chili', 'di', 'pomodori'], extra: ['voglio', 'pomodoro', 'del', 'tre'], words: ['vorrei', 'chilo', 'pomodoro'], tip: 0 },
  { k: 'match', title: 'Tap the matching pairs', pairs: [['il pane', 'bread'], ['la mela', 'apple'], ['il formaggio', 'cheese'], ['le uova', 'eggs'], ['il latte', 'milk']], right: [3, 0, 4, 1, 2], words: ['pane', 'mela', 'formaggio', 'uova', 'latte'], tip: 1 },
  { k: 'type', title: 'Write this in Italian', say: 'How much does it cost?', ans: ['Quanto costa?'], words: ['quanto', 'costare'], tip: 2 },
  { k: 'article', title: 'Pick the right article', noun: 'arancia', gloss: 'orange', opts: ['il', 'la', 'lo', 'l’'], ans: 3, words: ['arancia'], tip: 3 },
  { k: 'cloze', title: 'Fill in the verb', before: 'Noi', after: 'il pane al forno qui vicino.', verb: 'comprare', ans: 'compriamo', gloss: 'We buy bread at the bakery near here.', words: ['comprare', 'pane'], tip: 4 },
  { k: 'tiles', title: 'Translate this sentence', say: 'The cheese is very fresh today.', ans: ['Il', 'formaggio', 'è', 'molto', 'fresco', 'oggi'], extra: ['fresca', 'sono', 'la'], words: ['formaggio', 'fresco'], tip: 5 },
  { k: 'mcq', title: 'What does this mean?', say: 'Mi dà un etto di prosciutto, per favore?', opts: ['Could you give me 100 grams of ham, please?', 'I’ll give you a kilo of ham.', 'Is the ham fresh today?', 'I don’t eat ham, thank you.'], ans: 0, words: ['etto'], tip: 6 },
  { k: 'tiles', title: 'Translate this sentence', say: 'Is there any fresh fish?', ans: ['C’è', 'del', 'pesce', 'fresco'], extra: ['Ci', 'sono', 'pesci'], words: ['pesce', 'fresco'], tip: 7 },
];
/* a fixed shuffle per exercise, so the bank is stable between renders */
function shuffled(arr, seed) { const a = arr.slice(); let s = seed; for (let i = a.length - 1; i > 0; i--) { s = (s * 9301 + 49297) % 233280; const j = Math.floor(s / 233280 * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
EX.forEach((e, i) => { if (e.k === 'tiles') e.bank = shuffled(e.ans.concat(e.extra), 11 + i * 7); });
const PRAISE = ['Ottimo!', 'Esatto!', 'Bravissimo!', 'Perfetto!', 'Bene!'];

const S = { queue: EX.map((_, i) => i), pos: 0, done: new Set(), missed: new Set(), tried: new Set(), hearts: 3, xp0: 30, xp: 30, goal: 50, phase: 'answer', a: null, t0: 0, end: false, fresh: null };
