  $('[data-words]').innerHTML = WORDS.map(w => '<li class="ale-lingo-w' + (S.fresh && S.fresh.includes(w.it) ? ' is-fresh' : '') + '"><b>' + esc(w.it) + '</b><span>' + esc(w.en) + '</span><i aria-label="strength ' + w.s + ' of 4">' + [1, 2, 3, 4].map(k => '<u class="' + (k <= w.s ? 'is-on' : '') + '"></u>').join('') + '</i></li>').join('');
