  stage.innerHTML = '<section class="ale-lingo-end"><svg viewBox="0 0 96 96" aria-hidden="true"><circle cx="48" cy="48" r="40" fill="oklch(0.82 0.15 70)"/><circle cx="48" cy="48" r="31" fill="oklch(0.72 0.15 62)"/><path d="m48 26 6.6 13.4 14.8 2.2-10.7 10.4 2.5 14.7L48 59.8l-13.2 6.9 2.5-14.7-10.7-10.4 14.8-2.2z" fill="oklch(0.97 0.05 95)"/></svg>' +
    '<h2>Lezione completata!</h2><p>Unit 3, lesson 2 is done. ' + (S.missed.size ? 'You fixed ' + S.missed.size + ' mistake' + (S.missed.size === 1 ? '' : 's') + ' on the way.' : 'Not a single mistake.') + '</p>' +
    '<div class="ale-lingo-stats"><div class="ale-lingo-stat" style="--i:0"><p>Total XP</p><b>' + (S.xp - S.xp0) + '</b></div><div class="ale-lingo-stat" style="--i:1;--c:var(--ale-lingo-ok)"><p>Accuracy</p><b>' + acc + '%</b></div><div class="ale-lingo-stat" style="--i:2;--c:var(--ale-lingo-sel)"><p>Time</p><b>' + Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0') + '</b></div></div>' +
    '<div class="ale-lingo-mrow" style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center"><button type="button" class="ale-lingo-ghost-btn" data-act="practice"' + (S.missed.size ? '' : ' disabled title="No mistakes to practise"') + '>Practise mistakes</button><button type="button" class="ale-lingo-go" data-act="restart">Replay lesson</button></div></section>';
