    const got = a.picked.map(b => e.bank[b]).join(' ');
    ok = norm(got) === norm(e.ans.join(' '));
    body = ok ? esc(e.ans.join(' ')) : esc(e.ans.join(' '));
  } else if (e.k === 'match') { ok = true; body = a.mistakes ? a.mistakes + ' wrong pairing' + (a.mistakes === 1 ? '' : 's') + ' along the way.' : 'Every pair on the first try.'; }
