/* tiles move with a FLIP: measure every tile, change state, re-render, play the difference */
function moveTile(b) {
  if (S.phase !== 'answer') return;
  const e = cur(); if (e.k !== 'tiles') return;
  const first = new Map($$('[data-tile]', stage).map(el => [el.dataset.tile, el.getBoundingClientRect()]));
  const p = S.a.picked, k = p.indexOf(b);
  if (k > -1) p.splice(k, 1); else p.push(b);
  renderEx(false);
  if (RM.matches) return;
  $$('[data-tile]', stage).forEach(el => {
    const f = first.get(el.dataset.tile); if (!f) return;
    const l = el.getBoundingClientRect(), dx = f.left - l.left, dy = f.top - l.top;
    if (dx || dy) el.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: el.dataset.tile == b ? 420 : 300, easing: 'cubic-bezier(.2,.9,.25,1.05)' });
