    const left = EX.length - S.done.size;
    m.innerHTML = '<h2 id="ale-lingo-mh">Leave this lesson?</h2><p>' + (S.done.size ? 'You’ve finished ' + S.done.size + ' of ' + EX.length + ' exercises. Leaving now throws that progress away.' : 'Nothing is saved until you finish all ' + left + ' exercises.') + '</p><div class="ale-lingo-mrow"><button type="button" class="ale-lingo-ghost-btn" data-act="leave">Leave lesson</button><button type="button" class="ale-lingo-go" data-act="stay">Keep learning</button></div>';
  } else {
    m.innerHTML = '<p class="ale-lingo-big" aria-hidden="true">' + I.heart.replace('<svg ', '<svg style="width:52px;height:52px;fill:var(--ale-lingo-line2);stroke:none" ') + '</p><h2 id="ale-lingo-mh">You’re out of hearts</h2><p>Every missed answer costs one. Refill them now and pick up where you stopped — the exercises you missed are waiting at the end.</p><div class="ale-lingo-mrow"><button type="button" class="ale-lingo-ghost-btn" data-act="leave">End lesson</button><button type="button" class="ale-lingo-go" data-act="refill">Refill hearts</button></div>';
