function closeModal() { modalEl.hidden = true; }

/* ── events ───────────────────────────────────────── */
root.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t || !root.contains(t) || t.disabled) return;
  const act = t.dataset.act;
  if (t.dataset.tile != null) return moveTile(+t.dataset.tile);
  if (t.dataset.m) return matchTap(t.dataset.m);
  if (t.dataset.pick != null) { S.a.pick = +t.dataset.pick; renderEx(false); const b = $('[data-pick="' + t.dataset.pick + '"]', stage); if (b) b.focus({ preventScroll: true }); return; }
  if (t.dataset.acc) { const f = $('[data-text]', stage); const s = f.selectionStart ?? f.value.length, en = f.selectionEnd ?? s; f.value = f.value.slice(0, s) + t.dataset.acc + f.value.slice(en); S.a.text = f.value; f.focus(); f.setSelectionRange(s + 1, s + 1); return syncCheck(); }
  if (act === 'check') return check();
  if (act === 'skip') return skip();
  if (act === 'continue') return next();
  if (act === 'quit') return modal('quit');
  if (act === 'stay') return closeModal();
  if (act === 'leave') { closeModal(); S.hearts = 3; S.xp = S.xp0; return start(EX.map((_, i) => i)); }
  if (act === 'refill') { closeModal(); S.hearts = 3; renderTop(); S.phase = 'feedback'; return next(); }
  if (act === 'restart') { S.hearts = 3; return start(EX.map((_, i) => i)); }
  if (act === 'practice') { const q = [...S.missed]; S.missed = new Set(); S.tried = new Set(); return start(q); }
  if (act === 'words') { const on = root.dataset.view !== 'words'; root.dataset.view = on ? 'words' : 'lesson'; t.setAttribute('aria-pressed', on); return renderSide(); }
});
modalEl.addEventListener('click', e => { if (e.target === modalEl && modalEl.dataset.kind === 'quit') closeModal(); });
stage.addEventListener('input', e => { if (e.target.matches('[data-text]')) { S.a.text = e.target.value; syncCheck(); } });

root.addEventListener('keydown', e => {
  const k = e.key, tg = e.target;
  if (!modalEl.hidden) {
    if (k === 'Escape' && modalEl.dataset.kind === 'quit') { e.preventDefault(); closeModal(); }
    if (k === 'Tab') { const b = $$('button', modalEl); const i = b.indexOf(tg); if (e.shiftKey && i <= 0) { e.preventDefault(); b[b.length - 1].focus(); } else if (!e.shiftKey && i === b.length - 1) { e.preventDefault(); b[0].focus(); } }
    return;
  }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (k === 'Enter' && !(tg.closest('button') && !tg.matches('[data-pick], [data-tile], [data-m]'))) {
    e.preventDefault();
    if (S.phase === 'feedback') return next();
    if (S.end) return;
    return check();
  }
  if (tg.matches('[data-text]')) { if (k === 'Escape') { tg.blur(); root.focus(); } return; }
  if (k === 'Escape') return modal('quit');
  if (S.phase !== 'answer' || S.end) return;
  const e2 = cur();
  if (e2.k === 'tiles') {
    if (/^[1-9]$/.test(k)) { const b = +k - 1; if (b < e2.bank.length && !S.a.picked.includes(b)) { e.preventDefault(); moveTile(b); } return; }
    if (k === 'Backspace' && S.a.picked.length) { e.preventDefault(); return moveTile(S.a.picked[S.a.picked.length - 1]); }
  }
  if (e2.k === 'match' && /^[0-9]$/.test(k)) {
    const n = (+k + 9) % 10;
    const id = n < 5 ? 'L' + n : 'R' + e2.right[n - 5];
    const el = $('[data-m="' + id + '"]', stage); if (el && !el.disabled) { e.preventDefault(); matchTap(id); }
    return;
  }
  if ((e2.k === 'mcq' || e2.k === 'article') && /^[1-4]$/.test(k)) { e.preventDefault(); S.a.pick = +k - 1; return renderEx(false); }
  if (tg.matches('[role=radio]') && ['ArrowDown', 'ArrowUp', 'ArrowLeft', 'ArrowRight'].includes(k)) {
    e.preventDefault(); const n = e2.opts.length, d = k === 'ArrowDown' || k === 'ArrowRight' ? 1 : -1;
    S.a.pick = ((S.a.pick ?? -1) + d + n) % n; renderEx(false); $('[data-pick="' + S.a.pick + '"]', stage).focus();
  }
});

start(EX.map((_, i) => i));
/* the learner has already placed the first two words */
S.a.picked = [EX[0].bank.indexOf('Vorrei'), EX[0].bank.indexOf('due')];
renderEx(false);

