@property --ale-code-pass { syntax: '<number>'; inherits: true; initial-value: 0; }

.ale-code {
  /* re-theme with these four */
  --ale-code-bg: oklch(0.19 0.012 220);
  --ale-code-ink: oklch(0.93 0.01 220);
  --ale-code-accent: oklch(0.86 0.17 128);
  --ale-code-fail: oklch(0.71 0.16 25);
  /* derived */
  --ale-code-panel: color-mix(in oklch, var(--ale-code-bg) 93%, var(--ale-code-ink));
  --ale-code-edbg: color-mix(in oklch, var(--ale-code-bg) 88%, black);
  --ale-code-raise: color-mix(in oklch, var(--ale-code-bg) 86%, var(--ale-code-ink));
  --ale-code-line: color-mix(in oklch, var(--ale-code-ink) 10%, transparent);
  --ale-code-line2: color-mix(in oklch, var(--ale-code-ink) 18%, transparent);
  --ale-code-mute: color-mix(in oklch, var(--ale-code-ink) 60%, var(--ale-code-bg));
  --ale-code-faint: color-mix(in oklch, var(--ale-code-ink) 34%, var(--ale-code-bg));
  --ale-code-hover: color-mix(in oklch, var(--ale-code-ink) 7%, transparent);
  --ale-code-kw: oklch(0.82 0.13 75);
  --ale-code-str: oklch(0.83 0.12 145);
  --ale-code-num: oklch(0.79 0.12 35);
  --ale-code-fn: oklch(0.8 0.1 235);
  --ale-code-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-code-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-code-lh: 20px;
  --ale-code-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-code-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-code-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-code-bg); color: var(--ale-code-ink); color-scheme: dark; accent-color: var(--ale-code-accent);
  font: 13px/1.45 var(--ale-code-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-code-accent); outline-offset: 2px; }
  & button, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h1, & h2, & h3, & p, & ol, & ul, & dl, & dd, & pre { margin: 0; padding: 0; font: inherit; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--ale-code-mono); padding: 3px 5px; display: inline-block; border: 1px solid var(--ale-code-line2); border-bottom-width: 2px; border-radius: 5px; color: var(--ale-code-mute); }
  & code { font: 600 .92em var(--ale-code-mono); padding: 1px 5px; border-radius: 5px; background: var(--ale-code-line); }
}
.ale-code .ale-code-app {
  height: 100%; display: grid; grid-template-columns: 272px minmax(0, 1fr) 292px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "brief ed tests" "nav nav nav";
}

/* ── brief ─────────────────────────────── */
.ale-code .ale-code-brief { grid-area: brief; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; background: var(--ale-code-panel); border-right: 1px solid var(--ale-code-line); }
.ale-code .ale-code-brand {
  display: flex; align-items: center; gap: 10px; padding: 16px 16px 12px;
  & p { font: 750 15px var(--ale-code-mono); letter-spacing: -.02em; }
  & span { display: block; font-size: 11px; color: var(--ale-code-mute); }
}
.ale-code .ale-code-logo { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: var(--ale-code-accent); color: var(--ale-code-bg); & svg { stroke-width: 2.2; } }
.ale-code .ale-code-list { padding: 0 8px 10px; border-bottom: 1px solid var(--ale-code-line); }
.ale-code .ale-code-ex {
  width: 100%; display: grid; grid-template-columns: 20px 1fr auto; gap: 10px; align-items: center; text-align: left; border: 0; background: none; padding: 6px 8px; border-radius: 8px;
  & .ale-code-st { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px var(--ale-code-line2); }
  & .ale-code-st svg { width: 12px; height: 12px; stroke-width: 3; }
  & b { font-weight: 560; font-size: 12.5px; }
  & small { font: 600 10.5px var(--ale-code-mono); color: var(--ale-code-faint); font-variant-numeric: tabular-nums; }
  &.is-solved .ale-code-st { background: var(--ale-code-accent); color: var(--ale-code-bg); box-shadow: none; }
  &.is-tried .ale-code-st { box-shadow: inset 0 0 0 1.5px var(--ale-code-kw); }
  &.is-tried small { color: var(--ale-code-kw); }
  &:hover { background: var(--ale-code-hover); }
  &[aria-current="true"] { background: var(--ale-code-raise); }
  &[aria-current="true"] b { color: var(--ale-code-accent); }
}
.ale-code .ale-code-desc {
  overflow: auto; padding: 16px 18px 20px; display: flex; flex-direction: column; gap: 12px; scrollbar-width: thin;
  & > * { flex: none; }
  & > p:first-child { font: 700 10.5px var(--ale-code-sans); letter-spacing: .14em; text-transform: uppercase; color: var(--ale-code-accent); }
  & h1 { font-size: 19px; font-weight: 740; letter-spacing: -.02em; text-wrap: balance; margin-top: -8px; }
  & > p { font-size: 13px; line-height: 1.55; color: color-mix(in oklch, var(--ale-code-ink) 82%, var(--ale-code-bg)); text-wrap: pretty; }
  & table { border-collapse: collapse; font: 12px var(--ale-code-mono); width: 100%; }
  & th { text-align: left; font: 700 10px var(--ale-code-sans); letter-spacing: .1em; text-transform: uppercase; color: var(--ale-code-faint); padding: 0 0 6px; }
  & td { padding: 5px 0; border-top: 1px solid var(--ale-code-line); }
  & td:last-child { color: var(--ale-code-str); text-align: right; }
}
.ale-code .ale-code-hint {
  border-radius: 10px; border: 1px solid var(--ale-code-line2); overflow: hidden;
  & > button { width: 100%; display: flex; align-items: center; gap: 8px; border: 0; background: none; padding: 9px 12px; font-weight: 600; font-size: 12.5px; text-align: left; }
  & > button svg { width: 15px; height: 15px; color: var(--ale-code-kw); }
  & > button span { margin-left: auto; color: var(--ale-code-faint); font-size: 11px; font-weight: 500; }
  & > button:hover { background: var(--ale-code-hover); }
  & > div { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--ale-code-ease); }
  & > div > p { overflow: hidden; min-height: 0; font-size: 12.5px; line-height: 1.55; color: var(--ale-code-mute); padding: 0 12px; text-wrap: pretty; }
  & > button[aria-expanded="true"] + div { grid-template-rows: 1fr; }
  & > button[aria-expanded="true"] + div > p { padding-bottom: 12px; }
}
.ale-code .ale-code-sol {
  border: 1px dashed var(--ale-code-line2); background: none; border-radius: 10px; padding: 9px 12px; font-size: 12px; font-weight: 600; color: var(--ale-code-mute); text-align: left;
  &:hover { color: var(--ale-code-ink); border-color: var(--ale-code-mute); }
  &.is-arm { border-style: solid; border-color: var(--ale-code-fail); color: var(--ale-code-fail); }
}

/* ── editor ─────────────────────────────── */
.ale-code .ale-code-ed { grid-area: ed; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; min-width: 0; min-height: 0; background: var(--ale-code-edbg); }
.ale-code .ale-code-edh { display: flex; align-items: center; gap: 8px; padding: 10px 12px 10px 16px; border-bottom: 1px solid var(--ale-code-line); }
.ale-code .ale-code-file {
  display: inline-flex; align-items: center; gap: 7px; font: 600 12px var(--ale-code-mono); color: var(--ale-code-ink); min-width: 0;
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--ale-code-kw); opacity: 0; transition: opacity .2s; }
  &.is-dirty i { opacity: 1; }
}
.ale-code .ale-code-pos { margin-left: auto; font: 500 11px var(--ale-code-mono); color: var(--ale-code-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
.ale-code .ale-code-tb {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--ale-code-line2); background: none; font-size: 12px; font-weight: 600; color: var(--ale-code-mute);
  & svg { width: 14px; height: 14px; }
  &:hover:not(:disabled) { color: var(--ale-code-ink); border-color: var(--ale-code-mute); }
}
.ale-code .ale-code-run {
  display: inline-flex; align-items: center; gap: 8px; height: 30px; padding: 0 8px 0 10px; border-radius: 8px; border: 0; background: var(--ale-code-accent); color: var(--ale-code-bg); font-weight: 750; font-size: 12px;
  transition: transform .25s var(--ale-code-spring), filter .15s;
  & svg { width: 13px; height: 13px; fill: currentColor; stroke-width: 1; }
  & kbd { border-color: color-mix(in oklch, var(--ale-code-bg) 35%, transparent); color: var(--ale-code-bg); opacity: .7; }
  &:hover { filter: brightness(1.07); }
  &:active { transform: scale(.95); }
  &.is-busy svg { animation: ale-code-spin .6s linear infinite; }
}
@keyframes ale-code-spin { to { rotate: 360deg; } }

.ale-code .ale-code-scroll { position: relative; overflow: auto; min-height: 0; scrollbar-width: thin; cursor: text; }
.ale-code .ale-code-sheet { display: grid; grid-template-columns: auto 1fr; min-width: 100%; width: max-content; min-height: 100%; }
.ale-code .ale-code-gut {
  position: sticky; left: 0; z-index: 2; padding: 12px 12px 40px 14px; text-align: right; min-width: 46px; background: var(--ale-code-edbg);
  font: 12.5px/var(--ale-code-lh) var(--ale-code-mono); color: var(--ale-code-faint); user-select: none; font-variant-numeric: tabular-nums;
  & b { font-weight: 400; color: var(--ale-code-ink); }
  & em { font-style: normal; color: var(--ale-code-fail); font-weight: 700; }
}
.ale-code .ale-code-cell { position: relative; display: grid; }
.ale-code .ale-code-hl, .ale-code .ale-code-ta {
  grid-area: 1 / 1; margin: 0; padding: 12px 24px 40px 6px; border: 0; font: 12.5px/var(--ale-code-lh) var(--ale-code-mono); tab-size: 2; white-space: pre; letter-spacing: 0; word-spacing: 0;
}
.ale-code .ale-code-hl {
  color: var(--ale-code-ink); pointer-events: none;
  & .ale-code-k { color: var(--ale-code-kw); } & .ale-code-s { color: var(--ale-code-str); } & .ale-code-n { color: var(--ale-code-num); } & .ale-code-f { color: var(--ale-code-fn); }
  & .ale-code-c { color: var(--ale-code-faint); font-style: italic; } & .ale-code-o { color: var(--ale-code-mute); } & .ale-code-b { color: var(--ale-code-num); font-style: italic; }
}
.ale-code .ale-code-ta {
  resize: none; overflow: hidden; background: transparent; color: transparent; caret-color: var(--ale-code-accent); outline: 0; min-height: 100%; width: 100%; height: 100%;
  &::selection { background: color-mix(in oklch, var(--ale-code-fn) 32%, transparent); color: transparent; }
}
.ale-code .ale-code-cur, .ale-code .ale-code-errbar { position: absolute; left: -60px; right: 0; height: var(--ale-code-lh); top: calc(12px + (var(--l, 1) - 1) * var(--ale-code-lh)); pointer-events: none; }
.ale-code .ale-code-cur { background: color-mix(in oklch, var(--ale-code-ink) 4%, transparent); transition: top .08s; }
.ale-code .ale-code-errbar {
  background: color-mix(in oklch, var(--ale-code-fail) 16%, transparent); box-shadow: inset 3px 0 0 var(--ale-code-fail);
  animation: ale-code-err .5s var(--ale-code-ease);
}
@keyframes ale-code-err { from { opacity: 0; transform: scaleX(.96); } }
.ale-code .ale-code-stamp {
  position: absolute; right: 24px; top: 20px; z-index: 3; padding: 6px 14px; border: 3px solid var(--ale-code-accent); border-radius: 8px; color: var(--ale-code-accent);
  font: 800 18px var(--ale-code-mono); letter-spacing: .2em; text-transform: uppercase; rotate: -8deg; pointer-events: none;
  animation: ale-code-stamp .6s var(--ale-code-spring) both;
}
@keyframes ale-code-stamp { from { opacity: 0; scale: 1.8; rotate: 6deg; } }

.ale-code .ale-code-console {
  border-top: 1px solid var(--ale-code-line); max-height: 132px; display: grid; grid-template-rows: auto minmax(0, 1fr); background: var(--ale-code-bg);
  & header { display: flex; justify-content: space-between; align-items: baseline; padding: 8px 16px 4px; }
  & h2 { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-code-mute); }
  & header span { font: 500 11px var(--ale-code-mono); color: var(--ale-code-faint); }
  & pre { overflow: auto; padding: 2px 16px 10px; font: 12px/1.6 var(--ale-code-mono); color: var(--ale-code-mute); white-space: pre-wrap; scrollbar-width: thin; }
  & .ale-code-ce { color: var(--ale-code-fail); } & .ale-code-cp { color: var(--ale-code-ink); } & .ale-code-cd { color: var(--ale-code-faint); }
}
.ale-code .ale-code-keys {
  display: flex; gap: 14px; flex-wrap: wrap; padding: 7px 16px 9px; border-top: 1px solid var(--ale-code-line); font-size: 11px; color: var(--ale-code-faint); background: var(--ale-code-bg);
  & kbd { padding: 2px 4px; font-size: 9.5px; margin-right: 3px; }
}

/* ── tests ─────────────────────────────── */
.ale-code .ale-code-tests { grid-area: tests; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; background: var(--ale-code-panel); border-left: 1px solid var(--ale-code-line); }
.ale-code .ale-code-th {
  padding: 16px 16px 12px; display: grid; gap: 10px; border-bottom: 1px solid var(--ale-code-line);
  & h2 { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-code-mute); }
  & p { font-size: 18px; font-weight: 740; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & p span { font-size: 12px; font-weight: 500; color: var(--ale-code-mute); letter-spacing: 0; }
}
.ale-code .ale-code-meter {
  display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: 3px; height: 6px;
  & i { border-radius: 3px; background: var(--ale-code-line2); transition: background .3s; }
  & i.is-pass { background: var(--ale-code-accent); } & i.is-fail { background: var(--ale-code-fail); }
}
.ale-code .ale-code-tlist { overflow: auto; padding: 8px 8px 12px; scrollbar-width: thin; }
.ale-code .ale-code-t {
  --i: 0;
  width: 100%; display: grid; grid-template-columns: 20px 1fr; gap: 2px 10px; text-align: left; border: 0; background: none; padding: 9px 8px; border-radius: 9px; align-items: start;
  animation: ale-code-tin .35s var(--ale-code-ease) both; animation-delay: calc(var(--i) * 70ms);
  & .ale-code-ti { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px var(--ale-code-line2); margin-top: 1px; }
  & .ale-code-ti svg { width: 12px; height: 12px; stroke-width: 3; stroke-dasharray: 24; stroke-dashoffset: 24; animation: ale-code-draw .4s var(--ale-code-ease) forwards; animation-delay: calc(var(--i) * 70ms + 120ms); }
  & code { background: none; padding: 0; font-size: 12px; color: var(--ale-code-ink); word-break: break-all; }
  & small { grid-column: 2; font: 500 11px/1.45 var(--ale-code-mono); color: var(--ale-code-faint); }
  & small b { font-weight: 600; color: var(--ale-code-str); }
  & small u { text-decoration: none; color: var(--ale-code-fail); font-weight: 600; }
  &.is-pass .ale-code-ti { background: var(--ale-code-accent); color: var(--ale-code-bg); box-shadow: none; }
  &.is-fail .ale-code-ti { background: var(--ale-code-fail); color: var(--ale-code-bg); box-shadow: none; }
  &.is-pend .ale-code-ti { animation: ale-code-pulse 1s ease-in-out infinite; }
  &:hover { background: var(--ale-code-hover); }
  &[aria-pressed="true"] { background: var(--ale-code-raise); }
}
@keyframes ale-code-tin { from { opacity: 0; transform: translateX(10px); } }
@keyframes ale-code-draw { to { stroke-dashoffset: 0; } }
@keyframes ale-code-pulse { 50% { box-shadow: inset 0 0 0 1.5px var(--ale-code-mute); } }
.ale-code .ale-code-submit {
  padding: 12px 14px 14px; border-top: 1px solid var(--ale-code-line); display: grid; gap: 8px;
  & p { font-size: 12px; color: var(--ale-code-mute); text-wrap: pretty; }
  & button { height: 38px; border-radius: 10px; border: 0; font-weight: 750; background: var(--ale-code-accent); color: var(--ale-code-bg); transition: transform .25s var(--ale-code-spring); }
  & button:active:not(:disabled) { transform: scale(.97); }
  & button.is-ghost { background: none; border: 1px solid var(--ale-code-line2); color: var(--ale-code-ink); }
}

/* nav (narrow) */
.ale-code .ale-code-nav {
  grid-area: nav; display: none; padding: 4px 6px 6px; border-top: 1px solid var(--ale-code-line); background: var(--ale-code-panel);
  & button { flex: 1; border: 0; background: none; display: grid; justify-items: center; gap: 2px; padding: 6px 4px; border-radius: 10px; font-size: 11px; font-weight: 600; color: var(--ale-code-mute); }
  & button svg { width: 20px; height: 20px; }
  & button b { font: 700 10px var(--ale-code-mono); }
  & button[aria-selected="true"] { color: var(--ale-code-accent); background: var(--ale-code-hover); }
}
.ale-code .ale-code-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; translate: -50% 16px; display: flex; align-items: center; gap: 12px;
  padding: 8px 8px 8px 14px; border-radius: 12px; background: var(--ale-code-ink); color: var(--ale-code-bg); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 34px -14px oklch(0 0 0 / .8); opacity: 0; visibility: hidden; transition: opacity .25s, translate .4s var(--ale-code-spring), visibility 0s .4s;
  & button { border: 0; border-radius: 8px; padding: 5px 10px; background: color-mix(in oklch, var(--ale-code-bg) 12%, transparent); font-weight: 700; font-size: 12px; color: var(--ale-code-bg); }
  &.is-on { opacity: 1; visibility: visible; translate: -50% 0; transition: opacity .25s, translate .4s var(--ale-code-spring), visibility 0s; }
  & button:empty { display: none; }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 1080px) {
  .ale-code .ale-code-app { grid-template-columns: 244px minmax(0, 1fr) 264px; }
}
@container (max-width: 959px) {
  .ale-code .ale-code-app { grid-template-columns: minmax(0, 1fr) 260px; grid-template-areas: "ed tests" "nav nav"; }
  .ale-code .ale-code-nav { display: flex; }
  .ale-code .ale-code-nav [data-view="tests"] { display: none; }
  .ale-code .ale-code-brief { grid-area: ed; border-right: 0; }
