/* Drillbit — coding exercises checked by a tiny interpreter.
   Solutions are written in "Tern", a small brace language. They never touch the page's
   JavaScript engine: a tokenizer, a Pratt parser and a tree-walking interpreter run them
   with a step budget, so an endless loop fails its test instead of freezing the tab,
   and every error points at a line. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const I = {
  ok: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  no: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  bulb: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.6.5 1 1.2 1 2.1h5c0-.9.4-1.6 1-2.1A6 6 0 0 0 12 3Z"/></svg>',
};

/* ── Tern: lexer ───────────────────────────────────────── */
const KW = new Set(['fn', 'let', 'if', 'else', 'while', 'for', 'in', 'return', 'true', 'false', 'nil']);
const fail = (msg, line, kind) => { const e = new Error(msg); e.line = line; e.kind = kind || 'Syntax error'; return e; };
function lex(src) {
  const toks = []; let i = 0, line = 1;
  const push = (t, v) => toks.push({ t, v, line });
  while (i < src.length) {
    const c = src[i];
    if (c === '\n') { line++; i++; continue; }
    if (c === ' ' || c === '\t' || c === '\r') { i++; continue; }
    if (c === '/' && src[i + 1] === '/') { while (i < src.length && src[i] !== '\n') i++; continue; }
    if (c >= '0' && c <= '9') {
      let j = i; while (/[0-9_]/.test(src[j] || '')) j++;
      if (src[j] === '.' && /[0-9]/.test(src[j + 1] || '')) { j++; while (/[0-9]/.test(src[j] || '')) j++; }
      push('num', parseFloat(src.slice(i, j).replace(/_/g, ''))); i = j; continue;
    }
    if (/[A-Za-z_]/.test(c)) { let j = i; while (/[A-Za-z0-9_]/.test(src[j] || '')) j++; const w = src.slice(i, j); push(KW.has(w) ? w : 'id', w); i = j; continue; }
    if (c === '"') {
      let j = i + 1, s = '';
      while (j < src.length && src[j] !== '"') {
        if (src[j] === '\n') throw fail('This string never closes — add a " before the line ends', line);
        if (src[j] === '\\' && j + 1 < src.length) { j++; s += ({ n: '\n', t: '\t' })[src[j]] || src[j]; } else s += src[j];
        j++;
      }
      if (j >= src.length) throw fail('This string never closes — add a "', line);
      push('str', s); i = j + 1; continue;
    }
    const two = src.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||', '+=', '-=', '*=', '..'].includes(two)) { push(two, two); i += 2; continue; }
    if ('(){},;=+-*/%<>!'.includes(c)) { push(c, c); i++; continue; }
    throw fail('Unexpected character ‘' + c + '’', line);
  }
  push('eof', null);
  return toks;
}

/* ── Tern: parser (recursive descent, Pratt for operators) ───────────────────────────────────────── */
const BP = { '||': 1, '&&': 2, '==': 3, '!=': 3, '<': 4, '<=': 4, '>': 4, '>=': 4, '+': 5, '-': 5, '*': 6, '/': 6, '%': 6 };
function parse(src) {
  const toks = lex(src); let p = 0;
  const peek = (o = 0) => toks[Math.min(p + o, toks.length - 1)], next = () => toks[p++], at = t => toks[p].t === t;
  const desc = k => k.t === 'eof' ? 'the end of the code' : k.t === 'id' ? '‘' + k.v + '’' : k.t === 'num' ? 'the number ' + k.v : k.t === 'str' ? 'a string' : '‘' + k.v + '’';
  const want = (t, what) => { if (!at(t)) throw fail('Expected ' + (what || '‘' + t + '’') + ' but found ' + desc(toks[p]), toks[p].line); return next(); };
  function block(depth) {
    if (at('=')) throw fail('Use == to compare; a single = only assigns', toks[p].line);
    const open = want('{', '‘{’ to start the block'); const body = [];
    while (!at('}')) { if (at('eof')) throw fail('Missing ‘}’ for the block opened on line ' + open.line, open.line); const s = stmt(depth); if (s) body.push(s); }
    next(); return body;
  }
  function list(close, item) { const out = []; if (!at(close)) { do out.push(item()); while (at(',') && next()); } want(close, '‘' + close + '’'); return out; }
  function stmt(depth) {
    const k = peek();
    switch (k.t) {
      case ';': next(); return null;
      case 'fn': {
        if (depth) throw fail('Define functions at the top level, not inside a block', k.line);
        next(); const name = want('id', 'a function name').v; want('(', '‘(’ after the name');
        const params = list(')', () => want('id', 'a parameter name').v);
        return { k: 'fn', name, params, body: block(1), line: k.line };
      }
      case 'let': { next(); const name = want('id', 'a variable name').v; want('=', '‘=’ after the name'); return { k: 'let', name, e: expr(0), line: k.line }; }
      case 'if': { next(); const c = expr(0), then = block(depth + 1); let els = null; if (at('else')) { next(); els = at('if') ? [stmt(depth)] : block(depth + 1); } return { k: 'if', c, then, els, line: k.line }; }
      case 'while': { next(); const c = expr(0); return { k: 'while', c, body: block(depth + 1), line: k.line }; }
      case 'for': { next(); const name = want('id', 'a loop variable').v; want('in', '‘in’'); const a = expr(0); want('..', '‘..’ between the bounds'); const b = expr(0); return { k: 'for', name, a, b, body: block(depth + 1), line: k.line }; }
      case 'return': { next(); const bare = at('}') || at('eof') || at(';') || peek().line !== k.line; return { k: 'return', e: bare ? null : expr(0), line: k.line }; }
      case 'id': if (['=', '+=', '-=', '*='].includes(peek(1).t)) { next(); const op = next().t; return { k: 'set', name: k.v, op, e: expr(0), line: k.line }; }
    }
    return { k: 'expr', e: expr(0), line: k.line };
  }
  function expr(min) {
    let left = unary();
    for (;;) { const op = peek().t, bp = BP[op]; if (!bp || bp <= min) break; const line = next().line; left = { k: 'bin', op, l: left, r: expr(bp), line }; }
    return left;
  }
  function unary() { const k = peek(); if (k.t === '-' || k.t === '!') { next(); return { k: 'un', op: k.t, e: unary(), line: k.line }; } return postfix(); }
  function postfix() { let e = primary(); while (at('(')) { const line = next().line; e = { k: 'call', f: e, args: list(')', () => expr(0)), line }; } return e; }
  function primary() {
    const k = next();
    if (k.t === 'num' || k.t === 'str') return { k: 'lit', v: k.v, line: k.line };
    if (k.t === 'true' || k.t === 'false') return { k: 'lit', v: k.t === 'true', line: k.line };
    if (k.t === 'nil') return { k: 'lit', v: null, line: k.line };
    if (k.t === 'id') return { k: 'var', name: k.v, line: k.line };
    if (k.t === '(') { const e = expr(0); want(')', '‘)’'); return e; }
    if (k.t === '=') throw fail('Use == to compare; a single = only assigns', k.line);
    throw fail('Expected a value but found ' + desc(k), k.line);
  }
  const prog = []; while (!at('eof')) { const s = stmt(0); if (s) prog.push(s); }
  return prog;
}

/* ── Tern: interpreter ───────────────────────────────────────── */
const show = v => v === null || v === undefined ? 'nil' : typeof v === 'number' ? (Number.isInteger(v) ? String(v) : String(+v.toFixed(10))) : String(v);
const lit = v => typeof v === 'string' ? '"' + v + '"' : show(v);
const kindOf = v => v === null ? 'nil' : typeof v === 'boolean' ? 'true/false' : typeof v === 'string' ? 'a string' : 'a number';
const BUDGET = 100000;
function execute(prog, entry, args) {
  const out = []; let steps = 0, depth = 0;
  const halt = (msg, line) => fail(msg, line, 'Runtime error');
  const tick = line => { if (++steps > BUDGET) throw halt('Ran past ' + BUDGET.toLocaleString('en-US') + ' steps — is there a loop that never ends?', line); };
  const num = (v, line, op) => { if (typeof v !== 'number') throw halt('‘' + op + '’ needs numbers, but got ' + kindOf(v), line); return v; };
  const bool = (v, line, what) => { if (typeof v !== 'boolean') throw halt(what + ' needs true or false, but got ' + kindOf(v) + ' (' + show(v) + ')', line); return v; };
  const B = {
    print: a => { out.push(a.map(show).join(' ')); return null; },
    str: a => show(a[0]),
    floor: (a, l) => Math.floor(num(a[0], l, 'floor')),
    abs: (a, l) => Math.abs(num(a[0], l, 'abs')),
    min: (a, l) => Math.min(...a.map(x => num(x, l, 'min'))),
    max: (a, l) => Math.max(...a.map(x => num(x, l, 'max'))),
    len: (a, l) => { if (typeof a[0] !== 'string') throw halt('len() needs a string', l); return a[0].length; },
  };
  const fns = new Map();
  prog.forEach(s => { if (s.k === 'fn') fns.set(s.name, s); });
  const G = { vars: new Map(), up: null };
  const scope = up => ({ vars: new Map(), up });
  const find = (env, n) => { for (let e = env; e; e = e.up) if (e.vars.has(n)) return e; return null; };
  function arith(op, l, r, line) {
    if (op === '+' && (typeof l === 'string' || typeof r === 'string')) return show(l) + show(r);
    num(l, line, op); num(r, line, op);
    if ((op === '/' || op === '%') && r === 0) throw halt('Division by zero', line);
    return op === '+' ? l + r : op === '-' ? l - r : op === '*' ? l * r : op === '/' ? l / r : l % r;
  }
  function value(e, env) {
    tick(e.line);
    switch (e.k) {
      case 'lit': return e.v;
      case 'var': { const sc = find(env, e.name); if (sc) return sc.vars.get(e.name); if (fns.has(e.name) || B[e.name]) throw halt('‘' + e.name + '’ is a function — call it with ()', e.line); throw halt('Unknown name ‘' + e.name + '’', e.line); }
      case 'un': { const v = value(e.e, env); return e.op === '-' ? -num(v, e.line, '-') : !bool(v, e.line, '!'); }
      case 'bin': {
        if (e.op === '&&') return bool(value(e.l, env), e.line, '&&') && bool(value(e.r, env), e.line, '&&');
        if (e.op === '||') return bool(value(e.l, env), e.line, '||') || bool(value(e.r, env), e.line, '||');
        const l = value(e.l, env), r = value(e.r, env);
        if (e.op === '==') return l === r;
        if (e.op === '!=') return l !== r;
        if (e.op === '<' || e.op === '<=' || e.op === '>' || e.op === '>=') {
          if (!(typeof l === 'number' && typeof r === 'number') && !(typeof l === 'string' && typeof r === 'string')) throw halt('Can’t compare ' + kindOf(l) + ' with ' + kindOf(r), e.line);
          return e.op === '<' ? l < r : e.op === '<=' ? l <= r : e.op === '>' ? l > r : l >= r;
        }
        return arith(e.op, l, r, e.line);
      }
      case 'call': {
        if (e.f.k !== 'var') throw halt('Only named functions can be called', e.line);
        const name = e.f.name, args = e.args.map(a => value(a, env));
        if (fns.has(name)) return call(fns.get(name), args, e.line);
        if (B[name]) return B[name](args, e.line);
        throw halt('There is no function called ‘' + name + '’', e.line);
      }
    }
    return null;
  }
  function call(f, args, line) {
    if (args.length !== f.params.length) throw halt(f.name + '() takes ' + f.params.length + ' argument' + (f.params.length === 1 ? '' : 's') + ' but got ' + args.length, line);
    if (++depth > 200) throw halt('Recursion went deeper than 200 calls', line);
    const env = { vars: new Map(f.params.map((p, i) => [p, args[i]])), up: G };
    const r = run(f.body, env); depth--;
    return r ? r.ret : null;
  }
  function run(body, env) { for (const s of body) { const r = step(s, env); if (r) return r; } return null; }
  function step(s, env) {
    tick(s.line);
    switch (s.k) {
      case 'fn': return null;
      case 'let': if (env.vars.has(s.name)) throw halt('‘' + s.name + '’ is already declared in this block', s.line); env.vars.set(s.name, value(s.e, env)); return null;
      case 'set': {
        const sc = find(env, s.name);
        if (!sc) throw halt('Declare ‘' + s.name + '’ with let before assigning to it', s.line);
        let v = value(s.e, env); if (s.op !== '=') v = arith(s.op[0], sc.vars.get(s.name), v, s.line);
        sc.vars.set(s.name, v); return null;
      }
      case 'if': if (bool(value(s.c, env), s.line, 'if')) return run(s.then, scope(env)); return s.els ? run(s.els, scope(env)) : null;
      case 'while': while (bool(value(s.c, env), s.line, 'while')) { const r = run(s.body, scope(env)); if (r) return r; } return null;
      case 'for': { const a = num(value(s.a, env), s.line, '..'), b = num(value(s.b, env), s.line, '..'); for (let i = a; i < b; i++) { const sc = scope(env); sc.vars.set(s.name, i); const r = run(s.body, sc); if (r) return r; tick(s.line); } return null; }
      case 'return': return { ret: s.e ? value(s.e, env) : null };
      case 'expr': value(s.e, env); return null;
    }
    return null;
  }
  run(prog, G);
  if (!fns.has(entry)) throw fail('Define fn ' + entry + '(…) — the tests call it', 1, 'Missing function');
  const ret = call(fns.get(entry), args, fns.get(entry).line);
  return { ret, out, steps };
}

/* ── exercises ───────────────────────────────────────── */
const EXS = [
  { name: 'gcd', title: 'Greatest common divisor', level: 'Warm-up', params: 'a, b',
    brief: ['Return the largest whole number that divides both <code>a</code> and <code>b</code>. Either one may be zero.'],
    tests: [[[12, 18], 6], [[17, 5], 1], [[100, 75], 25], [[0, 9], 9], [[81, 27], 27]],
    hint: 'Euclid’s trick: while b isn’t 0, replace the pair (a, b) with (b, a % b). When b reaches 0, a is the answer.',
    starter: '// Return the largest number that divides both a and b.\nfn gcd(a, b) {\n  return 0\n}\n',
    solution: '// Euclid: the remainder keeps shrinking until it hits 0.\nfn gcd(a, b) {\n  while b != 0 {\n    let t = b\n    b = a % b\n    a = t\n  }\n  return a\n}\n' },
  { name: 'isLeap', title: 'Leap years', level: 'Conditions', params: 'year',
    brief: ['Return <code>true</code> if <code>year</code> is a leap year in the Gregorian calendar.', 'A year is a leap year when it divides by 4 — except century years, which only count when they also divide by 400.'],
    tests: [[[2024], true], [[2023], false], [[1900], false], [[2000], true], [[2100], false], [[1996], true]],
    hint: 'Check the most specific rule first: divisible by 400 is always a leap year; divisible by 100 (but not 400) never is; then fall back to the 4 rule.',
    starter: '// Return true when year is a leap year.\nfn isLeap(year) {\n  return false\n}\n',
    solution: 'fn isLeap(year) {\n  if year % 400 == 0 {\n    return true\n  }\n  if year % 100 == 0 {\n    return false\n  }\n  return year % 4 == 0\n}\n' },
  { name: 'digitSum', title: 'Digit sum', level: 'Loops', params: 'n',
    brief: ['Add up the decimal digits of a whole number <code>n</code> (n ≥ 0). For 123 that is 1 + 2 + 3.'],
    tests: [[[0], 0], [[7], 7], [[123], 6], [[9999], 36], [[50607], 18]],
    hint: 'n % 10 is the last digit and floor(n / 10) drops it. Keep a running total until n is 0.',
    starter: 'fn digitSum(n) {\n  let total = 0\n  return total\n}\n',
    solution: 'fn digitSum(n) {\n  let total = 0\n  while n > 0 {\n    total += n % 10\n    n = floor(n / 10)\n  }\n  return total\n}\n' },
  { name: 'steps', title: 'Collatz steps', level: 'Loops', params: 'n',
    brief: ['Starting from <code>n</code>, halve it when it’s even, otherwise make it 3n + 1. Return how many steps it takes to reach 1.'],
    tests: [[[1], 0], [[2], 1], [[6], 8], [[7], 16], [[27], 111]],
    hint: 'Count inside a while loop that runs until n == 1. Use n % 2 == 0 to test for even.',
    starter: 'fn steps(n) {\n  let count = 0\n  return count\n}\n',
    solution: 'fn steps(n) {\n  let count = 0\n  while n != 1 {\n    if n % 2 == 0 {\n      n = n / 2\n    } else {\n      n = 3 * n + 1\n    }\n    count += 1\n  }\n  return count\n}\n' },
  { name: 'fizz', title: 'FizzBuzz, one word', level: 'Strings', params: 'n',
    brief: ['Return <code>"Fizz"</code> for multiples of 3, <code>"Buzz"</code> for multiples of 5, <code>"FizzBuzz"</code> for both, and otherwise the number as a string.'],
    tests: [[[3], 'Fizz'], [[5], 'Buzz'], [[15], 'FizzBuzz'], [[7], '7'], [[30], 'FizzBuzz'], [[9], 'Fizz']],
    hint: 'Test the both-case first, or build the word up: start with "", add "Fizz" and "Buzz", and fall back to str(n) if it’s still empty.',
    starter: 'fn fizz(n) {\n  return str(n)\n}\n',
    solution: 'fn fizz(n) {\n  let word = ""\n  if n % 3 == 0 {\n    word += "Fizz"\n  }\n  if n % 5 == 0 {\n    word += "Buzz"\n  }\n  if word == "" {\n    return str(n)\n  }\n  return word\n}\n' },
];
const ATTEMPT = '// A year is a leap year if it divides by 4,\n// except centuries, unless they divide by 400.\nfn isLeap(year) {\n  if year % 4 == 0 {\n    return true\n  }\n  return false\n}\n';
const S = {
  cur: 1, view: 'code', sel: null, hint: false, arm: false,
  code: EXS.map((x, i) => i === 0 ? x.solution : i === 1 ? ATTEMPT : x.starter),
  results: EXS.map(() => null), runs: EXS.map(() => 0), solved: EXS.map((_, i) => i === 0), dirty: EXS.map(() => false), err: null,
};

/* ── running the tests ───────────────────────────────────────── */
function test(i) {
  const ex = EXS[i], src = S.code[i];
  let prog;
  try { prog = parse(src); }
  catch (e) { return { err: e, rows: ex.tests.map(([args, want]) => ({ args, want, ok: false, msg: e.kind + ' on line ' + e.line })) }; }
  const rows = ex.tests.map(([args, want]) => {
    try { const r = execute(prog, ex.name, args); return { args, want, got: r.ret, ok: r.ret === want, out: r.out, steps: r.steps }; }
    catch (e) { return { args, want, ok: false, msg: e.kind + ': ' + e.message, line: e.line, out: [] }; }
  });
  const firstErr = rows.find(r => r.line);
  return { rows, err: firstErr ? { message: firstErr.msg.replace(/^[^:]+: /, ''), line: firstErr.line, kind: firstErr.msg.split(':')[0] } : null };
}

/* ── editor ───────────────────────────────────────── */
const ta = $('[data-ta]'), hl = $('[data-hl]'), gut = $('[data-gut]'), scroller = $('[data-scroll]');
const TOK = /(\/\/[^\n]*)|("(?:[^"\\\n]|\\.)*"?)|\b(fn|let|if|else|while|for|in|return)\b|\b(true|false|nil)\b|\b(\d[\d_]*(?:\.\d+)?)\b|\b([A-Za-z_]\w*)(?=\s*\()|(==|!=|<=|>=|&&|\|\||\+=|-=|\*=|\.\.|[-+*/%=<>!])/g;
function highlight(src) {
  let out = '', last = 0, m;
  TOK.lastIndex = 0;
  while ((m = TOK.exec(src))) {
    out += esc(src.slice(last, m.index));
    const cls = m[1] ? 'c' : m[2] ? 's' : m[3] ? 'k' : m[4] ? 'b' : m[5] ? 'n' : m[6] ? 'f' : 'o';
    out += '<span class="ale-code-' + cls + '">' + esc(m[0]) + '</span>';
    last = TOK.lastIndex;
  }
  return out + esc(src.slice(last)) + '\n';
}
function lineOfCaret() { return ta.value.slice(0, ta.selectionStart).split('\n').length; }
let lastLines = -1, lastCur = -1;
function paint() {
  const src = ta.value, n = src.split('\n').length;
  hl.innerHTML = highlight(src);
  const errL = S.err && S.err.line;
  gut.innerHTML = Array.from({ length: n }, (_, k) => k + 1 === errL ? '<em>' + (k + 1) + '</em>' : k + 1 === lastCur ? '<b>' + (k + 1) + '</b>' : String(k + 1)).join('\n');
  lastLines = n;
  const eb = $('[data-errbar]');
  eb.hidden = !errL; if (errL) eb.style.setProperty('--l', errL);
}
function caret() {
  const l = lineOfCaret(), col = ta.selectionStart - ta.value.lastIndexOf('\n', ta.selectionStart - 1);
  $('[data-pos]').textContent = 'Ln ' + l + ', Col ' + col;
  $('[data-curline]').style.setProperty('--l', l);
