  --ale-grades-side: color-mix(in oklch, var(--ale-grades-bg) 95%, var(--ale-grades-ink));
  --ale-grades-line: color-mix(in oklch, var(--ale-grades-ink) 10%, transparent);
  --ale-grades-line2: color-mix(in oklch, var(--ale-grades-ink) 19%, transparent);
  --ale-grades-mute: color-mix(in oklch, var(--ale-grades-ink) 60%, var(--ale-grades-bg));
  --ale-grades-faint: color-mix(in oklch, var(--ale-grades-ink) 36%, var(--ale-grades-bg));
  --ale-grades-hover: color-mix(in oklch, var(--ale-grades-ink) 5%, transparent);
  --ale-grades-tint: color-mix(in oklch, var(--ale-grades-accent) 11%, var(--ale-grades-card));
  --ale-grades-warn: oklch(0.72 0.14 75);
  --ale-grades-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-grades-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-grades-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-grades-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-grades-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-grades-bg); color: var(--ale-grades-ink); color-scheme: light; accent-color: var(--ale-grades-accent);
