  width: 100%; height: 34px; border: 0; background: none; display: flex; align-items: center; gap: 9px; padding: 0 10px 0 12px; text-align: left; font-weight: 560;
  & i { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font: 700 9px var(--ale-grades-sans); font-style: normal; color: white; flex: none; }
  & span { overflow: hidden; text-overflow: ellipsis; }
  & u { margin-left: auto; text-decoration: none; width: 6px; height: 6px; border-radius: 50%; background: var(--ale-grades-pen); flex: none; }
  &:hover { background: var(--ale-grades-hover); }
  &[aria-pressed="true"] { background: var(--ale-grades-tint); color: var(--ale-grades-accent); }
}
.ale-grades .ale-grades-c {
  --p: 0;
  position: relative; text-align: center; font: 500 12.5px var(--ale-grades-mono); cursor: cell; outline: 0;
  /* mixed in oklab: no hue to interpolate, so a low score never drifts toward the accent's hue */
  background: color-mix(in oklab, var(--ale-grades-pen) calc(max(0, 0.6 - var(--p)) * 30%), color-mix(in oklab, var(--ale-grades-accent) calc(max(0, var(--p) - 0.75) * 34%), transparent));
  &.is-empty { color: var(--ale-grades-faint); }
  &.is-m span { display: inline-block; padding: 1px 6px; border-radius: 5px; background: color-mix(in oklch, var(--ale-grades-pen) 14%, transparent); color: var(--ale-grades-pen); font-weight: 700; font-size: 11px; }
  &.is-x span { display: inline-block; padding: 1px 5px; border-radius: 5px; background: var(--ale-grades-line); color: var(--ale-grades-mute); font-weight: 600; font-size: 10.5px; }
  &.is-colsel { box-shadow: inset 0 0 0 9999px color-mix(in oklch, var(--ale-grades-accent) 5%, transparent); }
  &:focus { box-shadow: inset 0 0 0 2px var(--ale-grades-accent); z-index: 1; }
  &.is-flash { animation: ale-grades-flash 1s var(--ale-grades-ease); }
  &.is-bad { animation: ale-grades-shake .4s var(--ale-grades-ease); box-shadow: inset 0 0 0 2px var(--ale-grades-pen); }
  & input { position: absolute; inset: 2px; width: calc(100% - 4px); border: 0; outline: 0; border-radius: 4px; text-align: center; font: 600 12.5px var(--ale-grades-mono); background: var(--ale-grades-card); box-shadow: 0 0 0 2px var(--ale-grades-accent), 0 6px 16px -6px color-mix(in oklch, var(--ale-grades-ink) 40%, transparent); }
}
/* the sticky name column grows an edge shadow only once the grid has scrolled sideways */
@supports (animation-timeline: scroll()) {
  .ale-grades .ale-grades-grid .ale-grades-name { animation: ale-grades-edge linear both; animation-timeline: scroll(nearest inline); animation-range: 0 48px; }
}
@keyframes ale-grades-edge { from { box-shadow: 0 0 0 transparent; } to { box-shadow: 8px 0 12px -8px color-mix(in oklab, var(--ale-grades-ink) 40%, transparent); } }
@keyframes ale-grades-flash { from { background: color-mix(in oklch, var(--ale-grades-warn) 45%, transparent); } }
@keyframes ale-grades-shake { 25% { transform: translateX(-3px); } 50% { transform: translateX(3px); } 75% { transform: translateX(-2px); } }
.ale-grades .ale-grades-avg { font: 700 12.5px var(--ale-grades-mono); text-align: center; min-width: 64px; }
.ale-grades .ale-grades-avg.is-risk { color: var(--ale-grades-pen); }
.ale-grades .ale-grades-let { text-align: center; min-width: 46px; & b { display: inline-grid; place-items: center; width: 24px; height: 22px; border-radius: 6px; font: 800 12px var(--ale-grades-sans); } }
.ale-grades .ale-grades-let[data-l="A"] b { background: color-mix(in oklch, var(--ale-grades-accent) 18%, transparent); color: var(--ale-grades-accent); }
.ale-grades .ale-grades-let[data-l="B"] b { background: color-mix(in oklch, var(--ale-grades-accent) 9%, transparent); color: var(--ale-grades-accent); }
.ale-grades .ale-grades-let[data-l="C"] b { background: var(--ale-grades-line); }
.ale-grades .ale-grades-let[data-l="D"] b { background: color-mix(in oklch, var(--ale-grades-warn) 22%, transparent); color: oklch(0.5 0.12 65); }
.ale-grades .ale-grades-let[data-l="F"] b { background: color-mix(in oklch, var(--ale-grades-pen) 16%, transparent); color: var(--ale-grades-pen); }
.ale-grades .ale-grades-grid tbody tr { transition: opacity .3s; }
.ale-grades .ale-grades-grid tbody tr:hover td, .ale-grades .ale-grades-grid tbody tr:hover .ale-grades-name { background-color: color-mix(in oklch, var(--ale-grades-ink) 2.5%, var(--ale-grades-bg)); }
.ale-grades .ale-grades-empty td { height: 120px; text-align: center; color: var(--ale-grades-faint); white-space: normal; }
.ale-grades .ale-grades-keys {
  display: flex; gap: 14px; flex-wrap: wrap; padding: 8px 16px 9px 20px; border-top: 1px solid var(--ale-grades-line); font-size: 11px; color: var(--ale-grades-faint);
  & kbd { padding: 2px 4px; font-size: 9.5px; margin-right: 3px; }
  & .ale-grades-saved { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; }
  & .ale-grades-saved::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--ale-grades-accent); }
  & .ale-grades-saved.is-saving::before { background: var(--ale-grades-warn); animation: ale-grades-blink .7s ease-in-out infinite; }
}
@keyframes ale-grades-blink { 50% { opacity: .3; } }

/* ── panel ─────────────────────────────── */
.ale-grades .ale-grades-panel { grid-area: panel; overflow: auto; min-height: 0; padding: 16px 16px 20px; border-left: 1px solid var(--ale-grades-line); background: var(--ale-grades-side); display: flex; flex-direction: column; gap: 16px; scrollbar-width: thin; & > * { flex: none; } }
.ale-grades .ale-grades-ph {
  display: grid; gap: 2px; animation: ale-grades-in .4s var(--ale-grades-ease) both;
  & > p { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-grades-accent); }
  & h2 { font-size: 18px; font-weight: 740; letter-spacing: -.02em; text-wrap: balance; }
  & span { font-size: 12px; color: var(--ale-grades-mute); }
}
@keyframes ale-grades-in { from { opacity: 0; transform: translateY(6px); } }
.ale-grades .ale-grades-back { align-self: flex-start; border: 0; background: none; padding: 4px 6px 4px 2px; margin: -4px 0 -6px; display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 600; color: var(--ale-grades-mute); border-radius: 7px; & svg { width: 15px; height: 15px; } &:hover { color: var(--ale-grades-ink); background: var(--ale-grades-hover); } }
.ale-grades .ale-grades-kpi {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--ale-grades-line);
  & div { background: var(--ale-grades-card); padding: 9px 10px; display: grid; }
  & b { font-size: 17px; font-weight: 750; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & span { font-size: 10.5px; color: var(--ale-grades-mute); }
}
.ale-grades .ale-grades-sec {
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-grades-mute); margin-bottom: 8px; display: flex; justify-content: space-between; }
  & h3 span { letter-spacing: 0; text-transform: none; font-weight: 500; color: var(--ale-grades-faint); }
}
.ale-grades .ale-grades-dist { display: grid; gap: 6px; }
.ale-grades .ale-grades-drow {
  --i: 0;
  display: grid; grid-template-columns: 22px 1fr 26px; gap: 8px; align-items: center; font-size: 12px;
  & b { font-weight: 800; text-align: center; }
  & i { height: 14px; border-radius: 4px; background: var(--ale-grades-line); overflow: hidden; display: block; }
  & i u { display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--c, var(--ale-grades-accent)); border-radius: 4px; transform-origin: left; animation: ale-grades-grow .6s var(--ale-grades-ease) both; animation-delay: calc(var(--i) * 50ms); text-decoration: none; transition: width .5s var(--ale-grades-ease); }
  & span { font: 600 11.5px var(--ale-grades-mono); text-align: right; color: var(--ale-grades-mute); }
}
@keyframes ale-grades-grow { from { transform: scaleX(0); } }
.ale-grades .ale-grades-hist {
  display: grid; grid-template-columns: repeat(10, 1fr); gap: 3px; align-items: end; height: 96px;
  & div { display: grid; grid-template-rows: auto 1fr auto; height: 100%; gap: 3px; text-align: center; }
  & div i { align-self: end; display: block; height: calc(var(--h) * 100%); min-height: 2px; border-radius: 3px 3px 1px 1px; background: var(--ale-grades-accent); opacity: .85; transform-origin: bottom; animation: ale-grades-rise .55s var(--ale-grades-spring) both; animation-delay: calc(var(--i) * 30ms); transition: height .4s var(--ale-grades-ease); }
  & div.is-low i { background: var(--ale-grades-pen); }
  & div small { font: 600 9px var(--ale-grades-mono); color: var(--ale-grades-faint); }
  & div b { font: 700 9.5px var(--ale-grades-mono); color: var(--ale-grades-mute); align-self: end; }
}
@keyframes ale-grades-rise { from { transform: scaleY(0); } }
.ale-grades .ale-grades-list {
  display: grid; gap: 2px;
  & li { display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; padding: 6px 8px; border-radius: 8px; font-size: 12.5px; }
  & li span { font: 600 12px var(--ale-grades-mono); color: var(--ale-grades-mute); }
  & li button { border: 0; background: none; padding: 0; text-align: left; font-weight: 560; }
  & li button:hover { color: var(--ale-grades-accent); text-decoration: underline; }
  & li:hover { background: var(--ale-grades-hover); }
}
.ale-grades .ale-grades-catbar {
  display: grid; gap: 8px;
  & div { display: grid; grid-template-columns: 1fr auto; gap: 3px 8px; font-size: 12px; }
  & div span { font: 600 12px var(--ale-grades-mono); }
  & div i { grid-column: 1 / -1; height: 7px; border-radius: 4px; background: var(--ale-grades-line); overflow: hidden; }
  & div i u { display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--ale-grades-accent); text-decoration: none; transition: width .5s var(--ale-grades-ease); }
  & div.is-low i u { background: var(--ale-grades-pen); }
}
.ale-grades .ale-grades-note {
  display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: var(--ale-grades-card); border: 1px solid var(--ale-grades-line);
  & label { font-size: 11px; font-weight: 700; color: var(--ale-grades-mute); }
  & textarea { width: 100%; resize: vertical; min-height: 74px; border-radius: 8px; border: 1px solid var(--ale-grades-line2); padding: 8px 10px; font-size: 12.5px; line-height: 1.45; outline: 0; background: var(--ale-grades-bg); }
  & textarea:focus { border-color: var(--ale-grades-accent); }
