  & div { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
  & small { font-size: 11px; color: var(--ale-grades-faint); }
  & small.is-err { color: var(--ale-grades-pen); font-weight: 600; }
  & .ale-grades-sent { display: flex; gap: 8px; align-items: center; color: var(--ale-grades-accent); font-weight: 650; font-size: 12.5px; animation: ale-grades-in .4s var(--ale-grades-ease) both; }
}

/* ── weights sheet, toast, nav ─────────────────────────────── */
.ale-grades .ale-grades-pop {
  position: absolute; z-index: 30; top: 58px; right: 80px; width: min(320px, calc(100% - 24px)); padding: 16px; border-radius: 14px; margin: 0;
  background: var(--ale-grades-card); box-shadow: 0 0 0 1px var(--ale-grades-line), 0 24px 50px -18px color-mix(in oklch, var(--ale-grades-ink) 40%, transparent);
  display: grid; gap: 10px; transform-origin: top right; transition: opacity .2s, transform .35s var(--ale-grades-spring);
  @starting-style { opacity: 0; transform: scale(.95) translateY(-6px); }
  & h2 { font-size: 15px; font-weight: 720; }
  & > p { font-size: 12px; color: var(--ale-grades-mute); text-wrap: pretty; }
  & footer { display: flex; justify-content: flex-end; gap: 8px; }
}
.ale-grades .ale-grades-wrow {
  display: grid; grid-template-columns: 1fr 120px 52px; gap: 10px; align-items: center; font-size: 12.5px; font-weight: 600;
  & input[type="range"] { width: 100%; }
  & input[type="number"] { width: 100%; height: 28px; border-radius: 7px; border: 1px solid var(--ale-grades-line2); padding: 0 6px; text-align: right; font: 600 12px var(--ale-grades-mono); }
}
.ale-grades .ale-grades-wsum { font: 600 12px var(--ale-grades-mono); color: var(--ale-grades-accent); &.is-err { color: var(--ale-grades-pen); } }
.ale-grades .ale-grades-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 46px; translate: -50% 16px; display: flex; align-items: center; gap: 12px;
  padding: 8px 8px 8px 14px; border-radius: 12px; background: var(--ale-grades-ink); color: var(--ale-grades-card); font-size: 12.5px;
  box-shadow: 0 16px 34px -14px color-mix(in oklch, var(--ale-grades-ink) 70%, transparent); opacity: 0; visibility: hidden; transition: opacity .25s, translate .4s var(--ale-grades-spring), visibility 0s .4s;
  & button { border: 0; border-radius: 8px; padding: 5px 10px; background: color-mix(in oklch, var(--ale-grades-card) 14%, transparent); color: var(--ale-grades-card); font-weight: 650; font-size: 12px; }
  &.is-on { opacity: 1; visibility: visible; translate: -50% 0; transition: opacity .25s, translate .4s var(--ale-grades-spring), visibility 0s; }
  &:not(.has-undo) button { display: none; }
}
.ale-grades .ale-grades-nav {
  grid-area: nav; display: none; padding: 4px 6px 6px; border-top: 1px solid var(--ale-grades-line); background: var(--ale-grades-side);
  & button { flex: 1; border: 0; background: none; display: grid; justify-items: center; gap: 2px; padding: 6px 4px; border-radius: 10px; font-size: 11px; font-weight: 600; color: var(--ale-grades-mute); }
  & button svg { width: 20px; height: 20px; }
  & button[aria-selected="true"] { color: var(--ale-grades-accent); background: var(--ale-grades-tint); }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 1080px) {
  .ale-grades .ale-grades-app { grid-template-columns: minmax(0, 1fr) 264px; }
  .ale-grades .ale-grades-search { width: 140px; }
}
@container (max-width: 959px) {
  .ale-grades .ale-grades-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "nav"; }
  .ale-grades .ale-grades-nav { display: flex; }
  .ale-grades .ale-grades-panel { grid-area: main; border-left: 0; }
  .ale-grades[data-view="grid"] .ale-grades-panel, .ale-grades[data-view="panel"] .ale-grades-main { display: none; }
  .ale-grades .ale-grades-pop { right: 12px; }
}
@container (max-width: 759px) {
  .ale-grades .ale-grades-top { padding: 12px 12px 10px 14px; gap: 10px; }
  .ale-grades .ale-grades-ttl p, .ale-grades .ale-grades-ttl h1 span { display: none; }
  .ale-grades .ale-grades-search { width: auto; flex: 1; min-width: 120px; }
  .ale-grades .ale-grades-tools { width: 100%; }
  .ale-grades .ale-grades-btn span { display: none; }
  .ale-grades .ale-grades-keys span:not(.ale-grades-saved) { display: none; }
  .ale-grades .ale-grades-grid .ale-grades-name { min-width: 128px; }
  .ale-grades .ale-grades-pop { top: 104px; }
}
@container (max-width: 460px) {
  .ale-grades .ale-grades-stu i { display: none; }
  .ale-grades .ale-grades-grid .ale-grades-name { min-width: 104px; max-width: 120px; }
}

@media (prefers-reduced-motion: reduce) {
  .ale-grades *, .ale-grades *::before, .ale-grades *::after { animation-duration: 1ms !important; animation-delay: 0s !important; transition-duration: 1ms !important; }
  .ale-grades .ale-grades-keys .ale-grades-saved.is-saving::before { animation: none !important; }
  .ale-grades .ale-grades-grid .ale-grades-name { animation: none !important; box-shadow: 1px 0 0 var(--ale-grades-line2); }
}

