/* Harrow Lane — Year 10 Chemistry gradebook.
   One grade() function turns raw scores into category percentages and a weighted term
   grade; the grid, letters, class averages, histograms and student breakdowns all read
   it, so an edit in one cell moves every number that depends on it. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const I = {
  sort: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M7 14l5 5 5-5"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 6-6 6 6 6"/></svg>',
  ok: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
};
const CATS = [{ id: 'hw', name: 'Homework', w: 20 }, { id: 'pr', name: 'Practicals', w: 30 }, { id: 'ts', name: 'Tests', w: 50 }];
const COLS = [
  { id: 'hw1', cat: 'hw', name: 'HW1', title: 'Moles and mass', max: 10 },
  { id: 'hw2', cat: 'hw', name: 'HW2', title: 'Ionic bonding', max: 10 },
  { id: 'hw3', cat: 'hw', name: 'HW3', title: 'Rates of reaction', max: 10 },
  { id: 'hw4', cat: 'hw', name: 'HW4', title: 'Equilibrium', max: 10 },
  { id: 'p1', cat: 'pr', name: 'P1', title: 'Titration', max: 20 },
  { id: 'p2', cat: 'pr', name: 'P2', title: 'Electrolysis', max: 20 },
  { id: 'p3', cat: 'pr', name: 'P3', title: 'Chromatography', max: 20 },
  { id: 't1', cat: 'ts', name: 'Test 1', title: 'Atomic structure', max: 50 },
  { id: 't2', cat: 'ts', name: 'Test 2', title: 'Quantitative chemistry', max: 50 },
];
const NAMES = ['Amara Okonkwo', 'Ben Halvorsen', 'Chiara Russo', 'Dev Malhotra', 'Elif Kaya', 'Finn O’Driscoll', 'Grace Mbeki', 'Hugo Lambert', 'Isla McKenzie', 'Jonah Weiss', 'Kenji Arai', 'Leila Haddad', 'Mateo Fernández', 'Nadia Petrova', 'Owen Price', 'Priya Raman', 'Rosa Lindqvist', 'Sami Nieminen'];
const GUARDIANS = ['Mrs Okonkwo', 'Mr Halvorsen', 'Ms Russo', 'Mr and Mrs Malhotra', 'Mrs Kaya', 'Ms O’Driscoll', 'Mr Mbeki', 'Mme Lambert', 'Mrs McKenzie', 'Dr Weiss', 'Mr Arai', 'Mrs Haddad', 'Sr Fernández', 'Ms Petrova', 'Mr Price', 'Dr Raman', 'Ms Lindqvist', 'Mr Nieminen'];
/* scores: number, 'M' missing (counts as 0), 'X' excused (ignored), '' not marked yet */
const RAW = [
  [9, 10, 8, 9, 18, 17, 19, 46, 44], [7, 6, 'M', 5, 13, 12, 14, 31, 29], [10, 9, 10, 10, 19, 20, 18, 48, 47], [6, 'M', 5, '', 11, 'M', 12, 27, 24],
  [8, 8, 9, 8, 16, 17, 15, 41, 43], [5, 6, 4, '', 10, 9, 11, 24, 26], [9, 9, 9, 10, 17, 18, 18, 44, 45], [8, 7, 7, '', 15, 14, 'X', 37, 35],
  [10, 10, 9, 9, 18, 19, 20, 47, 49], [6, 7, 6, 7, 12, 13, 13, 33, 30], [9, 8, 10, '', 17, 16, 17, 42, 40], [7, 8, 7, 8, 14, 15, 16, 36, 39],
  [4, 'M', 5, '', 9, 10, 'M', 22, 21], [9, 10, 9, 9, 19, 18, 19, 45, 46], [6, 5, 7, 6, 12, 11, 12, 30, 32], [10, 9, 9, '', 18, 18, 17, 43, 44],
  [8, 'X', 8, 9, 16, 15, 16, 39, 38], [7, 7, 6, 7, 13, 14, 12, 34, 33],
];
const HUES = [25, 70, 145, 200, 250, 300, 340, 105];
const S = {
  data: RAW.map(r => r.slice()), weights: CATS.map(c => c.w), filter: 'all', q: '', sort: ['name', 1],
  r: 0, c: 0, editing: null, panel: { mode: 'class', id: null }, view: 'grid', notes: {},
};
const undo = [], redo = [];

/* ── maths ───────────────────────────────────────── */
const isNum = v => typeof v === 'number';
function grade(i, weights = S.weights) {
  const row = S.data[i], cats = {};
  CATS.forEach((cat, k) => {
    let got = 0, poss = 0;
    COLS.forEach((col, c) => { if (col.cat !== cat.id) return; const v = row[c]; if (isNum(v)) { got += v; poss += col.max; } else if (v === 'M') poss += col.max; });
    cats[cat.id] = poss ? { pct: got / poss, got, poss, w: weights[k] } : null;
  });
  const used = Object.values(cats).filter(Boolean), wsum = used.reduce((a, x) => a + x.w, 0);
  const pct = wsum ? used.reduce((a, x) => a + x.pct * x.w, 0) / wsum : null;
  return { pct, cats, missing: row.filter(v => v === 'M').length };
}
const letter = p => p == null ? '—' : p >= 0.9 ? 'A' : p >= 0.8 ? 'B' : p >= 0.7 ? 'C' : p >= 0.6 ? 'D' : 'F';
const pctTxt = (p, d = 1) => p == null ? '—' : (100 * p).toFixed(d) + '%';
const RISK = 0.65;
const initials = n => n.split(' ').map(x => x[0]).join('').slice(0, 2);
function colStats(c) {
  const vals = S.data.map(r => r[c]).filter(v => isNum(v) || v === 'M').map(v => isNum(v) ? v : 0);
  const sorted = vals.slice().sort((a, b) => a - b), n = vals.length, max = COLS[c].max;
  const mean = n ? vals.reduce((a, b) => a + b, 0) / n : null;
  const median = n ? (n % 2 ? sorted[(n - 1) / 2] : (sorted[n / 2 - 1] + sorted[n / 2]) / 2) : null;
  return { n, mean, median, min: n ? sorted[0] : null, hi: n ? sorted[n - 1] : null, max, missing: S.data.filter(r => r[c] === 'M').length, excused: S.data.filter(r => r[c] === 'X').length, blank: S.data.filter(r => r[c] === '').length, vals };
}

/* ── rendering ───────────────────────────────────────── */
const head = $('[data-head]'), body = $('[data-body]'), foot = $('[data-foot]'), panel = $('[data-panel]');
function visibleRows() {
  const q = S.q.trim().toLowerCase();
