  e.preventDefault();
  const ta = $('[data-msg]'), err = $('[data-msgerr]');
  if (ta.value.trim().length < 12) { ta.setAttribute('aria-invalid', 'true'); err.textContent = 'Write at least a sentence before sending'; err.classList.add('is-err'); ta.focus(); return; }
  S.notes[S.panel.id] = '14:' + String(20 + Object.keys(S.notes).length).padStart(2, '0');
  renderPanel(); toast('Note sent to ' + GUARDIANS[S.panel.id]);
});
$('[data-q]').addEventListener('input', e => { S.q = e.target.value; S.r = 0; renderBody(); });
function syncFilter() { $$('[data-filter]').forEach(b => { const on = b.dataset.filter === S.filter; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); }
function setView(v) { root.dataset.view = v; $$('.ale-grades-nav [role=tab]').forEach(b => b.setAttribute('aria-selected', b.dataset.view === v)); }
function showPanelIfNarrow() { if (!panel.offsetParent || root.dataset.view === 'grid') { if ($('.ale-grades-nav').offsetParent) setView('panel'); } }

root.addEventListener('keydown', e => {
  const tg = e.target, k = e.key, mod = e.metaKey || e.ctrlKey;
  if (!pop.hidden && k === 'Escape') { e.preventDefault(); closeWeights(); return $('[data-act="weights"]').focus(); }
  if (tg.matches('.ale-grades-c input')) {
    if (k === 'Enter') { e.preventDefault(); return endEdit(true, e.shiftKey ? 'up' : 'down'); }
    if (k === 'Tab') { e.preventDefault(); return endEdit(true, e.shiftKey ? 'left' : 'right'); }
    if (k === 'Escape') { e.preventDefault(); return endEdit(false); }
    return;
  }
  if (mod && (k === 'z' || k === 'Z') && !tg.matches('input, textarea')) { e.preventDefault(); return e.shiftKey ? applyUndo(redo, undo, 1) : applyUndo(undo, redo, -1); }
  if (tg.matches('[data-filter]') && (k === 'ArrowRight' || k === 'ArrowLeft')) {
    const f = ['all', 'risk', 'missing'], n = f[(f.indexOf(S.filter) + (k === 'ArrowRight' ? 1 : 2)) % 3];
    e.preventDefault(); S.filter = n; syncFilter(); renderAll(); return $('[data-filter="' + n + '"]').focus();
  }
  if (!tg.matches('.ale-grades-c')) return;
  const d = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }[k];
  if (d) { e.preventDefault(); return focusCell(S.r + d[0], S.c + d[1]); }
  if (k === 'Home') { e.preventDefault(); return focusCell(mod ? 0 : S.r, 0); }
  if (k === 'End') { e.preventDefault(); return focusCell(mod ? rowsShown.length - 1 : S.r, COLS.length - 1); }
  if (k === 'Tab' && !e.shiftKey && S.c < COLS.length - 1) { e.preventDefault(); return focusCell(S.r, S.c + 1); }
  if (k === 'Tab' && e.shiftKey && S.c > 0) { e.preventDefault(); return focusCell(S.r, S.c - 1); }
  if (k === 'Enter' || k === 'F2') { e.preventDefault(); return startEdit(); }
  if (k === 'Backspace' || k === 'Delete') { e.preventDefault(); return setQuick(''); }
  if (k === 'm' || k === 'M') { e.preventDefault(); return setQuick('M'); }
  if (k === 'x' || k === 'X') { e.preventDefault(); return setQuick('X'); }
  if (/^[0-9.]$/.test(k) && !mod) { e.preventDefault(); return startEdit(k); }
});
root.addEventListener('focusout', e => { if (S.editing && e.target.matches('.ale-grades-c input') && !root.contains(e.relatedTarget)) endEdit(true); });

/* ── boot ───────────────────────────────────────── */
renderAll();
S.r = 3; S.c = 3;
renderBody();

css:
@property --ale-timetable-cr { syntax: '<number>'; inherits: true; initial-value: 0; }

.ale-timetable {
  /* re-theme with these four */
  --ale-timetable-bg: oklch(0.99 0.003 80);
  --ale-timetable-ink: oklch(0.22 0.02 260);
  --ale-timetable-accent: oklch(0.67 0.17 50);
  --ale-timetable-clash: oklch(0.57 0.2 25);
  /* derived */
  --ale-timetable-card: oklch(1 0 none);
  --ale-timetable-side: color-mix(in oklab, var(--ale-timetable-bg) 95%, var(--ale-timetable-ink));
  --ale-timetable-line: color-mix(in oklab, var(--ale-timetable-ink) 9%, transparent);
  --ale-timetable-line2: color-mix(in oklab, var(--ale-timetable-ink) 18%, transparent);
  --ale-timetable-mute: color-mix(in oklab, var(--ale-timetable-ink) 60%, var(--ale-timetable-bg));
  --ale-timetable-faint: color-mix(in oklab, var(--ale-timetable-ink) 36%, var(--ale-timetable-bg));
  --ale-timetable-hover: color-mix(in oklab, var(--ale-timetable-ink) 5%, transparent);
  --ale-timetable-tint: color-mix(in oklab, var(--ale-timetable-accent) 12%, var(--ale-timetable-card));
  --ale-timetable-hour: 52px;
  --ale-timetable-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-timetable-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-timetable-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-timetable-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-timetable-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-timetable-bg); color: var(--ale-timetable-ink); color-scheme: light; accent-color: var(--ale-timetable-accent);
  font: 13px/1.45 var(--ale-timetable-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-timetable-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h1, & h2, & h3, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; font: inherit; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--ale-timetable-mono); padding: 2px 4px; display: inline-block; border: 1px solid var(--ale-timetable-line2); border-bottom-width: 2px; border-radius: 4px; background: var(--ale-timetable-card); color: var(--ale-timetable-mute); }
}
.ale-timetable .ale-timetable-app { height: 100%; display: grid; grid-template-columns: 264px minmax(0, 1fr) 256px; grid-template-rows: minmax(0, 1fr) auto; grid-template-areas: "cat main sum" "nav nav nav"; }

/* ── catalogue ─────────────────────────────── */
.ale-timetable .ale-timetable-cat { grid-area: cat; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; background: var(--ale-timetable-side); border-right: 1px solid var(--ale-timetable-line); }
.ale-timetable .ale-timetable-cath {
  padding: 16px 14px 10px;
  & p { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-timetable-accent); }
  & h2 { font-size: 19px; font-weight: 760; letter-spacing: -.02em; margin-bottom: 10px; }
}
.ale-timetable .ale-timetable-search {
  display: flex; align-items: center; gap: 6px; height: 34px; padding: 0 10px; border-radius: 10px; border: 1px solid var(--ale-timetable-line2); background: var(--ale-timetable-card);
  & svg { width: 15px; height: 15px; color: var(--ale-timetable-faint); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; }
  &:focus-within { border-color: var(--ale-timetable-accent); }
}
.ale-timetable .ale-timetable-courses { overflow: auto; padding: 4px 8px 14px; scrollbar-width: thin; }
.ale-timetable .ale-timetable-course {
  --h: 200;
  position: relative; display: grid; grid-template-columns: 1fr auto; gap: 2px 8px; align-items: center; padding: 9px 8px 9px 14px; border-radius: 11px; margin-bottom: 2px;
  &::before { content: ""; position: absolute; left: 4px; top: 10px; bottom: 10px; width: 4px; border-radius: 2px; background: oklch(0.7 0.13 var(--h)); opacity: .35; transition: opacity .2s; }
  & b { font: 700 11px var(--ale-timetable-mono); letter-spacing: .02em; color: oklch(0.45 0.1 var(--h)); }
  & p { grid-column: 1; font-size: 12.5px; font-weight: 560; line-height: 1.3; }
  & small { grid-column: 1 / -1; font-size: 11px; color: var(--ale-timetable-faint); }
  & .ale-timetable-add { grid-row: 1 / 3; grid-column: 2; height: 28px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--ale-timetable-line2); background: var(--ale-timetable-card); font-size: 12px; font-weight: 650; display: inline-flex; align-items: center; gap: 4px; transition: background .2s, color .2s, border-color .2s, transform .25s var(--ale-timetable-spring); }
  & .ale-timetable-add svg { width: 14px; height: 14px; }
  & .ale-timetable-add:hover { border-color: var(--ale-timetable-ink); }
  & .ale-timetable-add:active { transform: scale(.94); }
  & .ale-timetable-add[aria-pressed="true"] { background: oklch(0.94 0.045 var(--h)); border-color: oklch(0.7 0.11 var(--h)); color: oklch(0.36 0.1 var(--h)); }
  &.is-on { background: var(--ale-timetable-card); box-shadow: 0 0 0 1px var(--ale-timetable-line); }
  &.is-on::before { opacity: 1; }
}

/* ── bar ─────────────────────────────── */
.ale-timetable .ale-timetable-main { grid-area: main; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-width: 0; min-height: 0; }
.ale-timetable .ale-timetable-bar { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid var(--ale-timetable-line); min-height: 62px; flex-wrap: wrap; }
.ale-timetable .ale-timetable-cred {
  display: grid; gap: 4px; min-width: 150px;
  & div { display: flex; align-items: baseline; gap: 6px; }
  & b { font-size: 18px; font-weight: 760; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & span { font-size: 11.5px; color: var(--ale-timetable-mute); }
  & i { position: relative; display: block; height: 6px; border-radius: 3px; background: var(--ale-timetable-line); overflow: hidden; }
  & i::before { content: ""; position: absolute; left: calc(15 / 21 * 100%); width: calc(3 / 21 * 100%); top: 0; bottom: 0; background: color-mix(in oklab, oklch(0.6 0.13 150) 25%, transparent); }
  & i u { position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--ale-timetable-cr) / 21 * 100%); background: var(--ale-timetable-ink); border-radius: 3px; transition: --ale-timetable-cr .6s var(--ale-timetable-spring); text-decoration: none; }
  &.is-over i u, &.is-under i u { background: var(--ale-timetable-clash); }
}
.ale-timetable .ale-timetable-chip {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 999px; font-size: 12px; font-weight: 650; border: 0;
  background: oklch(0.95 0.04 150); color: oklch(0.42 0.1 150);
  & svg { width: 14px; height: 14px; }
  &.is-bad { background: color-mix(in oklab, var(--ale-timetable-clash) 13%, var(--ale-timetable-card)); color: var(--ale-timetable-clash); }
}
button.ale-timetable-chip:hover { filter: brightness(.97); }
.ale-timetable .ale-timetable-flex { flex: 1; }
.ale-timetable .ale-timetable-btn {
  height: 34px; padding: 0 13px; border-radius: 10px; border: 1px solid var(--ale-timetable-line2); background: var(--ale-timetable-card); font-weight: 650; font-size: 12.5px; display: inline-flex; align-items: center; gap: 7px; white-space: nowrap;
  transition: border-color .15s, background .15s, transform .25s var(--ale-timetable-spring);
  & svg { width: 16px; height: 16px; }
  &:hover:not(:disabled) { border-color: var(--ale-timetable-ink); }
  &:active:not(:disabled) { transform: scale(.96); }
  &.is-pri { background: var(--ale-timetable-ink); color: var(--ale-timetable-card); border-color: var(--ale-timetable-ink); }
  &.is-acc { background: var(--ale-timetable-accent); border-color: var(--ale-timetable-accent); color: oklch(0.2 0.05 50); }
}
.ale-timetable .ale-timetable-ib { width: 32px; height: 32px; border: 0; border-radius: 9px; background: none; display: grid; place-items: center; color: var(--ale-timetable-mute); &:hover:not(:disabled) { background: var(--ale-timetable-hover); color: var(--ale-timetable-ink); } }
.ale-timetable .ale-timetable-solve {
  display: contents;
  & .ale-timetable-opt { display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 10px; background: var(--ale-timetable-ink); color: var(--ale-timetable-card); }
  & .ale-timetable-opt button { width: 30px; height: 30px; border: 0; border-radius: 8px; background: none; display: grid; place-items: center; color: inherit; }
  & .ale-timetable-opt button:hover:not(:disabled) { background: color-mix(in oklab, var(--ale-timetable-card) 15%, transparent); }
  & .ale-timetable-opt output { min-width: 108px; text-align: center; font-size: 12.5px; font-weight: 650; font-variant-numeric: tabular-nums; }
  & .ale-timetable-meta { font-size: 11.5px; color: var(--ale-timetable-mute); line-height: 1.3; font-variant-numeric: tabular-nums; }
}
.ale-timetable .ale-timetable-tg {
  height: 28px; padding: 0 10px; border-radius: 999px; border: 1px dashed var(--ale-timetable-line2); background: none; font-size: 12px; font-weight: 600; color: var(--ale-timetable-mute); display: inline-flex; align-items: center; gap: 5px;
  & svg { width: 13px; height: 13px; stroke-width: 2.4; opacity: 0; width: 0; transition: width .2s, opacity .2s; }
  &:hover { color: var(--ale-timetable-ink); border-color: var(--ale-timetable-mute); }
  &[aria-pressed="true"] { border-style: solid; border-color: var(--ale-timetable-accent); background: var(--ale-timetable-tint); color: oklch(0.42 0.13 50); }
  &[aria-pressed="true"] svg { opacity: 1; width: 13px; }
}

/* ── week ─────────────────────────────── */
.ale-timetable .ale-timetable-days { display: none; gap: 4px; padding: 8px 12px 0; }
.ale-timetable .ale-timetable-scroll { overflow: auto; min-height: 0; padding: 0 14px 16px 6px; scrollbar-width: thin; }
.ale-timetable .ale-timetable-week {
  position: relative; display: grid; grid-template-columns: 46px repeat(5, minmax(0, 1fr)); grid-template-rows: 34px calc(var(--ale-timetable-hour) * 10); min-width: 520px;
}
.ale-timetable .ale-timetable-dh {
  position: sticky; top: 0; z-index: 3; display: flex; align-items: flex-end; justify-content: center; gap: 5px; padding-bottom: 6px; background: var(--ale-timetable-bg);
  font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--ale-timetable-mute); border-bottom: 1px solid var(--ale-timetable-line2);
  & span { font: 600 10.5px var(--ale-timetable-mono); letter-spacing: 0; color: var(--ale-timetable-faint); text-transform: none; }
}
.ale-timetable .ale-timetable-hours { position: relative; & span { position: absolute; right: 8px; translate: 0 -50%; font: 500 10.5px var(--ale-timetable-mono); color: var(--ale-timetable-faint); font-variant-numeric: tabular-nums; } & span:first-child { translate: 0 2px; } }
.ale-timetable .ale-timetable-col {
  position: relative; border-left: 1px solid var(--ale-timetable-line);
  background: repeating-linear-gradient(to bottom, transparent 0 calc(var(--ale-timetable-hour) - 1px), var(--ale-timetable-line) calc(var(--ale-timetable-hour) - 1px) var(--ale-timetable-hour)),
    repeating-linear-gradient(to bottom, transparent 0 calc(var(--ale-timetable-hour) / 2 - 1px), color-mix(in oklab, var(--ale-timetable-ink) 4%, transparent) calc(var(--ale-timetable-hour) / 2 - 1px) calc(var(--ale-timetable-hour) / 2), transparent calc(var(--ale-timetable-hour) / 2) var(--ale-timetable-hour));
  &.is-off { background-color: color-mix(in oklab, var(--ale-timetable-ink) 3%, transparent); }
}
.ale-timetable .ale-timetable-shade { position: absolute; left: 0; right: 0; top: 0; pointer-events: none; background: repeating-linear-gradient(-45deg, transparent 0 6px, color-mix(in oklab, var(--ale-timetable-ink) 5%, transparent) 6px 7px); }
.ale-timetable .ale-timetable-blk {
  --h: 200; --lane: 0; --lanes: 1;
  position: absolute; top: calc(var(--s) * 100% + 1px); height: calc(var(--d) * 100% - 2px); left: calc(var(--lane) / var(--lanes) * 100% + 3px); width: calc(100% / var(--lanes) - 6px);
  border: 0; border-radius: 8px; padding: 5px 7px; text-align: left; overflow: hidden; display: grid; align-content: start; gap: 1px;
  background: oklch(0.945 0.045 var(--h)); color: oklch(0.32 0.09 var(--h)); box-shadow: inset 3px 0 0 oklch(0.62 0.13 var(--h));
  transition: box-shadow .2s, filter .2s, transform .25s var(--ale-timetable-spring);
  & p { display: flex; justify-content: space-between; gap: 4px; min-width: 0; }
  & b { font: 700 10px var(--ale-timetable-mono); letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: clip; }
  & em { font: 700 9px var(--ale-timetable-mono); font-style: normal; padding: 0 3px; border-radius: 4px; background: oklch(0.62 0.13 var(--h) / .16); white-space: nowrap; flex: none; }
  & span { font-size: 11px; line-height: 1.25; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font: 500 10px var(--ale-timetable-mono); opacity: .75; font-variant-numeric: tabular-nums; }
  &:hover { filter: brightness(.98) saturate(1.2); box-shadow: inset 3px 0 0 oklch(0.62 0.13 var(--h)), 0 6px 16px -8px oklch(0.4 0.1 var(--h) / .5); z-index: 2; }
  &.is-clash { background: repeating-linear-gradient(-45deg, oklch(0.945 0.045 var(--h)) 0 6px, color-mix(in oklab, var(--ale-timetable-clash) 14%, oklch(0.945 0.045 var(--h))) 6px 9px); box-shadow: inset 3px 0 0 var(--ale-timetable-clash), inset 0 0 0 1.5px var(--ale-timetable-clash); }
  &.is-ghost { background: color-mix(in oklab, oklch(0.945 0.045 var(--h)) 55%, transparent); box-shadow: inset 0 0 0 1.5px oklch(0.62 0.13 var(--h)); outline: 1.5px dashed oklch(0.62 0.13 var(--h)); outline-offset: -1.5px; pointer-events: none; z-index: 3; animation: ale-timetable-ghost .3s var(--ale-timetable-ease) both; }
  &.is-dim { opacity: .35; }
  &.is-short span { display: none; }
  &.is-sel { box-shadow: inset 3px 0 0 oklch(0.62 0.13 var(--h)), 0 0 0 2px var(--ale-timetable-ink); z-index: 2; }
  &.is-in { animation: ale-timetable-in .45s var(--ale-timetable-spring) both; animation-delay: calc(var(--i, 0) * 30ms); }
}
@keyframes ale-timetable-ghost { from { opacity: 0; } }
@keyframes ale-timetable-in { from { opacity: 0; transform: scale(.9); } }

/* ── picker ─────────────────────────────── */
.ale-timetable .ale-timetable-picker {
  position: absolute; z-index: 30; width: 290px; max-height: calc(100% - 24px); overflow: auto; padding: 12px; border-radius: 14px; background: var(--ale-timetable-card);
  box-shadow: 0 0 0 1px var(--ale-timetable-line), 0 24px 50px -16px color-mix(in oklab, var(--ale-timetable-ink) 45%, transparent);
  transition: opacity .2s, transform .35s var(--ale-timetable-spring); @starting-style { opacity: 0; transform: scale(.96) translateY(-4px); }
  & header { display: flex; justify-content: space-between; gap: 8px; align-items: start; margin-bottom: 8px; }
  & header b { font: 700 11px var(--ale-timetable-mono); }
  & header p { font-size: 13.5px; font-weight: 650; line-height: 1.25; }
  & h3 { font-size: 10px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--ale-timetable-faint); margin: 10px 2px 4px; }
  & footer { margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--ale-timetable-line); display: flex; justify-content: space-between; gap: 8px; }
}
.ale-timetable .ale-timetable-sec {
  width: 100%; display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; align-items: center; text-align: left; border: 0; background: none; padding: 7px 8px; border-radius: 9px;
  & i { width: 14px; height: 14px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ale-timetable-line2); }
  & span { font-size: 12.5px; font-weight: 600; }
  & small { display: block; font: 500 11px var(--ale-timetable-mono); color: var(--ale-timetable-mute); font-variant-numeric: tabular-nums; }
  & em { font-style: normal; font-size: 10.5px; font-weight: 700; padding: 2px 6px; border-radius: 999px; background: color-mix(in oklab, var(--ale-timetable-clash) 12%, transparent); color: var(--ale-timetable-clash); }
  & em.is-ok { background: oklch(0.95 0.04 150); color: oklch(0.42 0.1 150); }
  &:hover { background: var(--ale-timetable-hover); }
  &[aria-checked="true"] i { box-shadow: inset 0 0 0 4.5px var(--ale-timetable-ink); }
}

/* ── summary ─────────────────────────────── */
.ale-timetable .ale-timetable-sum { grid-area: sum; overflow: auto; min-height: 0; padding: 16px 16px 20px; background: var(--ale-timetable-side); border-left: 1px solid var(--ale-timetable-line); display: flex; flex-direction: column; gap: 16px; scrollbar-width: thin; & > * { flex: none; } }
.ale-timetable .ale-timetable-who {
  display: flex; gap: 10px; align-items: center;
  & i { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--ale-timetable-ink); color: var(--ale-timetable-card); font: 700 12px var(--ale-timetable-sans); font-style: normal; }
  & b { display: block; font-weight: 700; }
  & span { font-size: 11.5px; color: var(--ale-timetable-mute); }
}
.ale-timetable .ale-timetable-facts {
  display: grid; grid-template-columns: 1fr 1fr; gap: 1px; border-radius: 12px; overflow: hidden; background: var(--ale-timetable-line);
  & div { background: var(--ale-timetable-card); padding: 9px 10px; display: grid; }
  & b { font-size: 16px; font-weight: 750; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & span { font-size: 10.5px; color: var(--ale-timetable-mute); }
}
.ale-timetable .ale-timetable-sh { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-timetable-mute); margin-bottom: 6px; }
.ale-timetable .ale-timetable-load {
