  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  warn: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4.5M12 17.2v.1"/></svg>',
  wand: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 20 11-11M14 4v2M18 6l-1.4 1.4M20 10h-2M12.5 7.5l3 3"/></svg>',
  left: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 6-6 6 6 6"/></svg>',
  right: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg>',
  undo: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 14 4.5 9.5 9 5"/><path d="M4.5 9.5H15a4.5 4.5 0 0 1 0 9h-3"/></svg>',
  redo: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 14 4.5-4.5L15 5"/><path d="M19.5 9.5H9a4.5 4.5 0 0 0 0 9h3"/></svg>',
};
const COMP = { LEC: 'Lecture', LAB: 'Lab', TUT: 'Tutorial', SEM: 'Seminar', FLD: 'Field day' };
/* sections: [name, days (0 = Mon), start, end, room] */
const COURSES = [
  { id: 'envs', code: 'ENVS 210', title: 'Ecology of Rivers', cr: 4, h: 165, prof: 'Dr Ana Duarte', comps: {
    LEC: [['A', '02', '09:00', '10:15', 'Hollis 104'], ['B', '13', '13:00', '14:15', 'Hollis 104']],
    LAB: [['1', '1', '09:00', '11:50', 'Field Lab 2'], ['2', '3', '14:30', '17:20', 'Field Lab 2'], ['3', '4', '09:00', '11:50', 'Field Lab 2']] } },
  { id: 'chem', code: 'CHEM 142', title: 'General Chemistry II', cr: 4, h: 40, prof: 'Dr Felix Amadi', comps: {
    LEC: [['A', '024', '11:00', '11:50', 'Sato Hall'], ['B', '13', '10:30', '11:45', 'Sato Hall']],
    LAB: [['1', '2', '14:00', '16:50', 'Chem 210'], ['2', '4', '13:00', '15:50', 'Chem 210']] } },
  { id: 'stat', code: 'STAT 201', title: 'Statistics for Scientists', cr: 3, h: 255, prof: 'Prof. Mei Lindgren', comps: {
    LEC: [['A', '13', '09:00', '10:15', 'Quarry 12'], ['B', '02', '15:00', '16:15', 'Quarry 12']],
    TUT: [['1', '4', '10:00', '10:50', 'Quarry 3'], ['2', '2', '12:00', '12:50', 'Quarry 3']] } },
  { id: 'geog', code: 'GEOG 230', title: 'Mapping and GIS', cr: 3, h: 205, prof: 'Dr Tomas Reyes', comps: {
    LEC: [['A', '0', '13:00', '14:50', 'Marsh 1'], ['B', '3', '09:00', '10:50', 'Marsh 1']],
    LAB: [['1', '2', '09:00', '10:50', 'GIS Studio'], ['2', '4', '14:00', '15:50', 'GIS Studio']] } },
  { id: 'writ', code: 'WRIT 150', title: 'Writing about Science', cr: 3, h: 330, prof: 'Ms Ruth Okafor', comps: {
    SEM: [['A', '02', '12:00', '13:15', 'Library 4'], ['B', '13', '15:00', '16:15', 'Library 4']] } },
  { id: 'econ', code: 'ECON 105', title: 'Environmental Economics', cr: 3, h: 95, prof: 'Dr Sam Whitlow', comps: {
    LEC: [['A', '13', '12:00', '13:15', 'Pell 20'], ['B', '024', '10:00', '10:50', 'Pell 20']] } },
  { id: 'biol', code: 'BIOL 220', title: 'Plant Physiology', cr: 4, h: 128, prof: 'Dr Hana Kurz', comps: {
    LEC: [['A', '02', '10:30', '11:45', 'Gale 5'], ['B', '13', '14:30', '15:45', 'Gale 5']],
    LAB: [['1', '0', '14:00', '16:50', 'Greenhouse'], ['2', '3', '09:00', '11:50', 'Greenhouse']] } },
  { id: 'outd', code: 'OUTD 110', title: 'Field Skills', cr: 1, h: 70, prof: 'Mr Ivo Brandt', comps: {
    FLD: [['A', '4', '08:00', '11:50', 'Boathouse'], ['B', '2', '13:00', '16:50', 'Boathouse']] } },
  { id: 'math', code: 'MATH 160', title: 'Calculus for Life Sciences', cr: 4, h: 285, prof: 'Dr Lena Fisk', comps: {
    LEC: [['A', '024', '09:00', '09:50', 'Quarry 1'], ['B', '13', '16:30', '17:45', 'Quarry 1']],
    TUT: [['1', '1', '11:00', '11:50', 'Quarry 3'], ['2', '3', '11:00', '11:50', 'Quarry 3']] } },
  { id: 'span', code: 'LANG 101', title: 'Spanish I', cr: 3, h: 15, prof: 'Sra. Paloma Gil', comps: {
    LEC: [['A', '024', '08:00', '08:50', 'Arts 9'], ['B', '13', '08:00', '09:15', 'Arts 9']] } },
];
const C = Object.fromEntries(COURSES.map(c => [c.id, c]));
const MIN_CR = 15, MAX_CR = 18;
const sec = (id, comp, name) => C[id].comps[comp].find(s => s[0] === name);
