const S = {
  sel: { envs: { LEC: 'A', LAB: '3' }, chem: { LEC: 'A', LAB: '1' }, stat: { LEC: 'A', TUT: '2' }, geog: { LEC: 'A', LAB: '2' }, writ: { SEM: 'B' } },
  q: '', view: 'week', day: 0, solver: null, cons: { early: false, fri: false, lunch: false }, picker: null, ghost: null, registered: null,
};
const undo = [], redo = [];

/* ── derived state ───────────────────────────────────────── */
const plan = () => S.solver && S.solver.opts.length ? S.solver.opts[S.solver.i].sel : S.sel;
function allMeets(sel = plan()) { const out = []; for (const id in sel) for (const comp in sel[id]) out.push(...meets(id, comp, sel[id][comp])); return out; }
const overlap = (a, b) => a.d === b.d && a.s < b.e && b.s < a.e;
function clashes(sel = plan()) {
  const m = allMeets(sel), out = [];
  for (let i = 0; i < m.length; i++) for (let j = i + 1; j < m.length; j++) if (overlap(m[i], m[j]) && !(m[i].id === m[j].id && m[i].comp === m[j].comp)) out.push([m[i], m[j]]);
