}
const credits = (sel = plan()) => Object.keys(sel).reduce((a, id) => a + C[id].cr, 0);
function metrics(sel) {
  const m = allMeets(sel), days = new Set(m.map(x => x.d));
  let gaps = 0, hours = 0, early = 1440;
  DAYS.forEach((_, d) => {
    const ms = m.filter(x => x.d === d).sort((a, b) => a.s - b.s); if (!ms.length) return;
    early = Math.min(early, ms[0].s);
    let end = ms[0].e; hours += ms[0].e - ms[0].s;
    for (let k = 1; k < ms.length; k++) { if (ms[k].s > end) gaps += ms[k].s - end; end = Math.max(end, ms[k].e); hours += ms[k].e - ms[k].s; }
  });
  return { days: days.size, gaps, hours, early: early === 1440 ? null : early, perDay: DAYS.map((_, d) => m.filter(x => x.d === d).reduce((a, x) => a + x.e - x.s, 0)) };
}

/* ── solver ───────────────────────────────────────── */
function rulesOk(m, cons) {
  if (cons.early && m.s < 600) return false;
  if (cons.fri && m.d === 4) return false;
  if (cons.lunch && m.s < 780 && m.e > 720) return false;
