    if (k === slots.length) { const sel = {}; slots.forEach(sl => { (sel[sl.id] = sel[sl.id] || {})[sl.comp] = pick[sl.id + sl.comp]; }); found.push(sel); return; }
    const sl = slots[k];
    for (const name of sl.opts) {
