    '<p><b>' + c.code + '</b><em>' + m.comp + ' ' + m.name + '</em></p><span>' + esc(c.title) + '</span><small>' + hm(m.s) + '–' + hm(m.e) + ' · ' + esc(s[4]) + '</small></button>';
