  h += '<div class="ale-timetable-hours" style="grid-column:1;grid-row:2">' + Array.from({ length: 11 }, (_, k) => '<span style="top:calc(' + k + ' * var(--ale-timetable-hour))">' + (8 + k) + ':00</span>').join('') + '</div>';
