@property --ale-reading-g { syntax: '<number>'; inherits: true; initial-value: 0; }

.ale-reading {
  /* re-theme with these four */
  --ale-reading-bg: oklch(0.205 0.028 15);
  --ale-reading-ink: oklch(0.93 0.015 75);
  --ale-reading-accent: oklch(0.8 0.11 82);
  --ale-reading-wood: oklch(0.43 0.065 55);
  /* derived */
  --ale-reading-panel: color-mix(in oklab, var(--ale-reading-bg) 90%, var(--ale-reading-ink));
  --ale-reading-raise: color-mix(in oklab, var(--ale-reading-bg) 84%, var(--ale-reading-ink));
  --ale-reading-line: color-mix(in oklab, var(--ale-reading-ink) 10%, transparent);
  --ale-reading-line2: color-mix(in oklab, var(--ale-reading-ink) 18%, transparent);
  --ale-reading-mute: color-mix(in oklab, var(--ale-reading-ink) 62%, var(--ale-reading-bg));
  --ale-reading-faint: color-mix(in oklab, var(--ale-reading-ink) 36%, var(--ale-reading-bg));
  --ale-reading-hover: color-mix(in oklab, var(--ale-reading-ink) 7%, transparent);
  --ale-reading-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ale-reading-serif: ui-serif, "New York", Charter, Georgia, serif;
  --ale-reading-mono: ui-monospace, Menlo, Consolas, monospace;
  --ale-reading-ease: cubic-bezier(.2, .8, .2, 1);
  --ale-reading-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.03 43%, 1.005 55%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ale-reading-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ale-reading-bg); color: var(--ale-reading-ink); color-scheme: dark; accent-color: var(--ale-reading-accent);
  font: 13px/1.45 var(--ale-reading-sans); border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ale-reading-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h1, & h2, & h3, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; font: inherit; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--ale-reading-mono); padding: 2px 4px; display: inline-block; border: 1px solid var(--ale-reading-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--ale-reading-faint); }
}
.ale-reading .ale-reading-app { height: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 316px; grid-template-rows: auto minmax(0, 1fr) auto; grid-template-areas: "top top" "main book" "nav nav"; }

/* ── top ─────────────────────────────── */
.ale-reading .ale-reading-top { grid-area: top; display: flex; align-items: center; gap: 18px; padding: 12px 18px; border-bottom: 1px solid var(--ale-reading-line); }
