  & button { border: 0; background: none; height: 30px; padding: 0 13px; border-radius: 8px; font-weight: 600; font-size: 12.5px; color: var(--ale-reading-mute); display: inline-flex; gap: 7px; align-items: center; }
  & button:hover { color: var(--ale-reading-ink); }
