  & span { font-size: 12px; color: var(--ale-reading-mute); font-variant-numeric: tabular-nums; }
}
.ale-reading .ale-reading-sort {
  margin-left: auto; display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--ale-reading-line);
  & button { border: 0; background: none; height: 26px; padding: 0 10px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--ale-reading-mute); }
  & button[aria-checked="true"] { background: var(--ale-reading-accent); color: var(--ale-reading-bg); }
}
.ale-reading .ale-reading-now { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 14px; margin-bottom: 30px; }
.ale-reading .ale-reading-cur {
  --i: 0;
  display: grid; grid-template-columns: auto 1fr; gap: 14px; padding: 12px; border-radius: 14px; background: var(--ale-reading-panel); border: 1px solid var(--ale-reading-line);
  text-align: left; animation: ale-reading-rise .5s var(--ale-reading-ease) both; animation-delay: calc(var(--i) * 70ms);
  transition: border-color .2s, background .2s;
  &:hover { border-color: var(--ale-reading-line2); }
  &[aria-pressed="true"] { border-color: var(--ale-reading-accent); }
  & .ale-reading-meta { display: grid; align-content: start; gap: 3px; min-width: 0; }
  & .ale-reading-meta b { font: 600 15px/1.2 var(--ale-reading-serif); text-wrap: balance; }
  & .ale-reading-meta span { font-size: 12px; color: var(--ale-reading-mute); }
  & .ale-reading-bar { margin-top: 10px; height: 6px; border-radius: 3px; background: var(--ale-reading-line); overflow: hidden; }
  & .ale-reading-bar i { display: block; height: 100%; width: calc(var(--p) * 100%); background: var(--ale-reading-accent); border-radius: 3px; transition: width .7s var(--ale-reading-spring); }
  & small { font: 500 11px var(--ale-reading-mono); color: var(--ale-reading-faint); font-variant-numeric: tabular-nums; }
}
@keyframes ale-reading-rise { from { opacity: 0; transform: translateY(8px); } }
.ale-reading .ale-reading-cover {
  --sc: oklch(0.5 0.1 30);
  position: relative; width: 82px; aspect-ratio: 2 / 3; border-radius: 3px 6px 6px 3px; overflow: hidden; display: grid; align-content: space-between; padding: 9px 8px 8px 12px;
  background: linear-gradient(to right, color-mix(in oklab, var(--sc) 70%, black) 0 5px, color-mix(in oklab, var(--sc) 85%, white) 6px, var(--sc) 40%, color-mix(in oklab, var(--sc) 85%, black));
  box-shadow: 0 10px 22px -10px oklch(0 0 0 / .8), inset 0 0 0 1px oklch(1 0 none / .08);
  color: var(--tc, white);
  & b { font: 650 10.5px/1.15 var(--ale-reading-serif); text-wrap: balance; }
  & span { font-size: 8px; letter-spacing: .1em; text-transform: uppercase; opacity: .8; }
  &::after { content: ""; position: absolute; left: 12px; right: 8px; top: 50%; height: 1px; background: currentColor; opacity: .35; }
}

.ale-reading .ale-reading-shelf { display: grid; gap: 34px; padding-bottom: 14px; }
.ale-reading .ale-reading-row {
  position: relative; display: flex; align-items: flex-end; gap: 3px; padding: 0 18px; min-height: 236px; perspective: 1100px; perspective-origin: 50% 30%;
  &::before { content: ""; position: absolute; left: 0; right: 0; top: -10px; bottom: 0; border-radius: 6px 6px 0 0; background: linear-gradient(to bottom, oklch(0 0 0 / .18), oklch(0 0 0 / .32)); z-index: -1; }
  &::after {
    content: ""; position: absolute; left: -6px; right: -6px; bottom: -15px; height: 15px; border-radius: 2px 2px 4px 4px; z-index: 2;
    background: linear-gradient(to bottom, color-mix(in oklab, var(--ale-reading-wood) 80%, white) 0 2px, var(--ale-reading-wood) 2px 60%, color-mix(in oklab, var(--ale-reading-wood) 70%, black));
    box-shadow: 0 12px 18px -8px oklch(0 0 0 / .7);
  }
}
.ale-reading .ale-reading-end { width: 16px; height: 70px; flex: none; align-self: flex-end; background: linear-gradient(to right, color-mix(in oklab, var(--ale-reading-accent) 60%, black), var(--ale-reading-accent) 40%, color-mix(in oklab, var(--ale-reading-accent) 55%, black)); clip-path: polygon(0 100%, 0 25%, 35% 0, 100% 0, 100% 100%); opacity: .85; }
.ale-reading .ale-reading-end.is-r { transform: scaleX(-1); margin-left: auto; }
.ale-reading .ale-reading-spine {
  --sc: oklch(0.5 0.1 30); --w: 30px; --ht: 200px;
  position: relative; flex: none; width: var(--w); height: var(--ht); border: 0; padding: 0; border-radius: 2px 2px 1px 1px; transform-style: preserve-3d; transform-origin: 50% 100%;
  background: linear-gradient(to right, color-mix(in oklab, var(--sc) 72%, black) 0, color-mix(in oklab, var(--sc) 88%, white) 30%, var(--sc) 62%, color-mix(in oklab, var(--sc) 70%, black) 100%);
  color: var(--tc, white); box-shadow: inset 0 1px 0 oklch(1 0 none / .15);
  transition: transform .55s var(--ale-reading-spring), filter .25s;
  &::before { content: ""; position: absolute; left: 0; right: 0; top: 12px; height: 5px; border-block: 1px solid color-mix(in oklab, var(--ale-reading-accent) 70%, transparent); }
  &::after { content: ""; position: absolute; left: 0; right: 0; bottom: 14px; height: 5px; border-block: 1px solid color-mix(in oklab, var(--ale-reading-accent) 70%, transparent); }
  & .ale-reading-st { position: absolute; left: 0; right: 0; top: 26px; bottom: 50px; display: grid; place-items: center; overflow: hidden; }
  & .ale-reading-st b { writing-mode: vertical-rl; font: 600 10.5px/1 var(--ale-reading-serif); letter-spacing: .04em; white-space: nowrap; max-height: 100%; overflow: hidden; text-overflow: ellipsis; }
  & .ale-reading-sa { position: absolute; left: 0; right: 0; bottom: 24px; text-align: center; font: 700 7.5px var(--ale-reading-sans); letter-spacing: .08em; text-transform: uppercase; opacity: .75; }
  & .ale-reading-cv {
    position: absolute; left: 100%; top: 0; width: var(--cw); height: 100%; transform-origin: 0 50%; transform: rotateY(90deg); backface-visibility: hidden;
    background: linear-gradient(to right, color-mix(in oklab, var(--sc) 60%, black), var(--sc) 30%); display: grid; place-items: center; padding: 12px; text-align: center;
    font: 600 12px/1.2 var(--ale-reading-serif); color: var(--tc, white); opacity: 0; transition: opacity .4s;
  }
  &:hover { transform: translateY(-6px); filter: brightness(1.08); }
  &.is-out .ale-reading-cv { opacity: 1; }
  &.is-out { transform: translateY(-20px) rotateY(-38deg); z-index: 4; filter: brightness(1.1) drop-shadow(0 18px 18px oklch(0 0 0 / .5)); }
  &.is-new { animation: ale-reading-shelve .9s var(--ale-reading-spring) both; }
}
@keyframes ale-reading-shelve { from { transform: translateY(-60px) rotate(-8deg); opacity: 0; } }
.ale-reading .ale-reading-hint { margin-top: 26px; font-size: 11.5px; color: var(--ale-reading-faint); }

/* ── year ─────────────────────────────── */
.ale-reading .ale-reading-stats { display: grid; gap: 16px; }
.ale-reading .ale-reading-kpis {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px;
  & div { --i: 0; padding: 12px 14px; border-radius: 14px; background: var(--ale-reading-panel); border: 1px solid var(--ale-reading-line); animation: ale-reading-rise .5s var(--ale-reading-ease) both; animation-delay: calc(var(--i) * 60ms); }
  & b { display: block; font: 600 26px/1.1 var(--ale-reading-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & span { font-size: 11.5px; color: var(--ale-reading-mute); }
  & em { font-style: normal; color: var(--ale-reading-accent); }
}
.ale-reading .ale-reading-card {
  padding: 14px 16px; border-radius: 14px; background: var(--ale-reading-panel); border: 1px solid var(--ale-reading-line);
  & header { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; margin-bottom: 10px; }
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-reading-mute); }
  & header span { font-size: 11.5px; color: var(--ale-reading-faint); }
  & svg { width: 100%; height: auto; display: block; overflow: visible; }
}
.ale-reading .ale-reading-two { display: grid; grid-template-columns: 1.3fr 1fr; gap: 16px; }
.ale-reading .ale-reading-pace {
  & .ale-reading-gl { stroke: var(--ale-reading-line); stroke-width: 1; }
  & .ale-reading-ax { fill: var(--ale-reading-faint); stroke: none; font: 600 9px var(--ale-reading-mono); }
  & .ale-reading-goalline { stroke: var(--ale-reading-mute); stroke-width: 1.5; stroke-dasharray: 4 4; fill: none; }
  & .ale-reading-act { stroke: var(--ale-reading-accent); stroke-width: 2.5; fill: none; stroke-linejoin: round; stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: ale-reading-draw 1.2s var(--ale-reading-ease) forwards; }
  & .ale-reading-proj { stroke: var(--ale-reading-accent); stroke-width: 1.5; stroke-dasharray: 2 4; fill: none; opacity: .7; }
  & .ale-reading-area { fill: color-mix(in oklab, var(--ale-reading-accent) 12%, transparent); stroke: none; }
  & .ale-reading-dot { fill: var(--ale-reading-accent); stroke: var(--ale-reading-panel); stroke-width: 2; }
  & .ale-reading-lbl { fill: var(--ale-reading-ink); stroke: none; font: 650 10px var(--ale-reading-sans); }
}
@keyframes ale-reading-draw { to { stroke-dashoffset: 0; } }
/* cards rise into place as the year view scrolls inside its own pane */
@supports (animation-timeline: view()) {
  .ale-reading .ale-reading-stats .ale-reading-card { animation: ale-reading-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
@keyframes ale-reading-reveal { from { opacity: 0; transform: translateY(22px) scale(.985); } }
.ale-reading .ale-reading-months {
  display: grid; grid-template-columns: repeat(12, 1fr); gap: 4px; align-items: end; height: 124px;
  & div { display: grid; grid-template-rows: auto 1fr auto; height: 100%; gap: 3px; text-align: center; }
  & div b { font: 600 9px var(--ale-reading-mono); color: var(--ale-reading-mute); }
  & div i { align-self: end; display: block; height: calc(var(--v) * 100%); min-height: 2px; border-radius: 3px 3px 1px 1px; background: var(--ale-reading-accent); transform-origin: bottom; animation: ale-reading-grow .6s var(--ale-reading-spring) both; animation-delay: calc(var(--i) * 35ms); transition: height .5s var(--ale-reading-spring); }
  & div.is-future i { background: var(--ale-reading-line); }
  & div.is-now i { background: linear-gradient(to top, var(--ale-reading-accent), color-mix(in oklab, var(--ale-reading-accent) 50%, white)); }
  & small { font: 600 9px var(--ale-reading-mono); color: var(--ale-reading-faint); }
}
@keyframes ale-reading-grow { from { transform: scaleY(0); } }
.ale-reading .ale-reading-heat {
  display: grid; grid-template-rows: repeat(7, 1fr); grid-auto-flow: column; grid-auto-columns: 1fr; gap: 2px;
  & i { aspect-ratio: 1; border-radius: 2px; background: color-mix(in oklab, var(--ale-reading-accent) calc(var(--l) * 100%), var(--ale-reading-line)); }
  & i.is-out { background: transparent; }
  & i.is-future { background: none; box-shadow: inset 0 0 0 1px var(--ale-reading-line); }
  & i.is-today { box-shadow: 0 0 0 1.5px var(--ale-reading-ink); }
}
.ale-reading .ale-reading-heatx { display: flex; justify-content: space-between; margin-top: 6px; font: 600 9px var(--ale-reading-mono); color: var(--ale-reading-faint); }
.ale-reading .ale-reading-genres {
  display: grid; gap: 8px;
  & div { display: grid; grid-template-columns: 74px 1fr 24px; gap: 8px; align-items: center; font-size: 12px; }
  & div i { height: 8px; border-radius: 4px; background: var(--ale-reading-line); overflow: hidden; display: block; }
  & div i u { display: block; height: 100%; width: calc(var(--v) * 100%); background: var(--c); border-radius: 4px; text-decoration: none; transition: width .5s var(--ale-reading-ease); }
  & div span { font: 600 11px var(--ale-reading-mono); color: var(--ale-reading-mute); text-align: right; }
}

/* ── queue ─────────────────────────────── */
.ale-reading .ale-reading-queue ol { display: grid; gap: 8px; max-width: 640px; }
.ale-reading .ale-reading-q {
  display: grid; grid-template-columns: 22px auto 1fr auto; gap: 12px; align-items: center; padding: 10px 12px 10px 8px; border-radius: 14px; background: var(--ale-reading-panel); border: 1px solid var(--ale-reading-line);
  touch-action: none;
  & .ale-reading-grip { color: var(--ale-reading-faint); cursor: grab; display: grid; place-items: center; height: 100%; }
  & .ale-reading-grip svg { width: 16px; height: 16px; }
  & .ale-reading-cover { width: 44px; padding: 5px 4px 4px 7px; }
  & .ale-reading-cover b { font-size: 6.5px; }
  & .ale-reading-cover span, & .ale-reading-cover::after { display: none; }
  & .ale-reading-qt b { display: block; font: 600 14px/1.25 var(--ale-reading-serif); }
  & .ale-reading-qt span { font-size: 12px; color: var(--ale-reading-mute); }
  & .ale-reading-qa { display: flex; gap: 4px; }
  &.is-drag { box-shadow: 0 16px 34px -12px oklch(0 0 0 / .8); border-color: var(--ale-reading-accent); position: relative; z-index: 3; }
}
.ale-reading .ale-reading-pos { font: 700 12px var(--ale-reading-mono); color: var(--ale-reading-faint); }
.ale-reading .ale-reading-btn {
  height: 32px; padding: 0 12px; border-radius: 9px; border: 1px solid var(--ale-reading-line2); background: none; font-size: 12px; font-weight: 650; display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
  transition: border-color .15s, background .15s, transform .25s var(--ale-reading-spring);
  & svg { width: 15px; height: 15px; }
  &:hover:not(:disabled) { border-color: var(--ale-reading-mute); background: var(--ale-reading-hover); }
  &:active:not(:disabled) { transform: scale(.95); }
  &.is-pri { background: var(--ale-reading-accent); border-color: var(--ale-reading-accent); color: var(--ale-reading-bg); }
}
.ale-reading .ale-reading-ib { width: 32px; height: 32px; border: 0; border-radius: 9px; background: none; display: grid; place-items: center; color: var(--ale-reading-mute); &:hover:not(:disabled) { background: var(--ale-reading-hover); color: var(--ale-reading-ink); } }

/* ── book panel ─────────────────────────────── */
.ale-reading .ale-reading-book { grid-area: book; overflow: auto; min-height: 0; padding: 18px 18px 22px; border-left: 1px solid var(--ale-reading-line); background: var(--ale-reading-panel); display: flex; flex-direction: column; gap: 16px; scrollbar-width: thin; & > * { flex: none; } }
.ale-reading .ale-reading-bh {
  display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: end; animation: ale-reading-rise .45s var(--ale-reading-ease) both;
  & .ale-reading-cover { width: 96px; }
  & > div > p { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-reading-accent); }
  & h2 { font: 600 20px/1.15 var(--ale-reading-serif); letter-spacing: -.01em; text-wrap: balance; margin: 2px 0 3px; }
  & > div > span { font-size: 12.5px; color: var(--ale-reading-mute); }
}
.ale-reading .ale-reading-facts {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--ale-reading-line);
  & div { background: var(--ale-reading-raise); padding: 9px 10px; display: grid; }
  & b { font-size: 15px; font-weight: 700; font-variant-numeric: tabular-nums; }
  & span { font-size: 10.5px; color: var(--ale-reading-mute); }
}
.ale-reading .ale-reading-stars {
  display: flex; align-items: center; gap: 2px;
  & button { width: 30px; height: 30px; border: 0; background: none; display: grid; place-items: center; color: var(--ale-reading-line2); border-radius: 7px; transition: color .15s, transform .3s var(--ale-reading-spring); }
  & button svg { width: 20px; height: 20px; fill: currentColor; stroke: none; }
  & button.is-on { color: var(--ale-reading-accent); }
  & button:hover { transform: scale(1.15); }
  & span { margin-left: 6px; font-size: 12px; color: var(--ale-reading-mute); }
}
.ale-reading .ale-reading-quote { font: italic 14px/1.5 var(--ale-reading-serif); color: color-mix(in oklab, var(--ale-reading-ink) 85%, var(--ale-reading-bg)); padding-left: 12px; border-left: 2px solid var(--ale-reading-accent); text-wrap: pretty; }
.ale-reading .ale-reading-prog {
  display: grid; gap: 6px;
  & div { display: flex; justify-content: space-between; font-size: 12px; color: var(--ale-reading-mute); font-variant-numeric: tabular-nums; }
  & div b { color: var(--ale-reading-ink); }
  & i { height: 8px; border-radius: 4px; background: var(--ale-reading-line); overflow: hidden; display: block; }
  & i u { display: block; height: 100%; width: calc(var(--p) * 100%); border-radius: 4px; background: var(--ale-reading-accent); text-decoration: none; transition: width .7s var(--ale-reading-spring); }
}
.ale-reading .ale-reading-log {
  display: grid; gap: 10px; padding: 12px; border-radius: 12px; background: var(--ale-reading-raise); border: 1px solid var(--ale-reading-line);
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-reading-mute); }
  & .ale-reading-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  & label { display: grid; gap: 4px; font-size: 11px; color: var(--ale-reading-mute); }
  & .ale-reading-step { display: flex; align-items: center; border-radius: 9px; border: 1px solid var(--ale-reading-line2); overflow: hidden; }
  & .ale-reading-step:focus-within { border-color: var(--ale-reading-accent); }
  & .ale-reading-step button { width: 30px; height: 32px; border: 0; background: none; font-size: 15px; color: var(--ale-reading-mute); }
  & .ale-reading-step button:hover:not(:disabled) { background: var(--ale-reading-hover); color: var(--ale-reading-ink); }
  & input { width: 100%; min-width: 0; height: 32px; border: 0; outline: 0; background: none; text-align: center; font: 650 14px var(--ale-reading-mono); font-variant-numeric: tabular-nums; }
  & input[aria-invalid="true"] { color: oklch(0.72 0.15 25); }
  & .ale-reading-err { font-size: 11.5px; color: oklch(0.75 0.14 25); min-height: 1em; }
  & .ale-reading-err:empty { display: none; }
}
.ale-reading .ale-reading-sess {
  display: grid; gap: 2px;
  & li { display: flex; justify-content: space-between; font-size: 12px; padding: 5px 2px; border-bottom: 1px solid var(--ale-reading-line); color: var(--ale-reading-mute); font-variant-numeric: tabular-nums; }
  & li b { color: var(--ale-reading-ink); font-weight: 600; }
  & li.is-new { animation: ale-reading-rise .5s var(--ale-reading-ease) both; color: var(--ale-reading-accent); }
}
.ale-reading .ale-reading-sec h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--ale-reading-mute); margin-bottom: 6px; }
.ale-reading .ale-reading-back { display: none; align-self: flex-start; border: 0; background: none; padding: 4px 6px 4px 2px; font-size: 12px; font-weight: 600; color: var(--ale-reading-mute); align-items: center; gap: 4px; border-radius: 7px; & svg { width: 15px; height: 15px; } }

/* toast, nav */
.ale-reading .ale-reading-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; translate: -50% 16px; display: flex; align-items: center; gap: 12px;
  padding: 8px 8px 8px 14px; border-radius: 12px; background: var(--ale-reading-ink); color: var(--ale-reading-bg); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 34px -14px oklch(0 0 0 / .8); opacity: 0; visibility: hidden; transition: opacity .25s, translate .4s var(--ale-reading-spring), visibility 0s .4s;
  & button { border: 0; border-radius: 8px; padding: 5px 10px; background: color-mix(in oklab, var(--ale-reading-bg) 12%, transparent); font-weight: 700; font-size: 12px; color: var(--ale-reading-bg); }
  &.is-on { opacity: 1; visibility: visible; translate: -50% 0; transition: opacity .25s, translate .4s var(--ale-reading-spring), visibility 0s; }
  &:not(.has-undo) button { display: none; }
}
.ale-reading .ale-reading-nav {
  grid-area: nav; display: none; padding: 4px 6px 6px; border-top: 1px solid var(--ale-reading-line); background: var(--ale-reading-panel);
  & button { flex: 1; border: 0; background: none; display: grid; justify-items: center; gap: 2px; padding: 6px 4px; border-radius: 10px; font-size: 11px; font-weight: 600; color: var(--ale-reading-mute); }
  & button svg { width: 20px; height: 20px; }
  & button[aria-selected="true"] { color: var(--ale-reading-accent); background: var(--ale-reading-hover); }
}

/* ── responsive ─────────────────────────────── */
@container (max-width: 1080px) {
  .ale-reading .ale-reading-app { grid-template-columns: minmax(0, 1fr) 288px; }
  .ale-reading .ale-reading-kpis { grid-template-columns: repeat(2, 1fr); }
  .ale-reading .ale-reading-two { grid-template-columns: 1fr; }
}
@container (max-width: 759px) {
  .ale-reading .ale-reading-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "nav"; }
  .ale-reading .ale-reading-nav { display: flex; }
  .ale-reading .ale-reading-tabs { display: none; }
  .ale-reading .ale-reading-book { grid-area: main; border-left: 0; }
  .ale-reading:not([data-view="book"]) .ale-reading-book, .ale-reading[data-view="book"] .ale-reading-main { display: none; }
  .ale-reading .ale-reading-back { display: inline-flex; }
  .ale-reading .ale-reading-goal { margin-left: auto; }
  .ale-reading .ale-reading-main { padding: 14px 14px 20px; }
  .ale-reading .ale-reading-row { padding: 0 8px; }
  .ale-reading .ale-reading-sort { margin-left: 0; }
}
@container (max-width: 460px) {
  .ale-reading .ale-reading-brand small, .ale-reading .ale-reading-goal span { display: none; }
  .ale-reading .ale-reading-kpis b { font-size: 21px; }
  .ale-reading .ale-reading-q { grid-template-columns: 18px 1fr auto; & .ale-reading-cover { display: none; } }
  .ale-reading .ale-reading-now { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  .ale-reading *, .ale-reading *::before, .ale-reading *::after { animation-duration: 1ms !important; animation-delay: 0s !important; transition-duration: 1ms !important; }
  .ale-reading .ale-reading-spine.is-out { transform: translateY(-14px); }
  .ale-reading .ale-reading-pace .ale-reading-act { stroke-dashoffset: 0; animation: none !important; }
  .ale-reading .ale-reading-stats .ale-reading-card { animation: none !important; }
}

