const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const TODAY = 274;                                  /* day of year: Friday 2 October 2026 */
const date = d => { const t = new Date(Date.UTC(2026, 0, 1 + d)); return t.getUTCDate() + ' ' + MON[t.getUTCMonth()]; };
const monthOf = d => new Date(Date.UTC(2026, 0, 1 + d)).getUTCMonth();
const GOAL = 24;
const I = {
  star: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3.2 2.7 5.6 6.1.8-4.5 4.2 1.1 6.1L12 17l-5.4 2.9 1.1-6.1-4.5-4.2 6.1-.8z"/></svg>',
  grip: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6h.01M15 6h.01M9 12h.01M15 12h.01M9 18h.01M15 18h.01" stroke-width="3"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  up: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 14 6-6 6 6"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 6-6 6 6 6"/></svg>',
  play: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4.5h10.5a2 2 0 0 1 2 2V20H7a2 2 0 0 1-2-2z"/><path d="M5 18a2 2 0 0 1 2-2h10.5"/></svg>',
};
const GENRES = { Fiction: 'oklch(0.8 0.11 82)', Science: 'oklch(0.72 0.1 200)', History: 'oklch(0.66 0.12 30)', Nature: 'oklch(0.74 0.12 140)', Poetry: 'oklch(0.72 0.1 340)', Essays: 'oklch(0.75 0.06 260)', Travel: 'oklch(0.78 0.1 110)' };
/* [title, author, pages, genre, [l, c, h], spine height, start, end, rating, note] */
const RAW = [
  ['The Salt Orchard', 'Mirela Voss', 312, 'Fiction', [0.55, 0.09, 200], 206, 1, 13, 4, 'The orchard keeper never says the sea is coming. Everyone else does.'],
  ['A Field Guide to Small Weather', 'Tomasz Erlund', 228, 'Nature', [0.66, 0.08, 95], 184, 14, 26, 4, 'Fog has a grammar. I will never see a morning the same way.'],
  ['Ledger of Lost Rivers', 'Ama Quarshie', 401, 'History', [0.42, 0.08, 250], 226, 28, 47, 5, 'Cities are built on rivers they then pretend not to have.'],
  ['Night Ferry to Halde', 'Jun Takara', 264, 'Fiction', [0.35, 0.05, 285], 196, 48, 57, 3, 'Slow first half, a last chapter I read twice.'],
  ['The Patient Engine', 'Corin Abara', 356, 'Science', [0.58, 0.13, 40], 214, 59, 76, 4, 'Steam power was mostly about waiting well.'],
  ['Copper and Lime', 'Hester Gale', 198, 'Poetry', [0.7, 0.1, 135], 176, 78, 87, 5, '“The kettle keeps the house’s time.”'],
  ['Under the Glass Roof', 'Rafael Montoya', 344, 'Fiction', [0.6, 0.07, 180], 210, 91, 113, 4, 'A greenhouse, three sisters and one terrible winter.'],
  ['How Bridges Remember', 'Lena Ostrova', 289, 'Science', [0.5, 0.03, 60], 200, 120, 134, 4, 'Every bridge carries a record of every load it has borne.'],
  ['The Quiet Census', 'Noor Bakri', 412, 'History', [0.4, 0.1, 20], 222, 135, 150, 5, 'Who gets counted decides who gets served.'],
  ['Moths of the Lower Valley', 'Peter Ashdown', 176, 'Nature', [0.78, 0.05, 85], 172, 152, 159, 3, 'Lovely drawings; the text wanders.'],
  ['Small Gods of the Kitchen', 'Delphine Arcand', 240, 'Essays', [0.6, 0.12, 350], 188, 161, 170, 4, 'The essay on bread starters made me start one.'],
  ['A Map Drawn in Chalk', 'Ilse Marr', 318, 'Fiction', [0.7, 0.04, 240], 204, 171, 180, 5, 'Best thing I read this year. Gave a copy to Mum.'],
  ['Feral Arithmetic', 'Kofi Mensah-Lund', 272, 'Science', [0.55, 0.12, 145], 194, 183, 196, 4, 'Crows can count to five and so, mostly, can I.'],
  ['Winter Inventory', 'Saskia Holm', 152, 'Poetry', [0.86, 0.02, 250], 170, 198, 204, 4, 'Short poems that take a long time.'],
  ['The Long Way Through Ostend', 'Bram Verloo', 386, 'Travel', [0.48, 0.1, 230], 218, 212, 230, 3, 'Too many trains, not enough Ostend.'],
  ['Notes from the Allotment', 'Gwen Abernathy', 214, 'Essays', [0.58, 0.1, 110], 182, 231, 241, 4, 'Patience, slugs and the politics of a shared shed.'],
  ['The Ninth Lighthouse', 'Owen Tallis', 330, 'Fiction', [0.66, 0.14, 60], 208, 244, 263, 4, 'Read the last 80 pages in one sitting on the train.'],
  ['Glass Harvest', 'Yara Okafor', 448, 'Fiction', [0.55, 0.11, 305], 224, 256, null, null, ''],
  ['The Measure of Tides', 'Henrik Solberg', 296, 'Science', [0.5, 0.08, 210], 198, 268, null, null, ''],
  ['Atlas of Unwalked Paths', 'Marisol Peña', 260, 'Travel', [0.66, 0.1, 70], 192, null, null, null, ''],
  ['Bread and Brimstone', 'Aurelio Cann', 334, 'History', [0.45, 0.1, 30], 212, null, null, null, ''],
  ['The Hum of Hives', 'Tamsin Ware', 208, 'Nature', [0.74, 0.12, 92], 180, null, null, null, ''],
  ['Ordinary Comets', 'Felix Haugen', 372, 'Fiction', [0.4, 0.06, 262], 216, null, null, null, ''],
  ['Seven Rooms of Rain', 'Leila Morrow', 186, 'Poetry', [0.6, 0.06, 222], 174, null, null, null, ''],
];
const AT = { 17: 212, 18: 61 };
let B = RAW.map((r, i) => ({ id: i, title: r[0], author: r[1], pages: r[2], genre: r[3], col: 'oklch(' + r[4].join(' ') + ')', tc: r[4][0] > 0.68 ? 'oklch(0.26 0.04 ' + r[4][2] + ')' : 'oklch(0.97 0.012 ' + r[4][2] + ')', hue: r[4][2], light: r[4][0], ht: r[5], start: r[6], end: r[7], rating: r[8], note: r[9] }));
let QUEUE = [19, 20, 21, 22, 23];

/* one log of sessions drives everything; past sessions are generated from each book's dates */
let SESS = (() => {
  let s = 20260101; const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const out = [];
  B.forEach(b => {
    if (b.start == null) return;
    const cur = b.end == null, last = cur ? TODAY - 1 : b.end, days = [];
    for (let d = b.start; d <= last; d++) if (cur || d === b.start || d === last || rnd() < 0.78) days.push(d);
    const total = cur ? AT[b.id] : b.pages, w = days.map(() => 0.5 + rnd()), ws = w.reduce((a, x) => a + x, 0);
    let left = total;
    days.forEach((d, k) => { const p = k === days.length - 1 ? left : Math.max(1, Math.round(total * w[k] / ws)); left -= p; out.push({ b: b.id, d, p, min: Math.round(p * 1.7 + rnd() * 12) }); });
  });
  return out;
})();
const read = id => SESS.filter(x => x.b === id).reduce((a, x) => a + x.p, 0);

const S = { view: 'shelf', sort: 'date', sel: 17, newShelved: null, freshSess: null, rowsW: 0 };
let undoFn = null;

/* ── derived ───────────────────────────────────────── */
const finished = () => B.filter(b => b.end != null).sort((a, b) => a.end - b.end);
const current = () => B.filter(b => b.start != null && b.end == null);
function perDay() { const a = new Array(365).fill(0); SESS.forEach(x => { a[x.d] += x.p; }); return a; }
function streaks(pd) {
  let cur = 0; for (let d = pd[TODAY] ? TODAY : TODAY - 1; d >= 0 && pd[d] > 0; d--) cur++;
  let best = 0, run = 0; for (let d = 0; d <= TODAY; d++) { run = pd[d] > 0 ? run + 1 : 0; best = Math.max(best, run); }
  return { cur, best, today: pd[TODAY] > 0 };
}

/* ── shelf ───────────────────────────────────────── */
const shelfEl = $('[data-shelf]');
const spineW = b => Math.round(14 + b.pages / 12);
function sorted() {
  const f = finished();
  if (S.sort === 'hue') return f.sort((a, b) => (a.light > 0.8) - (b.light > 0.8) || a.hue - b.hue || a.light - b.light);
  if (S.sort === 'pages') return f.sort((a, b) => b.pages - a.pages);
  if (S.sort === 'author') return f.sort((a, b) => a.author.split(' ').pop().localeCompare(b.author.split(' ').pop()));
  return f;
}
const short = n => n.split(' ').pop().slice(0, 7);
function spineHTML(b) {
  const out = S.sel === b.id;
  return '<button type="button" role="option" class="ale-reading-spine' + (out ? ' is-out' : '') + (S.newShelved === b.id ? ' is-new' : '') + '" data-book="' + b.id + '" aria-selected="' + out + '" tabindex="-1" style="--sc:' + b.col + ';--tc:' + b.tc + ';--w:' + spineW(b) + 'px;--ht:' + b.ht + 'px;--cw:' + Math.round(b.ht * 0.66) + 'px" aria-label="' + esc(b.title + ' by ' + b.author + ', ' + b.pages + ' pages, finished ' + date(b.end)) + '" title="' + esc(b.title + ' — ' + b.author) + '">' +
    '<span class="ale-reading-st"><b>' + esc(b.title) + '</b></span><span class="ale-reading-sa">' + esc(short(b.author)) + '</span><span class="ale-reading-cv" aria-hidden="true">' + esc(b.title) + '</span></button>';
}
function renderShelf(flip) {
  const first = flip ? new Map($$('.ale-reading-spine', shelfEl).map(e => [e.dataset.book, e.getBoundingClientRect()])) : null;
  const avail = Math.max(200, shelfEl.clientWidth - 36 - 40);
  S.rowsW = shelfEl.clientWidth;
  const rows = [[]]; let w = 0;
  sorted().forEach(b => { const bw = spineW(b) + 3; if (w + bw > avail && rows[rows.length - 1].length) { rows.push([]); w = 0; } rows[rows.length - 1].push(b); w += bw; });
  shelfEl.innerHTML = rows.map((r, k) => '<div class="ale-reading-row">' + (k === 0 ? '<i class="ale-reading-end" aria-hidden="true"></i>' : '') + r.map(spineHTML).join('') + (k === rows.length - 1 ? '<i class="ale-reading-end is-r" aria-hidden="true"></i>' : '') + '</div>').join('');
  const sp = $$('.ale-reading-spine', shelfEl), f = sp.find(x => x.getAttribute('aria-selected') === 'true') || sp[0];
  if (f) f.tabIndex = 0;
  $('[data-fincount]').textContent = finished().length + ' books · ' + finished().reduce((a, b) => a + b.pages, 0).toLocaleString('en-GB') + ' pages';
  S.newShelved = null;
  if (!first || RM.matches) return;
  sp.forEach(e => {
    const a = first.get(e.dataset.book); if (!a) return;
    const l = e.getBoundingClientRect(), dx = a.left - l.left, dy = a.top - l.top; if (!dx && !dy) return;
    e.animate([{ translate: dx + 'px ' + dy + 'px' }, { translate: '0 0' }], { duration: 650, easing: 'cubic-bezier(.2,.85,.25,1)', delay: Math.min(240, Math.abs(dx) / 4) });
  });
}
function coverHTML(b) { return '<span class="ale-reading-cover" style="--sc:' + b.col + ';--tc:' + b.tc + '" aria-hidden="true"><b>' + esc(b.title) + '</b><span>' + esc(b.author) + '</span></span>'; }
function renderNow() {
  const cs = current();
  $('[data-nowcount]').textContent = cs.length ? cs.length + ' book' + (cs.length === 1 ? '' : 's') + ' on the go' : 'nothing on the go';
  $('[data-now]').innerHTML = cs.length ? cs.map((b, k) => { const r = read(b.id); return '<button type="button" class="ale-reading-cur" data-book="' + b.id + '" aria-pressed="' + (S.sel === b.id) + '" style="--i:' + k + '">' + coverHTML(b) + '<span class="ale-reading-meta"><b>' + esc(b.title) + '</b><span>' + esc(b.author) + '</span><span class="ale-reading-bar"><i style="--p:' + (r / b.pages).toFixed(3) + '"></i></span><small>page ' + r + ' of ' + b.pages + ' · ' + Math.round(100 * r / b.pages) + '%</small><small>since ' + date(b.start) + '</small></span></button>'; }).join('')
    : '<p style="color:var(--ale-reading-faint);font-size:12.5px">Start something from Up next.</p>';
}
function renderGoal() {
  const n = finished().length, pct = Math.round(100 * n / GOAL), expected = GOAL * (TODAY + 1) / 365, diff = n - expected;
  $('[data-goalmini]').innerHTML = '<svg viewBox="0 0 36 36" aria-hidden="true" style="--ale-reading-g:' + pct + '"><circle cx="18" cy="18" r="15" pathLength="100"/><circle cx="18" cy="18" r="15" pathLength="100"/></svg><div><b>' + n + '/' + GOAL + '</b> <span>' + (Math.abs(diff) < 0.5 ? 'on pace' : diff > 0 ? Math.round(diff) + ' ahead of pace' : Math.round(-diff) + ' behind pace') + '</span></div>';
}

/* ── year view ───────────────────────────────────────── */
function renderStats() {
  const pd = perDay(), st = streaks(pd), fin = finished(), n = fin.length;
  const total = pd.reduce((a, b) => a + b, 0), avg = total / (TODAY + (st.today ? 1 : 0));
  const months = MON.map((_, m) => pd.reduce((a, v, d) => a + (monthOf(d) === m ? v : 0), 0)), mmax = Math.max(...months);
  const booksBy = MON.map((_, m) => fin.filter(b => monthOf(b.end) === m).length);
  /* pace chart */
  const W = 520, H = 190, L = 28, R = 10, T = 12, Bt = 24, x = d => L + (W - L - R) * d / 364, y = v => H - Bt - (H - Bt - T) * v / GOAL;
  let step = 'M' + x(0) + ' ' + y(0), c = 0, len = 0, px = x(0), py = y(0);
  fin.forEach(b => { step += ' H' + x(b.end).toFixed(1); len += x(b.end) - px; px = x(b.end); c++; step += ' V' + y(c).toFixed(1); len += py - y(c); py = y(c); });
  step += ' H' + x(TODAY).toFixed(1); len += x(TODAY) - px;
  const proj = n / (TODAY + 1) * 365;
  const grid = [0, 6, 12, 18, 24].map(v => '<line class="ale-reading-gl" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(v) + '" y2="' + y(v) + '"/><text class="ale-reading-ax" x="' + (L - 6) + '" y="' + (y(v) + 3) + '" text-anchor="end">' + v + '</text>').join('') +
    MON.map((m, k) => '<text class="ale-reading-ax" x="' + x(Math.round(k * 30.4 + 15)) + '" y="' + (H - 8) + '" text-anchor="middle">' + m[0] + '</text>').join('');
  const svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" class="ale-reading-pace" role="img" aria-label="Books finished through the year against the goal of ' + GOAL + '">' + grid +
    '<line class="ale-reading-goalline" x1="' + x(0) + '" y1="' + y(0) + '" x2="' + x(364) + '" y2="' + y(GOAL) + '"/>' +
    '<path class="ale-reading-area" d="' + step + ' V' + y(0) + ' Z"/><path class="ale-reading-act" d="' + step + '" style="--len:' + Math.ceil(len) + '"/>' +
    '<line class="ale-reading-proj" x1="' + x(TODAY) + '" y1="' + y(n) + '" x2="' + x(364) + '" y2="' + y(Math.min(GOAL + 2, proj)) + '"/>' +
    '<circle class="ale-reading-dot" cx="' + x(TODAY) + '" cy="' + y(n) + '" r="5"/><text class="ale-reading-lbl" x="' + (x(TODAY) - 8) + '" y="' + (y(n) - 10) + '" text-anchor="end">' + n + ' today</text>' +
    '<text class="ale-reading-lbl" x="' + (x(364) - 2) + '" y="' + (y(Math.min(GOAL + 2, proj)) - 8) + '" text-anchor="end" style="fill:var(--ale-reading-mute)">on course for ' + Math.round(proj) + '</text></svg>';
  /* heatmap: weeks from Sunday 28 Dec 2025 */
  const startPad = 4, cells = [];
  for (let k = 0; k < 53 * 7; k++) { const d = k - startPad; cells.push(d < 0 || d > 364 ? '<i class="is-out"></i>' : d > TODAY ? '<i class="is-future"></i>' : '<i class="' + (d === TODAY ? 'is-today' : '') + '" style="--l:' + (pd[d] ? Math.min(1, 0.25 + Math.ceil(pd[d] / 15) * 0.19) : 0).toFixed(2) + '" title="' + date(d) + ': ' + pd[d] + ' pages"></i>'); }
  const genres = Object.keys(GENRES).map(g => [g, fin.filter(b => b.genre === g).length]).sort((a, b) => b[1] - a[1]), gmax = Math.max(...genres.map(g => g[1]));
  $('[data-pane="stats"]').innerHTML =
    '<div class="ale-reading-kpis"><div style="--i:0"><b>' + n + '<em> / ' + GOAL + '</em></b><span>books finished</span></div><div style="--i:1"><b>' + total.toLocaleString('en-GB') + '</b><span>pages this year</span></div><div style="--i:2"><b>' + avg.toFixed(1) + '</b><span>pages a day</span></div><div style="--i:3"><b>' + st.cur + '</b><span>day streak · best ' + st.best + '</span></div></div>' +
    '<section class="ale-reading-card"><header><h3>Pace</h3><span>dashed line is the goal of ' + GOAL + '</span></header>' + svg + '</section>' +
    '<div class="ale-reading-two"><section class="ale-reading-card"><header><h3>Pages by month</h3><span>' + MON[monthOf(TODAY)] + ' so far</span></header><div class="ale-reading-months">' + months.map((v, m) => '<div class="' + (m > monthOf(TODAY) ? 'is-future' : m === monthOf(TODAY) ? 'is-now' : '') + '" style="--i:' + m + '" title="' + MON[m] + ': ' + v + ' pages, ' + booksBy[m] + ' finished"><b>' + (v || '') + '</b><i style="--v:' + (v / mmax).toFixed(3) + '"></i><small>' + MON[m][0] + '</small></div>').join('') + '</div></section>' +
    '<section class="ale-reading-card"><header><h3>Genres</h3><span>' + n + ' books</span></header><div class="ale-reading-genres">' + genres.map(([g, v]) => '<div><span style="text-align:left;color:var(--ale-reading-ink);font-family:var(--ale-reading-sans)">' + g + '</span><i><u style="--v:' + (v / gmax).toFixed(3) + ';--c:' + GENRES[g] + '"></u></i><span>' + v + '</span></div>').join('') + '</div></section></div>' +
    '<section class="ale-reading-card"><header><h3>Every day of 2026</h3><span>' + (st.today ? 'today counts' : 'nothing logged today yet') + '</span></header><div class="ale-reading-heat" role="img" aria-label="Pages read per day in 2026">' + cells.join('') + '</div><div class="ale-reading-heatx">' + MON.map(m => '<span>' + m + '</span>').join('') + '</div></section>';
}

/* ── queue ───────────────────────────────────────── */
function renderQueue(flipFrom) {
  $('[data-qcount]').textContent = QUEUE.length + ' waiting · ' + QUEUE.reduce((a, id) => a + B[id].pages, 0).toLocaleString('en-GB') + ' pages';
  $('[data-queue]').innerHTML = QUEUE.length ? QUEUE.map((id, k) => { const b = B[id]; return '<li class="ale-reading-q" data-qid="' + id + '" tabindex="0" aria-label="' + esc(b.title + ', number ' + (k + 1) + ' of ' + QUEUE.length + '. Alt and arrow keys reorder.') + '"><span class="ale-reading-grip" aria-hidden="true">' + I.grip + '</span>' + coverHTML(b) +
    '<span class="ale-reading-qt"><b>' + esc(b.title) + '</b><span>' + esc(b.author) + ' · ' + b.pages + ' pages · ' + b.genre + '</span></span><span class="ale-reading-qa"><button type="button" class="ale-reading-ib" data-qup="' + id + '" aria-label="Move up"' + (k === 0 ? ' disabled title="Already first"' : '') + '>' + I.up + '</button><button type="button" class="ale-reading-btn" data-start="' + id + '">' + I.play + 'Start</button><button type="button" class="ale-reading-ib" data-qdel="' + id + '" aria-label="Remove ' + esc(b.title) + '">' + I.x + '</button></span></li>'; }).join('')
    : '<li style="color:var(--ale-reading-faint);font-size:12.5px">The pile is empty — a rare and dangerous state.</li>';
  if (!flipFrom || RM.matches) return;
  $$('.ale-reading-q').forEach(e => { const f = flipFrom.get(e.dataset.qid); if (f == null) return; const dy = f - e.getBoundingClientRect().top; if (dy) e.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.2,.8,.2,1)' }); });
}
const qRects = () => new Map($$('.ale-reading-q').map(e => [e.dataset.qid, e.getBoundingClientRect().top]));
function moveQ(id, d) { const k = QUEUE.indexOf(id), j = k + d; if (k < 0 || j < 0 || j >= QUEUE.length) return; const f = qRects(); QUEUE.splice(k, 1); QUEUE.splice(j, 0, id); renderQueue(f); const el = $('[data-qid="' + id + '"]'); if (el) el.focus({ preventScroll: true }); }

/* ── book panel ───────────────────────────────────────── */
const bookEl = $('[data-book]');
let draft = { pages: 24, min: 35, err: '' };
function renderBook() {
  const b = B[S.sel];
  if (!b) { bookEl.innerHTML = '<p style="color:var(--ale-reading-faint)">Pick a book from the shelf.</p>'; return; }
  const sess = SESS.filter(x => x.b === b.id), r = read(b.id), state = b.end != null ? 'fin' : b.start != null ? 'cur' : 'queue';
  let h = '<button type="button" class="ale-reading-back" data-act="backshelf">' + I.back + 'Shelf</button><header class="ale-reading-bh">' + coverHTML(b) + '<div><p>' + (state === 'fin' ? 'Finished ' + date(b.end) : state === 'cur' ? 'Reading now' : 'Up next · #' + (QUEUE.indexOf(b.id) + 1)) + '</p><h2>' + esc(b.title) + '</h2><span>' + esc(b.author) + ' · ' + b.genre + '</span></div></header>';
  if (state === 'fin') {
    const days = b.end - b.start + 1;
    h += '<div class="ale-reading-facts"><div><b>' + b.pages + '</b><span>pages</span></div><div><b>' + days + '</b><span>days</span></div><div><b>' + Math.round(b.pages / days) + '</b><span>pages a day</span></div></div>' +
      '<div class="ale-reading-stars" role="radiogroup" aria-label="Your rating">' + [1, 2, 3, 4, 5].map(k => '<button type="button" role="radio" class="' + (k <= (b.rating || 0) ? 'is-on' : '') + '" data-rate="' + k + '" aria-checked="' + (k === b.rating) + '" aria-label="' + k + ' star' + (k > 1 ? 's' : '') + '" tabindex="' + (k === (b.rating || 1) ? 0 : -1) + '">' + I.star + '</button>').join('') + '<span>' + (b.rating ? ['', 'Not for me', 'It was fine', 'Good', 'Really good', 'A favourite'][b.rating] : 'Rate it') + '</span></div>' +
      (b.note ? '<p class="ale-reading-quote">' + esc(b.note) + '</p>' : '') +
      '<section class="ale-reading-sec"><h3>How it went</h3><p style="font-size:12.5px;color:var(--ale-reading-mute);text-wrap:pretty">' + sess.length + ' sittings between ' + date(b.start) + ' and ' + date(b.end) + ', about ' + Math.round(sess.reduce((a, x) => a + x.min, 0) / 60) + ' hours in all. The longest sitting was ' + Math.max(...sess.map(x => x.p)) + ' pages.</p></section>';
  } else if (state === 'cur') {
    const left = b.pages - r;
    h += '<div class="ale-reading-prog" style="--p:' + (r / b.pages).toFixed(3) + '"><div><span>page <b>' + r + '</b> of ' + b.pages + '</span><span>' + Math.round(100 * r / b.pages) + '%</span></div><i><u></u></i><div><span>' + left + ' pages left</span><span>about ' + Math.max(1, Math.round(left / Math.max(1, r / Math.max(1, sess.length)))) + ' more sittings</span></div></div>' +
      '<form class="ale-reading-log" data-log><h3>Log today’s reading</h3><div class="ale-reading-fields"><label>Pages read<span class="ale-reading-step"><button type="button" data-step="pages:-5" aria-label="5 fewer pages">−</button><input type="text" inputmode="numeric" data-f="pages" value="' + draft.pages + '"' + (draft.err ? ' aria-invalid="true"' : '') + ' aria-label="Pages read"><button type="button" data-step="pages:5" aria-label="5 more pages">+</button></span></label>' +
      '<label>Minutes<span class="ale-reading-step"><button type="button" data-step="min:-5" aria-label="5 fewer minutes">−</button><input type="text" inputmode="numeric" data-f="min" value="' + draft.min + '" aria-label="Minutes"><button type="button" data-step="min:5" aria-label="5 more minutes">+</button></span></label></div>' +
      '<p class="ale-reading-err" role="alert">' + esc(draft.err) + '</p><button type="submit" class="ale-reading-btn is-pri" style="justify-content:center;height:36px">Log ' + Math.max(0, Math.min(left, +draft.pages || 0)) + ' pages → page ' + Math.min(b.pages, r + Math.max(0, +draft.pages || 0)) + '</button>' +
      '<button type="button" class="ale-reading-btn" data-act="finishbook" style="justify-content:center">I finished it</button></form>' +
      '<section class="ale-reading-sec"><h3>Recent sittings</h3><ul class="ale-reading-sess">' + sess.slice(-5).reverse().map(x => '<li class="' + (S.freshSess === x ? 'is-new' : '') + '"><span>' + (x.d === TODAY ? 'Today' : date(x.d)) + '</span><span><b>' + x.p + '</b> pages · ' + x.min + ' min</span></li>').join('') + '</ul></section>';
  } else {
    h += '<div class="ale-reading-facts"><div><b>' + b.pages + '</b><span>pages</span></div><div><b>' + Math.round(b.pages / 22) + '</b><span>days at your pace</span></div><div><b>#' + (QUEUE.indexOf(b.id) + 1) + '</b><span>in the pile</span></div></div>' +
      '<button type="button" class="ale-reading-btn is-pri" data-start="' + b.id + '" style="justify-content:center;height:38px">' + I.play + 'Start reading today</button>';
  }
  bookEl.innerHTML = h;
  S.freshSess = null;
}

function renderAll(flip) { renderGoal(); renderNow(); renderShelf(flip); if (S.view === 'stats') renderStats(); renderQueue(); renderBook(); }

/* ── actions ───────────────────────────────────────── */
let toastT = 0;
function toast(msg, undo) { const t = $('[data-toast]'); $('[data-toastmsg]').textContent = msg; undoFn = undo || null; t.classList.toggle('has-undo', !!undo); t.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => { t.classList.remove('is-on'); undoFn = null; }, 4200); }
const snapshot = () => ({ B: JSON.parse(JSON.stringify(B)), SESS: SESS.map(x => ({ ...x })), QUEUE: QUEUE.slice(), sel: S.sel });
const restore = s => { B = s.B; SESS = s.SESS; QUEUE = s.QUEUE; S.sel = s.sel; renderAll(true); };
function select(id, opts = {}) {
  S.sel = S.sel === id && opts.toggle ? null : id;
  if (S.sel == null) S.sel = current()[0] ? current()[0].id : finished()[0].id;
  $$('.ale-reading-spine', shelfEl).forEach(e => { const on = +e.dataset.book === S.sel; e.classList.toggle('is-out', on); e.setAttribute('aria-selected', on); });
  $$('.ale-reading-cur').forEach(e => e.setAttribute('aria-pressed', +e.dataset.book === S.sel));
  renderBook();
  if (opts.show && $('.ale-reading-nav').offsetParent) setView('book');
}
function logSession(e) {
  e.preventDefault();
  const b = B[S.sel], r = read(b.id), left = b.pages - r, p = Math.round(+draft.pages), m = Math.round(+draft.min);
  if (!isFinite(p) || p < 1) { draft.err = 'Log at least one page.'; return renderBook(); }
  if (p > left) { draft.err = 'Only ' + left + ' pages are left in this book.'; return renderBook(); }
  if (!isFinite(m) || m < 1 || m > 600) { draft.err = 'Minutes should be between 1 and 600.'; return renderBook(); }
  const snap = snapshot(), was = streaks(perDay()).cur;
  draft.err = '';
  const s = { b: b.id, d: TODAY, p, min: m }; SESS.push(s); S.freshSess = s;
  if (p === left) return finishBook(b, snap);
  renderAll(false);
  const now = streaks(perDay()).cur;
  toast(p + ' pages logged — page ' + (r + p) + ' of ' + b.pages + (now > was ? ' · streak ' + now + ' days' : ''), () => { restore(snap); toast('Session removed'); });
}
function finishBook(b, snap) {
  snap = snap || snapshot();
  const r = read(b.id); if (r < b.pages) SESS.push({ b: b.id, d: TODAY, p: b.pages - r, min: Math.round((b.pages - r) * 1.7) });
  b.end = TODAY; b.rating = null; S.newShelved = b.id; S.sort = 'date'; syncSort();
  renderAll(true);
  const n = finished().length;
  toast('Finished ' + b.title + ' — ' + n + ' of ' + GOAL + ' this year', () => { restore(snap); toast('Back on the reading pile'); });
}
function startBook(id) {
  const snap = snapshot(), b = B[id];
  QUEUE = QUEUE.filter(x => x !== id); b.start = TODAY; S.sel = id;
  renderAll(false);
  toast('Started ' + b.title, () => { restore(snap); toast('Back in Up next'); });
}
function setView(v) {
  S.view = v; root.dataset.view = v;
  $$('[role=tab][data-view]').forEach(t => { const on = t.dataset.view === v; t.setAttribute('aria-selected', on); if (t.closest('.ale-reading-tabs')) t.tabIndex = on ? 0 : -1; });
  $$('[data-pane]').forEach(p => { p.hidden = p.dataset.pane !== (v === 'book' ? 'shelf' : v); });
  if (v === 'stats') renderStats();
  if (v === 'shelf' && S.rowsW !== shelfEl.clientWidth) renderShelf(false);
  $('[data-main]').scrollTop = 0;
}
function syncSort() { $$('[data-sort]').forEach(b => { const on = b.dataset.sort === S.sort; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); }

/* ── events ───────────────────────────────────────── */
root.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t || !root.contains(t) || t.disabled) return;
  const a = t.dataset.act;
  if (t.dataset.book != null) return select(+t.dataset.book, { show: true });
  if (t.dataset.view && t.getAttribute('role') === 'tab') return setView(t.dataset.view);
  if (t.dataset.sort) { if (S.sort === t.dataset.sort) return renderShelf(false); S.sort = t.dataset.sort; syncSort(); return renderShelf(true); }
  if (t.dataset.rate) { const b = B[S.sel], k = +t.dataset.rate; b.rating = b.rating === k ? null : k; renderBook(); const f = $('[data-rate="' + k + '"]', bookEl); if (f) f.focus(); return toast(b.rating ? 'Rated ' + b.title + ' ' + k + ' out of 5' : 'Rating cleared'); }
  if (t.dataset.step) { const [f, d] = t.dataset.step.split(':'); draft[f] = clamp((Math.round(+draft[f]) || 0) + +d, 0, f === 'pages' ? 999 : 600); draft.err = ''; renderBook(); const again = $('[data-step="' + t.dataset.step + '"]', bookEl); if (again) again.focus(); return; }
  if (t.dataset.start != null) return startBook(+t.dataset.start);
  if (t.dataset.qup != null) return moveQ(+t.dataset.qup, -1);
  if (t.dataset.qdel != null) { const snap = snapshot(), id = +t.dataset.qdel, f = qRects(); QUEUE = QUEUE.filter(x => x !== id); renderQueue(f); if (S.sel === id) select(current()[0] ? current()[0].id : 0); return toast(B[id].title + ' removed from Up next', () => { restore(snap); toast('Back in the pile'); }); }
  if (a === 'finishbook') return finishBook(B[S.sel]);
  if (a === 'backshelf') return setView('shelf');
  if (a === 'toastundo') { $('[data-toast]').classList.remove('is-on'); const f = undoFn; undoFn = null; if (f) f(); }
});
bookEl.addEventListener('submit', e => { if (e.target.matches('[data-log]')) logSession(e); });
bookEl.addEventListener('input', e => { const f = e.target.dataset.f; if (!f) return; draft[f] = e.target.value.replace(/[^0-9]/g, ''); draft.err = ''; const btn = $('[data-log] [type="submit"]', bookEl), b = B[S.sel]; if (btn && b) { const r = read(b.id); btn.textContent = 'Log ' + Math.max(0, Math.min(b.pages - r, +draft.pages || 0)) + ' pages → page ' + Math.min(b.pages, r + (+draft.pages || 0)); } });

/* queue drag */
let drag = null;
root.addEventListener('pointerdown', e => {
  const g = e.target.closest('.ale-reading-grip'); if (!g || e.button !== 0) return;
  const li = g.closest('.ale-reading-q'), items = $$('.ale-reading-q'), rects = items.map(x => x.getBoundingClientRect());
  drag = { li, id: +li.dataset.qid, from: items.indexOf(li), to: items.indexOf(li), y0: e.clientY, step: rects.length > 1 ? rects[1].top - rects[0].top : rects[0].height + 8, items };
  items.forEach(x => { x.style.transition = 'transform .25s cubic-bezier(.2,.8,.2,1)'; }); li.style.transition = 'none'; li.classList.add('is-drag');
  li.setPointerCapture(e.pointerId); e.preventDefault();
});
root.addEventListener('pointermove', e => {
  if (!drag) return;
  const dy = e.clientY - drag.y0, n = drag.items.length;
  drag.to = clamp(Math.round(drag.from + dy / drag.step), 0, n - 1);
  drag.li.style.transform = 'translateY(' + clamp(dy, -drag.from * drag.step - 6, (n - 1 - drag.from) * drag.step + 6) + 'px)';
  drag.items.forEach((x, k) => { if (x === drag.li) return; const s = drag.to > drag.from && k > drag.from && k <= drag.to ? -1 : drag.to < drag.from && k < drag.from && k >= drag.to ? 1 : 0; x.style.transform = s ? 'translateY(' + s * drag.step + 'px)' : ''; });
});
const drop = () => {
  if (!drag) return; const d = drag; drag = null;
  const top = d.li.getBoundingClientRect().top;
  QUEUE.splice(d.from, 1); QUEUE.splice(d.to, 0, d.id); renderQueue();
  const el = $('[data-qid="' + d.id + '"]'); if (el && !RM.matches) { el.animate([{ transform: 'translateY(' + (top - el.getBoundingClientRect().top) + 'px)' }, { transform: 'none' }], { duration: 300, easing: 'cubic-bezier(.2,.8,.2,1)' }); }
  if (el) el.focus({ preventScroll: true });
  if (d.to !== d.from) toast(B[d.id].title + ' is now #' + (d.to + 1));
};
root.addEventListener('pointerup', drop);
root.addEventListener('pointercancel', drop);

root.addEventListener('keydown', e => {
  const tg = e.target, k = e.key;
  if (tg.matches('input')) { if (k === 'Escape') { tg.blur(); root.focus(); } return; }
  if (e.metaKey || e.ctrlKey) return;
  if (tg.matches('.ale-reading-q') && e.altKey && (k === 'ArrowUp' || k === 'ArrowDown')) { e.preventDefault(); return moveQ(+tg.dataset.qid, k === 'ArrowUp' ? -1 : 1); }
  if (e.altKey) return;
  if (tg.matches('.ale-reading-spine') && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(k)) {
    e.preventDefault(); const sp = $$('.ale-reading-spine', shelfEl), i = sp.indexOf(tg);
    const n = sp[k === 'Home' ? 0 : k === 'End' ? sp.length - 1 : clamp(i + (k === 'ArrowRight' ? 1 : -1), 0, sp.length - 1)];
    sp.forEach(x => x.tabIndex = x === n ? 0 : -1); n.focus(); return;
  }
  if (tg.matches('[data-sort]') && (k === 'ArrowLeft' || k === 'ArrowRight')) { e.preventDefault(); const o = ['date', 'hue', 'pages', 'author'], n = o[(o.indexOf(S.sort) + (k === 'ArrowRight' ? 1 : 3)) % 4]; S.sort = n; syncSort(); renderShelf(true); return $('[data-sort="' + n + '"]').focus(); }
  if (tg.matches('[data-rate]') && (k === 'ArrowLeft' || k === 'ArrowRight')) { e.preventDefault(); const b = B[S.sel]; b.rating = clamp((b.rating || 0) + (k === 'ArrowRight' ? 1 : -1), 1, 5); renderBook(); return $('[data-rate="' + b.rating + '"]', bookEl).focus(); }
  if (tg.closest('.ale-reading-tabs') && (k === 'ArrowLeft' || k === 'ArrowRight')) { e.preventDefault(); const o = ['shelf', 'stats', 'queue'], n = o[(o.indexOf(S.view === 'book' ? 'shelf' : S.view) + (k === 'ArrowRight' ? 1 : 2)) % 3]; setView(n); return $('.ale-reading-tabs [data-view="' + n + '"]').focus(); }
  if (k === '1' || k === '2' || k === '3') return setView(['shelf', 'stats', 'queue'][+k - 1]);
  if (k === 'l' || k === 'L') { const b = B[S.sel]; if (b && b.start != null && b.end == null) { e.preventDefault(); const f = $('[data-f="pages"]', bookEl); if ($('.ale-reading-nav').offsetParent) setView('book'); if (f) { f.focus(); f.select(); } } }
});

/* re-shelve when the shelf's width changes: rows are packed from real spine widths */
const ro = new ResizeObserver(() => {
  requestAnimationFrame(() => { if (!root.isConnected) { ro.disconnect(); return; } if (S.view === 'shelf' && shelfEl.clientWidth && Math.abs(shelfEl.clientWidth - S.rowsW) > 8) renderShelf(false); });
});
ro.observe(shelfEl);

renderAll(false);
